YH_EXAM_BANKS["LAW333-LEC"] = {"id":"LAW333-LEC","course":"LAW 333","short":"محاضرات الدكتور","lang":"ar","version":1,"los":[{"lo":"L1","ar":"مفهوم القانون التجاري وخصائصه ونطاقه ومصادره","en":""},{"lo":"L2","ar":"تمييز الأعمال التجارية: ضوابط التفرقة وأهميتها","en":""},{"lo":"L3","ar":"المحل التجاري","en":""},{"lo":"L4","ar":"الأعمال التجارية على وجه المقاولة وبالتبعية والأعمال المختلطة","en":""},{"lo":"L5","ar":"التاجر وشروط اكتساب صفة التاجر","en":""},{"lo":"L6","ar":"التزامات التاجر: مسك الدفاتر التجارية","en":""},{"lo":"L7","ar":"التزامات التاجر: القيد في السجل التجاري والغرفة التجارية","en":""},{"lo":"IMP","ar":"أسئلة الدكتور المهمة (الأوراق التجارية)","en":""}],"sections":{"LAW333-L1":{"ar":"المحاضرة الأولى — مفهوم القانون التجاري وخصائصه ونطاقه ومصادره"},"LAW333-L2":{"ar":"المحاضرة الثانية — تمييز الأعمال التجارية: ضوابط التفرقة وأهميتها"},"LAW333-L3":{"ar":"المحاضرة الثالثة — المحل التجاري"},"LAW333-L4":{"ar":"المحاضرة الرابعة — الأعمال التجارية على وجه المقاولة وبالتبعية والأعمال المختلطة"},"LAW333-L5":{"ar":"المحاضرة الخامسة — التاجر وشروط اكتساب صفة التاجر"},"LAW333-L6":{"ar":"المحاضرة السادسة — التزامات التاجر: مسك الدفاتر التجارية"},"LAW333-L7":{"ar":"المحاضرة السابعة — التزامات التاجر: القيد في السجل التجاري والغرفة التجارية"},"LAW333-PRAC":{"ar":"⭐ أسئلة الدكتور المهمة — قال إنها بتجي"}},"misconceptions":[{"id":"l1.theory-swap","ar":"تخلط بين النظرية الموضوعية والنظرية الشخصية","explain":"الموضوعية (المادية) العبرة فيها بالعمل بغض النظر عن الشخص، تاجر أو مدني.\nالشخصية (الذاتية) العبرة فيها بصفة التاجر المحترف بغض النظر عن طبيعة العمل.","fix":"راجع الشريحتين ١٢ و١٣، وثبّت المعادلة: موضوعية/مادية = العمل، شخصية/ذاتية = الشخص (التاجر).","coach":"أخوك يقول كلمة («العمل» أو «التاجر المحترف» أو «مادية» أو «ذاتية») وأنت ترد فوراً باسم النظرية الثاني ومعناها في جملة وحدة.","sec":"LAW333-L1"},{"id":"l1.critique-swap","ar":"تخلط انتقادات النظريتين ببعض","explain":"الموضوعية لها انتقاد واحد: صعوبة حصر الأعمال التجارية.\nالشخصية لها ثلاثة: صعوبة حصر المهن التجارية، تضييق النطاق على غير المحترفين، وإخضاع كل أعمال التاجر حتى الخارجة عن نشاطه.","fix":"الشريحتان ١٢–١٣؛ ركّز على الفرق بين «حصر الأعمال» (موضوعية) و«حصر المهن» (شخصية).","coach":"أخوك يقرأ انتقاد عشوائي وأنت تقول لأي نظرية ينتمي، وبعدين تعدّ انتقادات الشخصية الثلاثة بدون ما تطالع.","sec":"LAW333-L1"},{"id":"l1.saudi-approach","ar":"تحسب المنظم السعودي أخذ بنظرية وحدة وترك الثانية","explain":"المنظم أخذ بالموضوعية كأساس فعدّد الأعمال التجارية، لكن ما أهمل الشخصية: عرّف التاجر واعتد بصفته في بعض المسائل.\nوالسبب العيوب اللي ترد على النظريتين.","fix":"الشريحة ١٤ كاملة.","coach":"اشرح لأخوك مسلك النظام السعودي في ثلاث نقاط: وش الأساس، وش أخذ من النظرية الثانية، وليش.","sec":"LAW333-L1"},{"id":"l1.speed-credit-rules","ar":"تخلط بين القواعد اللي تدعم السرعة واللي تدعم الائتمان","explain":"السرعة تدعمها: حرية الإثبات، حماية الوضع الظاهر، انتقال الحقوق بالتظهير والتسليم.\nالائتمان يدعمه: افتراض التضامن بين المدينين بدين تجاري، والصرامة في نظام الإفلاس.","fix":"الشريحتان ٨ و١٠.","coach":"أخوك يقول قاعدة من الخمس وأنت تقول «سرعة» أو «ائتمان» خلال ثانيتين.","sec":"LAW333-L1"},{"id":"l1.speed-absolute","ar":"تظن إن السرعة تلغي أي شكلية في التصرفات التجارية","explain":"السرعة هي الأصل، لكن الشريحة تنبه إن المنظم اشترط شكلية في بعض التصرفات.\nمثل اشتراط الكتابة في عقد الشركة والأوراق التجارية.","fix":"ملاحظة الشريحة ٧.","coach":"أخوك يسألك: «هل كل تصرف تجاري بدون شكلية؟» ولازم ترد بـ«لا» وتذكر المثالين.","sec":"LAW333-L1"},{"id":"l1.credit-meaning","ar":"تحسب الائتمان هو التضامن أو مجرد «الثقة»","explain":"تعريف الائتمان: الأجل الممنوح للوفاء بالديون، والثقة المتبادلة هي الصورة اللي يبرزها.\nالتضامن والصرامة في الإفلاس قواعد تدعمه، مو تعريفه.","fix":"الشريحتان ٩–١٠.","coach":"قل التعريف بالكلمتين المفتاحيتين «الأجل» و«الوفاء بالديون»، ثم اشرح لأخوك ليش الديون المتسلسلة تخلي الائتمان ضروري.","sec":"LAW333-L1"},{"id":"l1.custom-vs-usage","ar":"تخلط بين العرف التجاري والعادات التجارية","explain":"العرف ملزم لاعتقاد التجار بإلزاميته، والقاضي يحكم به من تلقاء نفسه ويفترض العلم به.\nالعادات أقل درجة: من إرادة المتعاقدين فقط، تقتصر على أطرافها، وعلى من يدعيها عبء الإثبات.","fix":"الشريحتان ١٨–١٩ مع أمثلة كل واحد.","coach":"أخوك يذكر مثال (افتراض التضامن، الإعذار بأي وسيلة، حزم البضائع ووزنها) وأنت تصنّفه عرف أو عادة وتقول مين عليه الإثبات.","sec":"LAW333-L1"},{"id":"l1.custom-precedence","ar":"تلخبط أي عرف يغلب ومتى نرجع للعرف","explain":"العرف الخاص بتجارة معينة يغلب العام، والمحلي يغلب الشامل لأماكن متعددة.\nوالعرف كله ما يُصار إليه إلا في حالة غياب النص النظامي.","fix":"الشريحة ١٨ (النقطتين الثالثة والرابعة).","coach":"أخوك يعطيك عرفين متعارضين (خاص/عام أو محلي/شامل) وأنت تختار الغالب، وبعدين يسألك: «طيب لو فيه نص نظامي؟»","sec":"LAW333-L1"},{"id":"l1.judiciary-vs-fiqh","ar":"تخلط بين القضاء والفقه","explain":"القضاء = مبادئ استقرت عليها أحكام الجهات القضائية، يطبق النظام ويفسره، واستنبط دعوى المنافسة غير المشروعة وقواعد الشركة الفعلية.\nالفقه = آراء شراح القانون، يستخلص المبادئ ويبين النقص ويقدم الحلول، وأثّر في ظهور القانون الصرفي وقانون المنافسة.","fix":"الشريحتان ٢٠–٢١ والملاحظة اللي تحت.","coach":"أخوك يقول «المنافسة غير المشروعة» أو «قانون المنافسة» أو «الشركة الفعلية» أو «القانون الصرفي» وأنت تقول قضاء أو فقه.","sec":"LAW333-L1"},{"id":"l1.topics-scope","ar":"تخلط بين موضوعات القانون التجاري وموضوعات المقرر","explain":"القانون التجاري فيه ستة موضوعات رئيسية: الأعمال التجارية، التاجر، الشركات، الأوراق التجارية، الإفلاس، البحري والجوي.\nالمقرر يهتم بثلاثة منها بس: نظرية الأعمال التجارية، نظرية التاجر، الشركات.","fix":"الشريحتان ٤–٥.","coach":"عدّ الستة لأخوك، وهو يوقفك عند كل واحد ويسأل: «من مقررنا ولا لا؟»","sec":"LAW333-L1"},{"id":"l1.private-law","ar":"تظن القانون التجاري جزء من القانون المدني أو من القانون العام","explain":"القانون التجاري فرع مستقل من فروع القانون الخاص.\nوالقانون المدني على رأس فروع القانون الخاص، وهو في المملكة نظام المعاملات المدنية ١٤٤٤هـ.","fix":"الشريحة ٣ النقطة الثانية.","coach":"قل لأخوك جملة وحدة فيها الكلمات الثلاث: «مستقل»، «القانون الخاص»، «نظام المعاملات المدنية ١٤٤٤هـ».","sec":"LAW333-L1"},{"id":"l1.intl-mixup","ar":"تخلط بين الاتفاقيات الدولية والمنظمات وتفاصيلها","explain":"الاتفاقيات: باريس ١٨٨٣م، جنيف ١٩٣٠ و١٩٣١م، فيينا ١٩٨٠م (البيع والنقل الدولي)، روما (تنازع القوانين)، الجات، التريبس، ونموذجي اليونسيترال.\nالمنظمات: ICC، لجنة الأمم المتحدة لقانون التجارة الدولية (انضمام المملكة ١٤٢٤هـ)، فاتف (عبر مجلس التعاون وكعضو مراقب).","fix":"الشريحة ٢٣ بقسميها.","coach":"أخوك يقرأ اسم، وأنت تقول «اتفاقية» أو «منظمة» وتذكر سنة أو معلومة وحدة عنها.","sec":"LAW333-L1"},{"id":"l2.no-single-criterion","ar":"تظن أن فيه معياراً واحداً يكفي للتفريق","explain":"الشرائح واضحة: ما فيه معيار محدد، وكل معيار من الأربعة نتيجته «صحيح، لكنه لا يكفي لوحده».\nعشان كذا القوانين عدّدت الأعمال التجارية على سبيل المثال، واسترشدت بعدة معايير.","fix":"راجع الشريحة ٤، وسطر «النتيجة» في الشرائح ٥ إلى ٨، والخلاصة في الشريحة ٩.","coach":"اسأله: «معيار المضاربة صحيح؟» لازم يرد خلال ١٠ ثوانٍ: صحيح لكنه ما يكفي لوحده، ويذكر سبب نقده. كرّروا نفس السؤال مع المعايير الأربعة.","sec":"LAW333-L2"},{"id":"l2.criteria-mix","ar":"تخلط بين معاني المعايير الأربعة","explain":"لكل معيار كلمة مفتاحية: المضاربة = الربح، التداول = حركة السلع، المشروع = التنظيم، الحرفة = المهنة.\nإذا نسيت الكلمة، بتطبق معياراً غلطاً على السؤال.","fix":"سطر «المقصود بـ… هنا» في الشرائح ٥ إلى ٨.","coach":"قل له كلمة (ربح، حركة، تنظيم، مهنة)، وهو يرد باسم المعيار ومثاله: معارض السيارات، تجارة التجزئة، البنوك، المحلات اللي تحتاج أيدي عاملة.","sec":"LAW333-L2"},{"id":"l2.criteria-critique","ar":"تخلط نقد معيار بنقد معيار ثاني","explain":"المضاربة: المحامي والطبيب والمزارع يستهدفون الربح. التداول: الجمعيات التعاونية. المشروع: المكاتب الهندسية والعيادات، والشراء للبيع ولو مرة وحدة.\nالحرفة: يستبعد الأعمال المنفردة، ولا يوجد معيار محدد للحرفة.","fix":"سطر «نقد المعيار» في الشرائح ٥ إلى ٨.","coach":"اقرأ له مثال النقد فقط (مثلاً «العيادات الطبية» أو «المزارع»)، وهو يحدد أي معيار ينتقده.","sec":"LAW333-L2"},{"id":"l2.coop","ar":"تتلخبط في الجمعيات التعاونية","explain":"الجمعيات التعاونية تجي مرتين: في معيار المضاربة كمثال لعمل مو تجاري لأنها ما تستهدف الربح.\nوفي نقد معيار التداول، لأن فيها تداول ومع ذلك ما تكتسب الصفة التجارية.","fix":"الشريحة ٥ (وبهذا المعيار نعلم) والشريحة ٦ (نقد المعيار).","coach":"اسأله: «ليش الجمعية التعاونية مو تجارية مع إنها تبيع سلع؟» لازم يقول: لأنها تبيع بسعر التكلفة وما تستهدف الربح، وهذا نفسه نقد لمعيار التداول.","sec":"LAW333-L2"},{"id":"l2.courts","ar":"تخلط بين اختصاص المحاكم التجارية والمحاكم العامة","explain":"المحاكم التجارية: منازعات التجار، والدعاوى على التاجر في العقود التجارية فوق ١٠٠ ألف ريال، وشركاء شركة المضاربة، ونظام الشركات والإفلاس والملكية الفكرية.\nالمحاكم العامة: المنازعات المدنية، وكل ما يخرج عن اختصاص غيرها.","fix":"الشريحتان ١١ و١٢.","coach":"خلّه يعد بنود المحاكم التجارية الستة على أصابعه، وبعدها اعطه حالة وهو يحدد أي محكمة تختص بها.","sec":"LAW333-L2"},{"id":"l2.evidence-freedom","ar":"تظن أن الإثبات التجاري يحتاج كتابة دائماً، أو أنه حر بدون أي استثناء","explain":"الأصل في التجاري حرية الإثبات: شهادة أو قرائن أو أي وسيلة، وكذلك إثبات العكس، ما لم ينص النظام على غير ذلك.\nالاستثناءات اللي تُشترط فيها الكتابة أربعة: عقد الشركة، بيع السفينة أو حصة منها، الأوراق التجارية، الترخيص باستعمال العلامة التجارية.","fix":"الشريحتان ١٣ و١٤.","coach":"اطلب منه يعد الاستثناءات الأربعة. بعدها عدّها أنت ودخّل وحدة غلط (مثل عقد القرض)، وهو لازم يكتشفها.","sec":"LAW333-L2"},{"id":"l2.solidarity-reversed","ar":"تعكس قاعدة التضامن بين الدين المدني والتجاري","explain":"الدين المدني: لا تضامن إلا باتفاق أو نص. الدين التجاري: التضامن مفترض بالعرف، والدائن يطالب أي مدين بكامل الدين.\nنفي التضامن في التجاري يحتاج اتفاقاً لا يخالف النص، وفي شركة التضامن يكون الاتفاق على نفيه باطلاً.","fix":"الشريحة ١٥.","coach":"قل له «دين مدني» أو «دين تجاري»، وهو يرد بسرعة: التضامن مفترض أو يحتاج اتفاقاً أو نصاً؟","sec":"LAW333-L2"},{"id":"l2.notice-form","ar":"تطبق شكل الإعذار المدني على الدين التجاري","explain":"في الدين المدني يكون الإعذار بورقة رسمية تُعلن بواسطة أعوان القضاء، وفي الدين التجاري يصح بأي وسيلة ولو بخطاب عادي.\nإذا ما أعذر الدائن يُعتبر متسامحاً بالتأخير، وإذا أعذر صار المدين مقصراً ويتحمل ضرر التأخير.","fix":"الشريحة ١٦.","coach":"اسأله: «دائن أرسل لمدينه بدين تجاري خطاباً عادياً، يصح الإعذار؟» وبعدها اسأله نفس السؤال عن دين مدني.","sec":"LAW333-L2"},{"id":"l2.grace-period","ar":"تظن أن المهلة القضائية في الدين التجاري سهلة مثل المدني","explain":"في الدين المدني يقدر القاضي يعطي المدين نظرة الميسرة إذا عجز عن الوفاء واستدعت حالته ذلك، بشرط ما يتضرر الدائن ضرراً جسيماً.\nفي الدين التجاري ما تُعطى المهلة إلا في حدود ضيقة، واستثناءً بشروط محددة ومتشددة.","fix":"الشريحة ١٧.","coach":"خلّه يشرح لك «نظرة الميسرة» في جملة وحدة، وبعدها يقول الفرق في التجاري بكلمتين: «حدود ضيقة».","sec":"LAW333-L2"},{"id":"l2.bankruptcy-civil-debt","ar":"تظن أن أي توقف عن دفع دين يؤدي لإشهار إفلاس التاجر","explain":"الإفلاس نظام تجاري، وشرطه أن يتوقف التاجر عن دفع ديونه التجارية.\nإذا توقف عن دفع دين مدني ما يُشهر إفلاسه، حتى لو كان تاجراً.","fix":"الشريحة ١٨.","coach":"اعطه حالتين: تاجر توقف عن دين تجاري، وتاجر توقف عن دين مدني. يحكم في كل حالة ويذكر السبب.","sec":"LAW333-L2"},{"id":"l2.importance-list","ar":"تخلط بين جوانب أهمية التمييز والأمور اللي تحتها","explain":"أهمية التمييز في ثلاث جوانب: الاختصاص القضائي، والإثبات، وتنفيذ الالتزامات.\nوتحت تنفيذ الالتزامات أربعة أمور: التضامن، والإعذار، والمهلة القضائية، والإفلاس.","fix":"مخطط الشريحة ١٠.","coach":"خلّه يرسم الشكل من الذاكرة: ٣ مربعات فوق، و٤ مربعات تحت «تنفيذ الالتزامات».","sec":"LAW333-L2"},{"id":"l3.legis-def","ar":"تظن إن النظام السعودي عرّف المحل التجاري","explain":"الشريحة صريحة: ما فيه تعريف تشريعي للمحل التجاري في النظام السعودي.\nالتعريف الموجود فقهي: أداة يستخدمها التاجر وتتكون من عناصر مادية ومعنوية.","fix":"راجع شريحة 3: الفرق بين «التعريف التشريعي» و«التعريف الفقهي».","coach":"اسأله: «هل عرّف النظام السعودي المحل التجاري؟» يقول: لا، ثم يسرد التعريف الفقهي بكلماته في جملة واحدة.","sec":"LAW333-L3"},{"id":"l3.personality","ar":"تخلط بين المحل التجاري والشركة التجارية","explain":"الشركة التجارية لها شخصية معنوية، لكن المحل التجاري ما له.\nوالأثر: ما له ذمة مالية مستقلة ولا رأس مال مستقل. وكلمة «كيان مستقل» في التعريف ما تعني شخصية معنوية.","fix":"راجع الخاصية الرابعة في شريحة 4 وأثرها.","coach":"قل له: «شركة» أو «محل»، ويرد بسرعة: له شخصية معنوية؟ له ذمة مستقلة؟","sec":"LAW333-L3"},{"id":"l3.material-movable","ar":"تحسب المحل التجاري عقار أو منقول مادي","explain":"المحل مال منقول يخضع لنظام المنقولات، وهو تحديداً من المنقولات المعنوية.\nلأن قيمته الاقتصادية تُستمد أساساً من عناصره المعنوية مثل العملاء والسمعة والاسم والعلامة.","fix":"راجع أول خاصيتين في شريحة 4، ومثال هبة الأموال المنقولة.","coach":"اسأله: «تاجر وهب كل منقولاته، يدخل محله؟ وليش؟» ويذكر الخاصيتين.","sec":"LAW333-L3"},{"id":"l3.liberal-professions","ar":"تحسب عيادة الطبيب ومكتب المحامي محال تجارية","explain":"من خصائص المحل إنه يكتسب الصفة التجارية.\nفمكاتب المهن الحرة (طبيب، مهندس، محامي) مستبعدة لأن هذه المهن أعمال مدنية.","fix":"راجع خاصية «المحل التجاري يكتسب الصفة التجارية» في شريحة 4.","coach":"عدّد عليه أماكن (صيدلية تبيع، عيادة، مكتب محاماة، بقالة) ويقول هل هي محل تجاري مع السبب.","sec":"LAW333-L3"},{"id":"l3.theory-mixup","ar":"تخلط بين النظريات الثلاث وانتقاداتها","explain":"المجموع القانوني = ذمة مستقلة، ونُقدت لتعارضها مع وحدة الذمة المالية وعدم الشخصية المعنوية. المجموع الواقعي = عناصر منسّقة، ويؤخذ عليها إنها بلا مدلول قانوني.\nالملكية المعنوية = مال معنوي منقول في ذمة صاحبه، يحميه القانون بدعوى المنافسة غير المشروعة.","fix":"راجع شريحة 5 واربط كل نظرية بكلمة مفتاحية وبنقدها.","coach":"قل اسم النظرية ويرد بمضمونها في جملة ثم بنقدها، وبعدها اعكسها: قل النقد ويرد باسم النظرية.","sec":"LAW333-L3"},{"id":"l3.excluded-material","ar":"تحسب العقار والدفاتر تنتقل تلقائياً مع بيع المحل","explain":"العقار والدفاتر التجارية والمراسلات عناصر مادية مستبعدة.\nالعقار ينتقل بإفراغ رسمي عند كتابة العدل، والدفاتر ما تنتقل ملكيتها لكن يجوز نقلها طوعاً بالمناولة أو الترك.","fix":"راجع «العناصر المادية المستبعدة» في شريحة 6.","coach":"اسأله: «بعت محلي مع العمارة اللي هو فيها والدفاتر، وش ينتقل وكيف؟» ويفصّل كل واحد.","sec":"LAW333-L3"},{"id":"l3.debts","ar":"تحسب ديون المحل من عناصره عند البيع","explain":"الديون عنصر معنوي مستبعد: ما تُعتبر من عناصر المحل عند بيعه.\nحتى لو نشأت من استغلال المحل نفسه.","fix":"راجع شريحة 8 وانتبه لعبارة «حتى لو».","coach":"اسأله: «المحل عليه دين لمورد بسبب بضاعة المحل، بعته، الدين من عناصر المحل؟» ويجاوب مع ذكر «حتى لو».","sec":"LAW333-L3"},{"id":"l3.goods-vs-equipment","ar":"تخلط بين البضائع والمهام والمعدات","explain":"البضائع معدّة للبيع (ومعها المواد نصف المصنوعة والأولية).\nالمهام والمعدات تُستخدم لتيسير العمل وليست مخصصة للبيع، مثل الآلات والشاحنات والأثاث والحاسب.","fix":"راجع «العناصر المادية» في شريحة 6 والغرض من كل نوع.","coach":"في محل بن: حبوب البن، المكينة، سيارة التوصيل، الكراسي، أكياس القهوة المعبّأة. يصنّف كل وحدة بضاعة أو معدات.","sec":"LAW333-L3"},{"id":"l3.clientele-vs-goodwill","ar":"تخلط بين حق الاتصال بالعملاء والسمعة التجارية","explain":"حق الاتصال مع العملاء = الأشخاص اللي استقروا على التعامل مع المحل.\nالسمعة التجارية = قدرة المحل على جذب العملاء العرضيين بسبب موقعه أو اسمه أو علامته أو لأي سبب.","fix":"راجع أول عنصر وسابع عنصر في شريحة 7، والكلمتين: «استقروا» و«العرضيين».","coach":"اقرأ عليه حالة: «زبون كل يوم يجي» و«واحد مرّ صدفة وشاف المحل على الشارع العام»، ويحدد أي عنصر لكل واحد.","sec":"LAW333-L3"},{"id":"l3.name-vs-mark","ar":"تخلط بين الاسم التجاري والعلامة التجارية","explain":"الاسم التجاري تسمية للمحل نفسه تميّزه عن المتاجر المشابهة، ويُكتب في وثائقه كالعقود والسندات.\nالعلامة التجارية دلالات أو إشارات أو رموز يضعها التاجر على منتجاته.","fix":"راجع تعريفي الاسم التجاري والعلامات التجارية في شريحة 7.","coach":"اسأله: «اللي مكتوب على العقد والسند، واللي مطبوع على المنتج: أيهم اسم وأيهم علامة؟»","sec":"LAW333-L3"},{"id":"l3.single-entity","ar":"تظن إن تنظيم المحل ككيان واحد يلغي استقلال عناصره","explain":"النظام الواحد يخلّي التاجر يتصرف في المحل ككيان واحد بدل كل عنصر لحاله.\nلكن حسب التعريف الفقهي يبقى كل عنصر مستقل بذاته ويخضع لنظامه، مثل العلامات لنظام العلامات والأسماء لنظام الأسماء.","fix":"راجع آخر التعريف الفقهي و«أهمية تنظيم المحل التجاري» في شريحة 3.","coach":"اسأله سؤالين ورا بعض: «ليش ننظّم المحل بنظام واحد؟» ثم «طيب العلامة التجارية وش نظامها؟»","sec":"LAW333-L3"},{"id":"l4.single-vs-enterprise","ar":"تخلط بين العمل المنفرد والعمل على وجه المقاولة","explain":"بعض الأعمال الأصلية تصير تجارية ولو وقعت مرة وحدة، لكن أعمال المقاولة ما تصير تجارية إلا بتكرار واحتراف ومشروع منظم مستمر. عشان كذا المزاد العرضي غير المنتظم (مثل مزادات الجهات الحكومية على الأموال المصادرة) ما يعتبر تجاري.","fix":"راجع تعريف المقاولة في الشريحة 3، واستثناء المزايدات العرضية في الشريحة 9.","coach":"أخوك يذكر لك أعمال (مزاد مرة وحدة، شركة نقل منتظمة، مزاد حكومي على أموال مدين)، وأنت تسأل نفسك بصوت: فيه تكرار واحتراف ومشروع منظم؟ إذا لا، فهو مو مقاولة.","sec":"LAW333-L4"},{"id":"l4.list-exhaustive","ar":"تحسب قائمة المقاولات في المادة 2 قائمة مقفلة","explain":"المادة 2 من نظام المحكمة التجارية ذكرت سبع صور للمقاولة، لكن الشريحة نصت إنها واردة على سبيل المثال لا الحصر، يعني ممكن تكون فيه أعمال ثانية على وجه المقاولة.","fix":"راجع آخر سطر في الشريحة 3، واحفظ الصور السبع.","coach":"أخوك يقول: عدّ لي صور المقاولة في المادة 2. تعدها سبع، وبعدين يسألك: حصر ولا مثال؟ لازم تقول مثال لا حصر.","sec":"LAW333-L4"},{"id":"l4.craftsman-industry","ar":"تحسب الحرفي (الخياط، الحداد، الإسكافي) من مقاولة الصناعة","explain":"الصناعة (إنتاج، تحويل، إصلاح) تجارية بشرط توفر مقومات المشروع بقصد المضاربة والربح. الحرفي يعتمد على مهارته الشخصية، فعمله أقرب لبيع الإنتاج أو المهارة منه للمضاربة، فيخرج من نطاق الصناعة.","fix":"راجع الفقرة الأخيرة في الشريحة 4.","coach":"أخوك يذكر: مصنع زجاج، مطبعة، خياط، حداد، مصنع سيارات. أنت تقول لكل واحد: صناعة تجارية ولا حرفي خارج النطاق، ومع السبب.","sec":"LAW333-L4"},{"id":"l4.criterion-means","ar":"تظن إن تجارية المقاولة تتحدد بالوسيلة أو بمصدر السلعة","explain":"في النقل العبرة مو بالوسيلة (بر، بحر، جو) بل باحتراف النقل في مشروع منظم. وفي التوريد ما يشترط يسبقه شراء: توريد محاصيل زرعها أو أسماك صادها تجاري ما دام على وجه المقاولة.","fix":"راجع آخر نقطة في الشريحة 5، والشريحة 7.","coach":"أخوك يسألك: شركة نقل بحري تجارية؟ وشخص يورد سمك صاده بنفسه؟ جاوب بنفس المعيار: هل فيه مشروع منظم مستمر؟","sec":"LAW333-L4"},{"id":"l4.commission-vs-agency","ar":"تخلط بين الوكالة بالعمولة والوكالة العادية","explain":"الوكيل العادي يتصرف باسم موكله ولحسابه بموجب وكالة رسمية فما يكون طرف. الوكيل بالعمولة يتصرف باسمه الخاص لكن لحساب موكله بموجب عقد وكالة بالعمولة، وأجره اسمه عمولة.","fix":"راجع النقطة الثالثة في الشريحة 6.","coach":"أخوك يسألك سؤالين: باسم مين؟ ولحساب مين؟ وأنت تجاوب للنوعين: العادية (باسم الموكل ولحسابه)، بالعمولة (باسمه هو ولحساب الموكل).","sec":"LAW333-L4"},{"id":"l4.commission-vs-brokerage","ar":"تخلط بين الوكيل بالعمولة والسمسار","explain":"السمسار يقرّب بين شخصين أو أكثر لإبرام صفقة بدون ما يكون طرف، فما يلتزم بأي أثر من آثار العقد. الوكيل بالعمولة يدخل طرف، يكتسب الحقوق ويتحمل الالتزامات ثم ينقلها لموكله.","fix":"راجع آخر نقطة في الشريحة 6.","coach":"أخوك يوصف لك شخص: وقّع العقد باسمه وبعدين حوّله لصاحبه، أو جمع البائع والمشتري وأخذ أجرته وطلع. وأنت تقول: وكيل بالعمولة ولا سمسار؟","sec":"LAW333-L4"},{"id":"l4.liberal-professions","ar":"تحسب مكاتب المهن الحرة (المحامين، الأطباء، المهندسين) من المكاتب التجارية","explain":"مكاتب الخدمات (تخليص جمركي، استقدام، تعقيب، تحصيل ديون...) تجارية لأنها تحترف الوساطة بقصد الربح. أما مكاتب المهن الحرة كالمحامين والأطباء والمهندسين فما تعد أعمالاً تجارية وتخضع لتنظيم قانوني مختلف.","fix":"راجع آخر نقطة في الشريحة 8.","coach":"أخوك يقرأ عليك قائمة مكاتب مخلوطة (استقدام، محاماة، تأمين، عيادة، إعلان)، وأنت تفرزها: تجاري ولا مهنة حرة.","sec":"LAW333-L4"},{"id":"l4.accessory-unrelated","ar":"تظن إن أي عمل يسويه التاجر يصير تجاري بالتبعية","explain":"صفة التاجر وحدها ما تكفي. لازم العمل المدني يكون متصل بشؤون تجارته أو ناشئ عنها. شراء سيارة لنقل أسرته أو دفع مصاريف تعليم وعلاج أبنائه يظل مدني.","fix":"راجع الشريحة 11 (النقطة الثالثة والمكونين) والشرط الثاني في الشريحة 13.","coach":"أخوك يذكر أعمال لتاجر: سيارة لنقل البضائع، سيارة لأسرته، أثاث لمحله، علاج ولده. وأنت تقول: تبعية ولا مدني، وأي شرط ناقص.","sec":"LAW333-L4"},{"id":"l4.accessory-noncontract","ar":"تظن إن الأعمال التجارية بالتبعية تشمل العقود بس","explain":"التبعية تشمل الالتزامات التعاقدية وغير التعاقدية (اللي مصدرها مو العقد): المسؤولية التقصيرية كالمنافسة غير المشروعة وتعويض الغير عن الضرر، والإثراء بلا سبب كرد ما قبضه التاجر زائداً عن الثمن.","fix":"راجع الشريحة 14 كاملة.","coach":"أخوك يقول: اذكر مثالين تعاقدية ومثالين غير تعاقدية، وأنت تجاوب بدون ما تشوف الشريحة.","sec":"LAW333-L4"},{"id":"l4.bases-mixup","ar":"تخلط بين أسس نظرية الأعمال التجارية بالتبعية الثلاثة","explain":"النظري: الفرع يتبع الأصل. التنظيمي: نصوص النظام (المادة 2 فقرة د من نظام المحكمة التجارية، والمادة 16/1 من نظام المحاكم التجارية). المنطقي: كل أعمال التاجر المتعلقة بمهنته تخضع لنظام واحد ومحكمة واحدة.","fix":"راجع الشريحة 12.","coach":"أخوك يقول جملة (الفرع يتبع الأصل، المادة 16/1، نظام واحد ومحكمة واحدة)، وأنت تقول أي أساس هي.","sec":"LAW333-L4"},{"id":"l4.mixed-vs-accessory","ar":"تخلط بين العمل المختلط والعمل التجاري بالتبعية","explain":"المختلط: نفس العمل تجاري لطرف ومدني للطرف الثاني، وهو وصف مو نوع مستقل. التبعية: عمل أصله مدني يصير تجاري لأنه صدر من تاجر لحاجات تجارته. عقد النقل مختلط (تجاري للناقل مدني للمسافر)، إلا إذا المسافر تاجر وسفره لغرض تجارته فيصير تجاري بالتبعية.","fix":"راجع الشريحة 16 وقارنها بالشريحة 11.","coach":"أخوك يعطيك حالتين لمسافر: موظف رايح إجازة، وتاجر رايح يشتري بضاعة. قل التكييف لكل واحد من جهة المسافر.","sec":"LAW333-L4"},{"id":"l4.mixed-court","ar":"تخلط في القانون الواجب التطبيق والمحكمة المختصة بالعمل المختلط","explain":"القانون: التجاري على الطرف التجاري والمدني على الطرف المدني، وفي الإثبات يلتزم الطرفان بنظام الإثبات. المحكمة: حسب صفة العمل للمدعى عليه؛ مدني فالعامة، وتجاري فالتجارية إذا كان من العقود التجارية والمطالبة فوق 500 ألف ريال، وإلا العامة.","fix":"راجع الشريحة 17.","coach":"أخوك يبدّل لك المدعي والمدعى عليه والمبلغ (300 ألف، 700 ألف)، وأنت تحدد المحكمة كل مرة وتقول: شفت صفة العمل عند مين؟","sec":"LAW333-L4"},{"id":"l5.occasional","ar":"تحسب إن أي صفقة تجارية متفرقة تخليك تاجر","explain":"الاحتراف معناه ممارسة دائمة ومنتظمة ومستمرة كوسيلة للعيش.\nالعمل العارض أو اللي على فترات متباعدة (مثل بيع سيارة كل فترة طويلة) ما يكفي.","fix":"راجع تعريف الاحتراف ومثال السيارات في شريحة 4.","coach":"أخوك يذكر لك ثلاث حالات: شخص باع أرضه مرة وحدة، شخص عنده بقالة شغالة يومياً، شخص يبيع سيارة كل سنة. وأنت تقول في كل وحدة: احتراف أو لا، وتبرر بالكلمات الثلاث: دائمة، منتظمة، مستمرة.","sec":"LAW333-L5"},{"id":"l5.side-job","ar":"تحسب إن التجارة لازم تكون مهنتك الوحيدة","explain":"الشرائح نصت إنه ما يشترط يكون العمل التجاري مهنة الشخص الوحيدة.\nالمحامي أو المهندس اللي يتاجر بصورة مستمرة يكتسب صفة التاجر.","fix":"راجع أول نقطة في شريحة 5.","coach":"أخوك يسألك: «مهندس عنده متجر إلكتروني شغال طول السنة، تاجر؟». وأنت تجاوب وتسمّع جملة الشريحة: «ولا يشترط أن يكون العمل التجاري مهنة الشخص الوحيدة».","sec":"LAW333-L5"},{"id":"l5.conditions-mixup","ar":"تخلط بين تعريف الاحتراف وتعريف الاستقلالية وتعريف الأهلية","explain":"الاحتراف: ممارسة دائمة ومنتظمة ومستمرة للعيش. الاستقلالية: تشتغل باسمك ولحسابك وتتحمل الربح والخسارة.\nالأهلية: قدرة المرء وصلاحيته على مباشرة التصرفات القانونية.","fix":"راجع شرائح 4 و9 و13، وحط التعاريف الثلاثة جنب بعض.","coach":"أخوك يقرأ عليك تعريفاً بدون ما يقول اسمه، وأنت تقول أي شرط هو. بعدين بالعكس: يقول اسم الشرط وأنت تسمّع تعريفه.","sec":"LAW333-L5"},{"id":"l5.illegal-trade","ar":"تحسب إن اللي يتستر بنشاط غير مشروع ما يُعامل كتاجر أبداً","explain":"المشروعية شرط لاكتساب صفة التاجر، لكن اللي يتستر خلف نشاط مشروع يُعتبر تاجراً في مواجهة الغير حسن النية.\nالغير يستفيد من نظرية الوضع الظاهر، ويطلب شهر إفلاسه على أساس النشاط الظاهر المشروع.","fix":"راجع شريحة 6: السؤال المكتوب بالخط العريض وجوابه.","coach":"أخوك يسألك: «تاجر مخدرات متستر ببقالة، تعامل معه مورّد حسن النية. يقدر المورّد يطلب إفلاسه؟ وعلى أي أساس؟». والجواب: نعم، على أساس النشاط الظاهر المشروع.","sec":"LAW333-L5"},{"id":"l5.capacity-vs-ban","ar":"تخلط بين الممنوع من التجارة (كالموظف العام) وعديم الأهلية","explain":"الحظر مقرر للمصلحة العامة وما يأثر على صحة التصرف، فالموظف العام إذا تاجر يعتبر تاجراً ويجوز شهر إفلاسه، وما يُعفى من جزاءاته التأديبية.\nانعدام الأهلية يبطل التصرف، والمنع مقرر لحماية الشخص نفسه، فما يكتسب صفة التاجر ولا يجوز شهر إفلاسه.","fix":"راجع النقطة الثانية في شريحة 5، وشريحة 15 كاملة.","coach":"أخوك يقول «موظف عام» أو «مجنون»، وأنت ترد بسرعة على ثلاث أسئلة: تاجر أو لا؟ يجوز شهر إفلاسه أو لا؟ المنع للمصلحة العامة أو لحمايته؟","sec":"LAW333-L5"},{"id":"l5.partners","ar":"تحسب إن كل شريك في شركة تجارية يصير تاجراً","explain":"الشخصية المعنوية للشركة مستقلة عن الشركاء، فصفة الشركة ما تنتقل لهم.\nالاستثناء: الشركاء المتضامنون في شركتي التضامن والتوصية البسيطة، بسبب مسؤوليتهم التضامنية عن ديون الشركة.","fix":"راجع أول نقطة في شريحة 7.","coach":"أخوك يسألك: «مساهم في شركة مساهمة؟ شريك متضامن في شركة تضامن؟ شريك متضامن في توصية بسيطة؟». وأنت تقول تاجر أو لا، وتذكر السبب.","sec":"LAW333-L5"},{"id":"l5.profit-result","ar":"تحسب إن لازم يتحقق ربح فعلي وكبير","explain":"لازم يكون الاحتراف بقصد الربح، لكن ما يشترط يكون الربح كبيراً، ولا يشترط يتحقق فعلاً.\nالعبرة بالقصد وليس بالنتيجة.","fix":"راجع آخر نقطة في شريحة 7.","coach":"أخوك يسألك: «واحد فتح محل وخسر أول سنة، يعتبر تاجر؟». تجاوب بجملة «العبرة بالقصد وليس بالنتيجة». بعدين يسألك عن مثال لعمل ما يقوم على الربح، والجواب: سحب الكمبيالات.","sec":"LAW333-L5"},{"id":"l5.registry-proof","ar":"تحسب إن القيد في السجل التجاري يثبت إنك تاجر بشكل قاطع","explain":"صفة التاجر غير مفترضة، واللي يتمسك بها عليه عبء الإثبات. والقيد والدفاتر ومظاهر الشهرة قرائن بسيطة يمكن إثبات عكسها.\nوالعكس صحيح: عدم القيد ما ينفي الصفة، ووصف الشخص لنفسه بالتاجر ما يثبتها.","fix":"راجع شريحة 8 (إثبات الاحتراف).","coach":"أخوك يعطيك ثلاث حالات: واحد مقيد بالسجل وما يشتغل، وواحد يشتغل باستمرار وما قيّد نفسه، وواحد كاتب في عقده «تاجر» وما يشتغل. وأنت تحكم في كل حالة وتبرر.","sec":"LAW333-L5"},{"id":"l5.shop-required","ar":"تحسب إن المحل التجاري شرط لصفة التاجر","explain":"من نتائج شرط الاستقلالية إنه ما يلزم اتخاذ محل تجاري.\nيكفي الاحتراف بنية الربح باسم الشخص ولحسابه، فالسمسار والوكيل بالعمولة تجار حتى لو ما عندهم محل.","fix":"راجع شريحة 11 (ثانياً).","coach":"أخوك يسألك: «سمسار عقار يشتغل من جواله بدون مكتب، تاجر؟». وأنت تجاوب، وتعدّد الشروط الثلاثة، وتوضح إن المحل مو واحد منها.","sec":"LAW333-L5"},{"id":"l5.agent-commission","ar":"تخلط بين مدير الشركة المساهمة والوكيل بالعمولة","explain":"الاثنين يشتغلون لحساب غيرهم، لكن المدير ما يتحمل المخاطر، فما يكون تاجراً.\nالوكيل بالعمولة والسمسار تجار، لأن أعمالهم تجارية بطبيعتها ويمارسونها بأسمائهم ولحسابهم، حتى لو كانت صفقات الموكل مدنية.","fix":"قارن شريحة 10 (أولاً) بشريحة 11 (ثانياً).","coach":"أخوك يعدّ عليك: مدير شركة مساهمة، موظف في محل، وكيل بالعمولة، سمسار، ولي قاصر. وأنت تفرزهم إلى تاجر ومو تاجر، مع السبب لكل واحد.","sec":"LAW333-L5"},{"id":"l5.hidden-trader","ar":"تحسب إن واحد بس من التاجر الظاهر والمستتر هو التاجر","explain":"حسب الرأي الراجح، الاثنين يكتسبون صفة التاجر.\nالمستتر عشان ما يتهرب من آثار التجارة مثل شهر الإفلاس، والظاهر بنظرية الظاهر حمايةً للغير اللي تعامل معه.","fix":"راجع شريحة 12 (ثالثاً).","coach":"أخوك يسألك سؤالين: «ليش المستتر تاجر؟» و«ليش الظاهر تاجر؟». وأنت تجاوب كل سؤال بسببه المختلف.","sec":"LAW333-L5"},{"id":"l5.minor-trade","ar":"تحسب إن القاصر ما يقدر يتاجر أبداً، أو إن وليه يقدر يفتح له تجارة جديدة","explain":"الولي يقدر يأذن للقاصر بالإتجار إذناً مطلقاً أو مقيداً، ويُعتبر القاصر كامل الأهلية فيما أُذن له فيه وفي التقاضي فيه.\nلكن الولي (ومثله القيم) ما ينشئ تجارة جديدة، له بس يستمر في تجارة آلت للقاصر، وبإذن المحكمة.","fix":"راجع شريحة 16، وآخر نقطة في شريحة 14.","coach":"أخوك يسألك ثلاث أسئلة: «الولي أذن لولده (16 سنة) يبيع جوالات بس، وش حكمه؟»، ثم «الولي يبي يفتح لولده القاصر مطعم جديد، يقدر؟»، ثم «القاصر ورث محل أبوه، وش الحكم؟».","sec":"LAW333-L5"},{"id":"l6.mandatory-optional","ar":"تخلط بين الدفاتر الإلزامية والاختيارية","explain":"الإلزامية ثلاثة بس: اليومية والجرد والأستاذ. الباقي (التسويدة، الخزانة، المخزن، الأوراق التجارية) اختياري، حتى الخزانة اللي تُعد أساسية للبنوك والشركات الكبرى تبقى اختيارية.","fix":"راجع مخطط الشريحة ٨، والملاحظة عن دفتر الخزانة في الشريحة ١٠.","coach":"أخوك يقول اسم دفتر عشوائي وأنت ترد فوراً «إلزامي» أو «اختياري». ولما يقول «الخزانة» لازم تكمل: «اختياري، بس أساسي للبنوك والشركات الكبرى».","sec":"LAW333-L6"},{"id":"l6.ledger-journal","ar":"تخلط بين دفتر اليومية ودفتر الأستاذ","explain":"اليومية: عمليات التاجر المالية تنقيد فيها يوم بيوم حتى السحوبات الشخصية. الأستاذ: أهم الدفاتر، تُرحَّل إليه العمليات ذات الطبيعة الواحدة من الدفاتر الثانية.","fix":"الشريحة ٩: ركّز على «يوم بيوم» مقابل «تُرحَّل إليه».","coach":"أخوك يقرأ لك وصف فيه «يوم بيوم» أو «أهم الدفاتر» أو «تُرحَّل إليه»، وأنت تسمي الدفتر وتقول الكلمة اللي دلّتك عليه.","sec":"LAW333-L6"},{"id":"l6.inventory-warehouse","ar":"تخلط بين دفتر الجرد ودفتر المخزن","explain":"الجرد: تفاصيل البضاعة الموجودة آخر السنة المالية مع صورة من قائمة المركز المالي، وهو إلزامي. المخزن: حركة البضاعة اللي تدخل وتطلع من المخزن، وهو اختياري.","fix":"قارن تعريف الجرد في الشريحة ٩ بتعريف المخزن في الشريحة ١٠.","coach":"أخوك يقول «آخر السنة المالية» أو «حركة دخول وخروج»، وأنت تسمي الدفتر وتصنيفه (إلزامي/اختياري).","sec":"LAW333-L6"},{"id":"l6.draft-journal","ar":"تخلط بين دفتر التسويدة ودفتر اليومية","explain":"التسويدة مسودة: العمليات اليومية تنكتب فيها بسرعة وبدون تنظيم، وبعدين تنتقل بشكل منظم لدفتر اليومية. التسويدة اختيارية واليومية إلزامية.","fix":"الشريحة ١٠ (التسويدة) مقابل الشريحة ٩ (اليومية).","coach":"أخوك يسألك: «العمليات بعد ما تنكتب في التسويدة وين تروح؟» والجواب: لدفتر اليومية بشكل منظم.","sec":"LAW333-L6"},{"id":"l6.exempt","ar":"تلخبط مين ملزم ومين مستثنى من مسك الدفاتر","explain":"الأصل: كل من اكتسب صفة التاجر، طبيعي أو اعتباري، سعودي أو أجنبي. المستثنى اثنين بس: التاجر اللي رأس ماله ما يزيد عن ١٠٠ ألف ريال، والشريك المتضامن.","fix":"الشريحة ٧ بالكامل.","coach":"أخوك يذكر حالات (شركة أجنبية، شريك متضامن، تاجر برأس مال ٩٠ ألف، تاجر سعودي برأس مال مليون) وأنت تقول «ملزم» أو «مستثنى» وليش.","sec":"LAW333-L6"},{"id":"l6.retention","ar":"تحسب مدة الحفظ مدة تقادم أو تنسى الورثة","explain":"المادة الثامنة: التاجر وورثته يحفظون الدفاتر عشر سنوات على الأقل، ونفس المدة لصور المراسلات والوثائق. وحجية الدفاتر تبقى حتى بعد العشر سنوات لأنها ليست مدة تقادم.","fix":"الشريحة ١١، انتبه لكلمات «وورثته» و«على الأقل» و«ليست مدة تقادم».","coach":"أخوك يسألك ثلاث أسئلة سريعة: مين يحفظ؟ كم سنة؟ وش يصير لحجية الدفاتر بعد ما تخلص المدة؟","sec":"LAW333-L6"},{"id":"l6.numbers","ar":"تلخبط الأرقام: ١٠٠ ألف، ٥ آلاف، ٥٠ ألف، ١٠ سنوات","explain":"١٠٠ ألف ريال هو حد رأس مال التاجر المستثنى من مسك الدفاتر. من ٥ آلاف إلى ٥٠ ألف ريال هي غرامة المخالف. و١٠ سنوات مدة الحفظ.","fix":"الشرائح ٧ و١١ و١٢.","coach":"أخوك يقول رقم (١٠٠ ألف، ٥ آلاف، ٥٠ ألف، ١٠ سنوات) وأنت تقول وش يمثل في المحاضرة.","sec":"LAW333-L6"},{"id":"l6.irregular-effect","ar":"تخلط بين آثار عدم مسك الدفاتر أو عدم انتظامها","explain":"فيه ثلاث آثار منفصلة: غرامة من ٥ إلى ٥٠ ألف، عدم الاعتداد بالدفاتر غير المنتظمة في الإثبات، واحتساب الزكاة أو الضريبة بالأسلوب التقديري اللي ممكن يكون مبالغ فيه. أثر ما يلغي الثاني.","fix":"الشريحة ١٢.","coach":"اطلب من أخوك يعدّ الآثار الثلاثة بدون ما يشوف، وبعدين يعطيك ثلاث أمثلة على عدم الانتظام (الحواشي، الفراغ، الترقيم).","sec":"LAW333-L6"},{"id":"l6.computer-conditions","ar":"تخلط مين مسؤول عن وش في شروط الحاسب الآلي","explain":"المنشأة: وسائل أمان، ومخرجات مطبوعة دورية، وهي المسؤولة مباشرة عن صحة البيانات. المحاسب القانوني: يقدم تقرير «فحص تأكيدات» يؤيد صحة ونظامية البيانات.","fix":"الشريحة ١٣، الشروط الثلاثة.","coach":"أخوك يقول «المنشأة» أو «المحاسب القانوني» وأنت تذكر وش عليه بالضبط.","sec":"LAW333-L6"},{"id":"l6.binding-proof","ar":"تظن الدفاتر المنتظمة تُلزم القاضي أو دليل قطعي","explain":"القضاء غير ملزم بالأخذ بالدفاتر حتى لو منتظمة لأن القاضي له سلطة تقديرية. والدليل منها مو قطعي، ولكل ذي مصلحة يثبت العكس.","fix":"الشريحة ١٥، أول نقطتين.","coach":"أخوك يسألك: «الدفاتر منتظمة، يعني القاضي لازم ياخذ فيها؟» وأنت ترد وتعلل بـ«سلطة تقديرية» و«مو دليل قطعي».","sec":"LAW333-L6"},{"id":"l6.evidence-exception","ar":"تظن استخدام الدفاتر في الإثبات تطبيق للقواعد العامة","explain":"القاعدتين العامتين: «لا يُجبر الشخص على تقديم دليل ضد نفسه» و«لا يجوز للشخص اصطناع دليل لنفسه ضد الغير». الدفاتر تُستخدم لمصلحة التاجر وضده، فهذا استثناء من القاعدتين.","fix":"الشريحة ١٤.","coach":"أخوك يسألك: «ليش يعتبر استثناء؟» وأنت تربط كل قاعدة بجهة: لمصلحته = دليل لنفسه، وضده = دليل ضد نفسه.","sec":"LAW333-L6"},{"id":"l6.opponent-access","ar":"تظن النظام حسم حق الخصم في الاطلاع على الدفاتر","explain":"الشريحة تقول إن النظام لم يبين هل للخصم حق الاطلاع على دفاتر التاجر أو لا. فلا تختار «يجوز» ولا «لا يجوز».","fix":"آخر نقطة في الشريحة ١٥.","coach":"أخوك يسألك مباشرة: «هل للخصم يطّلع على دفاتر التاجر؟» والجواب الصح: «النظام لم يبين».","sec":"LAW333-L6"},{"id":"l7.fixed-shop-criterion","ar":"تحسب إن رأس المال هو اللي يحدد هل التاجر الفرد ملزم بالقيد","explain":"الشريحة تقول: كل تاجر ملزم بالقيد «بغض النظر عن مقدار رأس المال». المعيار هو المحل الثابت؛ واللي يمارس تجارته بدون محل يباشر فيه عمله مو ملزم.","fix":"راجع شريحة 4 (الأفراد)، وركّز على عبارتين: «بغض النظر عن مقدار رأس المال» و«طالما لديه محل ثابت».","coach":"أخوك يعطيك حالتين بسرعة: تاجر رأس ماله صغير وعنده دكان، وتاجر غني يبيع متنقل بدون محل. تقول له ملزم أو لا، وتذكر المعيار بكلمتين: «المحل الثابت».","sec":"LAW333-L7"},{"id":"l7.companies-scope","ar":"تظن إن الشركات الأجنبية أو المدنية معفاة من القيد","explain":"الالتزام يشمل كل شركة تأسست في المملكة أو لها فرع فيها، ويسري على الشركات الأجنبية المرخص لها بفرع أو مكتب، وعلى الشركات المدنية كالعقارية والزراعية.","fix":"راجع شريحة 4 (الشركات) واحفظ الأنواع الأربعة.","coach":"عدّد لأخوك بصوت عالي أربعة أنواع شركات ملزمة بالقيد بدون ما تشوف الشريحة، وهو يصحح لك.","sec":"LAW333-L7"},{"id":"l7.data-list","ar":"تزيد أو تنقص في البيانات الواجب قيدها","explain":"القائمة خمسة بنود محددة: البيانات الشخصية والوصفية، أحكام الإفلاس النهائية، أحكام الأهلية، أحكام حل الشركة أو بطلانها، والإدانة في التزوير والتزييف والرشوة. انتبه لكلمة «النهائية» وللجرائم الثلاث بالذات.","fix":"راجع شريحة 5 واكتب البنود الخمسة من ذاكرتك.","coach":"أخوك يقول كلمة (إفلاس نهائي، محجور عليه، حل الشركة، رشوة، أسماء العملاء…) وأنت ترد: «تُقيد» أو «مو في القائمة» مع السبب.","sec":"LAW333-L7"},{"id":"l7.judicial-body","ar":"تحسب مكاتب السجل التجاري جهة قضائية","explain":"مكاتب السجل التجاري تتبع وزارة التجارة وتتأكد من صحة البيانات المسجلة، لكنها جهة إدارية مو قضائية.","fix":"راجع أول نقطة في شريحة 6.","coach":"أخوك يسألك: «مكاتب السجل تتبع مين؟ ووش طبيعتها؟» وتجاوب بجملة وحدة خلال خمس ثواني.","sec":"LAW333-L7"},{"id":"l7.stats-only","ar":"تحسب القيد مجرد أداة إحصاء واستعلام","explain":"الشريحة تنص إن القيد ليس فقط أداة للإحصاء والاستعلام بل أداة للشهر القانوني، وهذا يتماشى مع تعريف السجل كوسيلة إشهار.","fix":"راجع شريحة 6 (النقطة الثانية) واربطها بتعريف السجل في شريحة 3.","coach":"اشرح لأخوك بجملتين ليش القيد «شهر قانوني» واربطه بكلمة «وسيلة إشهار» في التعريف.","sec":"LAW333-L7"},{"id":"l7.extract-limits","ar":"تظن إن الصورة المستخرجة من السجل تنعطى بكل بياناتها بدون أي قيد","explain":"أي شخص يقدر ياخذ صورة لأي تاجر أو شركة، بس بشرط ما يكون فيها بيانات تضر بسمعة التاجر ولا تفيد الغير، مثل أحكام الإفلاس السابقة قبل رد الاعتبار.","fix":"راجع آخر نقطة في شريحة 6.","coach":"أخوك يمثّل إنه يطلب صورة سجل لتاجر عليه إفلاس قديم وما رُد له اعتباره، وأنت تقول له وش ينعطى ووش ما ينعطى وليش.","sec":"LAW333-L7"},{"id":"l7.deregistration-who","ar":"تخلط مين اللي يطلب شطب القيد في كل حالة","explain":"ثلاث حالات: التاجر نفسه إذا اعتزل التجارة، وورثته إذا توفي، والمصفون إذا صُفّيت الشركة.","fix":"راجع أول نقطة في شريحة 7.","coach":"أخوك يقول الحالة (اعتزال، وفاة، تصفية) وأنت ترد فوراً بالشخص اللي يطلب الشطب.","sec":"LAW333-L7"},{"id":"l7.old-vs-new-law","ar":"تعكس بين نظام السجل التجاري الحالي والقديم","explain":"النظام الحالي، بخلاف القديم، هو اللي رتّب آثاراً قانونية مدنية على القيد وجزاءً جنائياً عند مخالفة أحكامه.","fix":"راجع النقطة الثانية في شريحة 7.","coach":"قل الجملة كاملة لأخوك: «الحالي بخلاف القديم رتّب آثار مدنية وجزاء جنائي»، وبعدين يسألك فجأة: أي نظام؟","sec":"LAW333-L7"},{"id":"l7.evidence-date","ar":"تخلط في التاريخ اللي تبدأ منه حجية البيانات المقيدة","explain":"حسب الشريحة، حجية البيانات المقيدة في السجل التجاري تبدأ من تاريخ تقديمها، مو من أي تاريخ ثاني.","fix":"راجع البند الأول في شريحة 8.","coach":"أخوك يسألك: «البيانات تصير حجة من متى؟» وتجاوب بثلاث كلمات: «من تاريخ تقديمها».","sec":"LAW333-L7"},{"id":"l7.fine-amount","ar":"تنسى نوع الجزاء أو مقدار الغرامة على مخالفة أحكام السجل","explain":"مخالفة أحكام السجل التجاري يترتب عليها جزاء جنائي، وهو غرامة تصل إلى خمسين ألف ريال، والشريحة ذكرته كبند ثالث.","fix":"راجع البند الثالث في شريحة 8.","coach":"أخوك يسألك: «وش جزاء مخالفة أحكام السجل؟ وكم الحد الأعلى؟» وترد بنوع الجزاء والمبلغ.","sec":"LAW333-L7"},{"id":"l7.chamber-nature","ar":"تحسب الغرفة التجارية جهة ربحية أو ما لها شخصية اعتبارية","explain":"الغرفة هيئة لا تستهدف الربح، ولها شخصية اعتبارية، ويمثلها رئيس مجلس إدارتها أمام القضاء والغير.","fix":"راجع الفقرة الأولى في شريحة 9.","coach":"أخوك يسألك ثلاثة أسئلة سريعة: ربحية أو لا؟ لها شخصية اعتبارية؟ مين يمثلها أمام القضاء؟","sec":"LAW333-L7"},{"id":"l7.registry-vs-chamber","ar":"تخلط بين السجل التجاري والغرفة التجارية","explain":"السجل التجاري وسيلة إشهار تنشر معلومات التاجر للمتعاملين معه، ومكاتبه تتبع وزارة التجارة. أما الغرفة فهيئة غير ربحية تمثل مصالح التجار والصناع أمام السلطات العامة.","fix":"قارن بين شريحة 3 وشريحة 6 وشريحة 9.","coach":"أخوك يقرأ وصف (إشهار، تمثيل أمام السلطات العامة، التأكد من صحة البيانات، لا تستهدف الربح) وأنت تقول: «سجل» أو «غرفة».","sec":"LAW333-L7"},{"id":"imp.drawee","ar":"تخلط بين أطراف الشيك والكمبيالة والسند لأمر","explain":"الشيك: المسحوب عليه لازم يكون بنك دائماً.\nالكمبيالة: المسحوب عليه ممكن يكون أي شخص.\nالسند لأمر: ما فيه مسحوب عليه أصلاً — طرفين بس (المحرر والمستفيد).","fix":"احفظ الجدول: كمبيالة ٣ أطراف (أي شخص) · شيك ٣ أطراف (بنك) · سند لأمر طرفين.","coach":"قل له اسم الورقة وخلّه يقول كم طرف فيها ومين المسحوب عليه.","sec":"LAW333-PRAC"}],"cases":[],"questions":[{"n":101,"lo":"L1","sec":"LAW333-L1","type":"term","topic":"commercial-law-def","stem":"ما تعريف القانون التجاري حسب الشرائح؟","options":["مجموعة القواعد التي يتعارف عليها التجار في تنظيم معاملاتهم التجارية مع اعتقادهم بإلزاميتها","مجموعة القواعد القانونية التي تحكم الأعمال التجارية","مجموعة المبادئ القانونية التي استقرت عليها أحكام الجهات القضائية","آراء شراح القانون واجتهاداتهم في مختلف مجالات التجارة"],"answer":1,"why":"التعريف في الشريحة ٣ حرفياً: «هو مجموعة القواعد القانونية التي تحكم الأعمال التجارية». الكلمة المفتاح: «تحكم الأعمال التجارية».","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا تعريف العرف (شريحة ١٨) — فيه «يتعارف عليها التجار» و«إلزاميتها»، مو تعريف القانون التجاري كله."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف القضاء كمصدر من مصادر القانون التجاري (شريحة ٢٠)."},{"i":3,"mis":"gen.neighbor","note":"هذا قريب من تعريف الفقه (شريحة ٢١) — آراء الشراح مصدر تفسيري، مو القانون نفسه."}],"tests":["تعريف القانون التجاري"]},{"n":102,"lo":"L1","sec":"LAW333-L1","type":"tf","topic":"private-law-branch","stem":"القانون التجاري فرع مستقل من فروع القانون الخاص، التي يأتي على رأسها القانون المدني، وهو في المملكة «نظام المعاملات المدنية» الصادر عام ١٤٤٤هـ.","options":["صح","خطأ"],"answer":0,"why":"العبارة مطابقة للشريحة ٣. انتبه لكلمتين: «مستقل» (مو جزء من المدني) و«الخاص» (مو العام).","wrong":[{"i":1,"mis":"l1.private-law","note":"ممكن تحسبها خطأ لأنك تظن التجاري جزء من القانون المدني أو من القانون العام، لكن الشريحة تقول «فرع مستقل من فروع القانون الخاص»."}],"tests":["موقع القانون التجاري بين فروع القانون","نظام المعاملات المدنية ١٤٤٤هـ"]},{"n":103,"lo":"L1","sec":"LAW333-L1","type":"figure","topic":"course-topics","stem":"الشكل يعرض الموضوعات الرئيسية التي تندرج ضمن القانون التجاري. أيّ موضوع من التالي ليس من الموضوعات التي تعنينا في هذا المقرر؟","img":"img/law333/L1-s04.png","options":["الشركات","الأوراق التجارية","نظرية التاجر","نظرية الأعمال التجارية"],"answer":1,"why":"الشكل (شريحة ٤) فيه ستة موضوعات، لكن المقرر يهتم بثلاثة بس (شريحة ٥): نظرية الأعمال التجارية، نظرية التاجر، الشركات. فالأوراق التجارية من موضوعات القانون التجاري لكنها مو من مقررنا — ومثلها نظام الإفلاس والنظام البحري والجوي.","wrong":[{"i":0,"mis":"l1.topics-scope","note":"الشركات من الموضوعات الثلاثة اللي يعنينا المقرر (شريحة ٥)."},{"i":2,"mis":"l1.topics-scope","note":"نظرية التاجر من موضوعات المقرر الثلاثة."},{"i":3,"mis":"l1.topics-scope","note":"نظرية الأعمال التجارية أول موضوع من موضوعات المقرر."}],"tests":["الموضوعات الستة للقانون التجاري","الموضوعات الثلاثة في المقرر"]},{"n":104,"lo":"L1","sec":"LAW333-L1","type":"list","topic":"characteristics","stem":"خصائص القانون التجاري كما وردت في الشرائح هي:","options":["السرعة والائتمان","السرعة والشكلية","الائتمان والمساواة بين الأشخاص","حرية الإثبات وافتراض التضامن"],"answer":0,"why":"الشريحة ٦: خاصيتين فقط — السرعة والائتمان. باقي الخيارات إما عكس الخاصية أو قواعد تدعمها أو ميزة لنظرية ثانية.","wrong":[{"i":1,"mis":"gen.reversed","note":"الشكلية عكس السرعة؛ السرعة معناها «بأقل الشكليات والتعقيدات»، والشكلية استثناء في بعض التصرفات فقط."},{"i":2,"mis":"gen.neighbor","note":"المساواة بين الأشخاص ميزة للنظرية الموضوعية (شريحة ١٢)، مو خاصية للقانون التجاري."},{"i":3,"mis":"l1.speed-credit-rules","note":"هذي قواعد تدعم الخصائص: حرية الإثبات تدعم السرعة، وافتراض التضامن يدعم الائتمان — مو هي الخصائص نفسها."}],"tests":["خصائص القانون التجاري"]},{"n":105,"lo":"L1","sec":"LAW333-L1","type":"figure","topic":"speed-rules","stem":"القواعد الظاهرة في الشكل استقر عليها القانون التجاري لدعم أي خاصية من خصائصه؟","img":"img/law333/L1-s08.png","options":["الائتمان","السرعة","الشكلية في التصرفات","المساواة بين الأشخاص"],"answer":1,"why":"الشريحة ٨ تحت عنوان «السرعة»: «ولهذا استقر القانون التجاري على كثير من القواعد التي تدعم هذا الاتجاه، مثل: حرية الإثبات، حماية الوضع الظاهر، انتقال الحقوق بالتظهير والتسليم». كلها تخلي التعامل أسرع وأبسط.","wrong":[{"i":0,"mis":"l1.speed-credit-rules","note":"قواعد الائتمان غير: افتراض التضامن بين المدينين والصرامة في نظام الإفلاس (شريحة ١٠)."},{"i":2,"mis":"gen.reversed","note":"هذي القواعد تقلل الشكليات، ما تزيدها."},{"i":3,"mis":"gen.neighbor","note":"المساواة ميزة النظرية الموضوعية، مو خاصية من خصائص القانون التجاري."}],"tests":["القواعد الداعمة للسرعة"]},{"n":106,"lo":"L1","sec":"LAW333-L1","type":"concept","topic":"credit-rules","stem":"أيّ مما يلي من القواعد التي أتت مؤكدة على الثقة وتقوية الائتمان؟","options":["حرية الإثبات","حماية الوضع الظاهر","الصرامة في نظام الإفلاس","انتقال الحقوق بالتظهير والتسليم"],"answer":2,"why":"الشريحة ١٠: دعماً للائتمان جاءت قاعدتان: افتراض التضامن بين المدينين بدين تجاري، والصرامة في نظام الإفلاس. منطقها: الديون التجارية متسلسلة، فلازم ضمانات قوية للسداد.","wrong":[{"i":0,"mis":"l1.speed-credit-rules","note":"حرية الإثبات من قواعد السرعة (شريحة ٨)."},{"i":1,"mis":"l1.speed-credit-rules","note":"حماية الوضع الظاهر من قواعد السرعة (شريحة ٨)."},{"i":3,"mis":"l1.speed-credit-rules","note":"انتقال الحقوق بالتظهير والتسليم من قواعد السرعة (شريحة ٨)."}],"tests":["القواعد الداعمة للائتمان"]},{"n":107,"lo":"L1","sec":"LAW333-L1","type":"term","topic":"credit-def","stem":"المقصود بالائتمان في القانون التجاري:","options":["إتمام العمليات التجارية بأقل الشكليات والتعقيدات","افتراض التضامن بين المدينين بدين تجاري","الأجل الممنوح للوفاء بالديون","قاعدة تنشأ ويتكرر اتباعها في العمل مما يكسبها قوة الإلزام"],"answer":2,"why":"الشريحة ٩: «المقصود بالائتمان هو الأجل الممنوح للوفاء بالديون، ما يمثل إبراز صورة الثقة المتبادلة بين التجار». يعني المهلة للسداد.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا وصف خاصية السرعة (شريحة ٧)."},{"i":1,"mis":"l1.credit-meaning","note":"افتراض التضامن قاعدة تدعم الائتمان، مو تعريفه."},{"i":3,"mis":"gen.neighbor","note":"هذا وصف العرف (شريحة ١٨)."}],"tests":["تعريف الائتمان"]},{"n":108,"lo":"L1","sec":"LAW333-L1","type":"tf","topic":"formality-exception","stem":"بما أن السرعة من صميم النشاط التجاري، فكل التصرفات القانونية التجارية تتسم بالسرعة والمرونة، ولم يشترط المنظم في أيٍّ منها شكلية معينة.","options":["صح","خطأ"],"answer":1,"why":"ملاحظة الشريحة ٧: «ليست كل التصرفات القانونية تتسم بالسرعة والمرونة، بل اشترط المنظم في بعض التصرفات شكلية معينة، كاشتراط الكتابة في عقد الشركة والأوراق التجارية». كلمة «كل» هي الفخ.","wrong":[{"i":0,"mis":"l1.speed-absolute","note":"ممكن تختار صح لأن السرعة فعلاً خاصية أساسية، لكن الشريحة تستثني تصرفات اشترط فيها المنظم الكتابة."}],"tests":["الاستثناء من السرعة","اشتراط الكتابة في عقد الشركة والأوراق التجارية"]},{"n":109,"lo":"L1","sec":"LAW333-L1","type":"scenario","topic":"solidarity-presumption","stem":"ثلاثة تجار في مكة اشتروا مع بعض شحنة بضاعة بدين تجاري واحد، وما اتفقوا صراحة على التضامن بينهم. حسب الشرائح، وش القاعدة اللي تنطبق ووش طبيعتها؟","options":["لا تضامن بينهم إلا باتفاق مكتوب، لأن المنظم اشترط الكتابة في كل التصرفات التجارية","يُفترض التضامن بينهم، وهي قاعدة تدعم خاصية السرعة مثل حرية الإثبات","يُفترض التضامن بينهم، لكنها عادة تجارية تقتصر على أطرافها وعلى من يدعيها عبء الإثبات","يُفترض التضامن بينهم لأن الدين تجاري، وهي من القواعد العرفية التجارية التي تقوّي الائتمان"],"answer":3,"why":"الشريحة ١٨: من أمثلة القواعد العرفية التجارية «قاعدة افتراض التضامن بين المدينين بدين تجاري في حال تعددهم»، والشريحة ١٠ تذكرها ضمن القواعد المؤكدة على الثقة وتقوية الائتمان. (المثال العرفي الثاني: إعذار المدين التاجر بأي وسيلة بدل إعذاره بطريقة رسمية.)","wrong":[{"i":0,"mis":"l1.speed-absolute","note":"الكتابة مشروطة في بعض التصرفات فقط (عقد الشركة والأوراق التجارية)، مو في كل التصرفات."},{"i":1,"mis":"l1.speed-credit-rules","note":"افتراض التضامن يدعم الائتمان، أما حرية الإثبات فتدعم السرعة."},{"i":2,"mis":"l1.custom-vs-usage","note":"افتراض التضامن مثال على العرف لا العادة؛ مثال العادة في الشرائح: حزم البضائع ووزنها."}],"tests":["افتراض التضامن","أمثلة القواعد العرفية","القواعد الداعمة للائتمان"]},{"n":110,"lo":"L1","sec":"LAW333-L1","type":"term","topic":"objective-theory","stem":"على ماذا تقوم النظرية الموضوعية (المادية) في تحديد نطاق القانون التجاري؟","options":["على صفة التاجر المحترف، فلا تطبق قواعد القانون التجاري إلا على من اكتسب صفة التاجر","على أن العمل هو ما يحدد النطاق، فالعبرة بالعمل بغض النظر عن الشخص القائم به سواء كان تاجراً أم مدنياً","على إخضاع كافة أعمال التاجر لأحكام القانون التجاري حتى الخارجة عن نشاطه","على أن العمل لا يخضع للقانون التجاري إلا إذا قام به تاجر محترف"],"answer":1,"why":"الشريحة ١٢: «تقوم هذه النظرية على أن العمل هو ما يحدد نطاق تطبيق القانون التجاري، فالعبرة بالعمل بغض النظر عن الشخص القائم به سواء كان تاجرًا أم مدنيًا». تذكّر: موضوعية/مادية = العمل.","wrong":[{"i":0,"mis":"l1.theory-swap","note":"هذا تعريف النظرية الشخصية (الذاتية) — شريحة ١٣."},{"i":2,"mis":"l1.theory-swap","note":"هذي نتيجة النظرية الشخصية وأحد انتقاداتها (شريحة ١٣)."},{"i":3,"mis":"l1.theory-swap","note":"ربط العمل بالتاجر المحترف منطق النظرية الشخصية، والموضوعية تقول العكس: بغض النظر عن الشخص."}],"tests":["النظرية الموضوعية (المادية)"]},{"n":111,"lo":"L1","sec":"LAW333-L1","type":"concept","topic":"personal-critiques","stem":"أيّ مما يلي ليس من الانتقادات الموجهة إلى النظرية الشخصية (الذاتية)؟","options":["صعوبة حصر المهن التجارية لتحديد من يعتبر تاجراً ممن لا يعد كذلك","تضييق نطاق تطبيق القانون التجاري بحرمان من يمارس نشاطاً تجارياً لا يصل إلى درجة الاحتراف","خضوع كافة أعمال التاجر لأحكام القانون التجاري حتى وإن كانت خارجة عن نشاطه التجاري","صعوبة حصر الأعمال التجارية المتعددة لا سيما مع تطور القانون التجاري"],"answer":3,"why":"الخيار الصحيح هو انتقاد النظرية الموضوعية (شريحة ١٢). انتقادات الشخصية ثلاثة (شريحة ١٣): صعوبة حصر «المهن»، التضييق، وإخضاع كل أعمال التاجر. ميّز: الموضوعية ← حصر «الأعمال»، الشخصية ← حصر «المهن».","wrong":[{"i":0,"mis":"l1.critique-swap","note":"هذا الانتقاد الأول للنظرية الشخصية فعلاً؛ لا تخلط «المهن» بـ«الأعمال»."},{"i":1,"mis":"l1.critique-swap","note":"هذا الانتقاد الثاني للنظرية الشخصية."},{"i":2,"mis":"l1.critique-swap","note":"هذا الانتقاد الثالث للنظرية الشخصية («وهذا غير منطقي»)."}],"tests":["انتقادات النظرية الشخصية","انتقاد النظرية الموضوعية"]},{"n":112,"lo":"L1","sec":"LAW333-L1","type":"scenario","topic":"personal-theory-scenario","stem":"تاجر أقمشة في الرياض اشترى ثلاجة لبيته للاستعمال الشخصي. لو طبقنا النظرية الشخصية (الذاتية)، أي عبارة صحيحة؟","options":["يخضع هذا الشراء لأحكام القانون التجاري لأنه صادر من تاجر، وهذا من الانتقادات الموجهة للنظرية لأنه خارج عن نشاطه التجاري","لا يخضع للقانون التجاري، لأن النظرية الشخصية تنظر إلى طبيعة العمل لا إلى صفة الشخص","يخضع للقانون التجاري، وهذا من مزايا النظرية لأنها لا تخل بالمساواة بين الأشخاص","لا يخضع للقانون التجاري، لأن الانتقاد الوحيد للنظرية الشخصية هو صعوبة حصر الأعمال التجارية"],"answer":0,"why":"النظرية الشخصية تطبق القانون التجاري على من اكتسب صفة التاجر «بغض النظر عن طبيعة العمل». فشراء الثلاجة يدخل، والشريحة ١٣ تعدّ هذا الانتقاد الثالث: «خضوع كافة أعمال التاجر لأحكام القانون التجاري، حتى وإن كانت خارجة عن نشاطه التجاري وهذا غير منطقي».","wrong":[{"i":1,"mis":"l1.theory-swap","note":"النظر لطبيعة العمل هو منطق النظرية الموضوعية، مو الشخصية."},{"i":2,"mis":"gen.neighbor","note":"عدم الإخلال بالمساواة ميزة النظرية الموضوعية، والنتيجة هنا انتقاد مو ميزة."},{"i":3,"mis":"l1.critique-swap","note":"صعوبة حصر الأعمال انتقاد الموضوعية، والشخصية لها ثلاثة انتقادات مو واحد."}],"tests":["النظرية الشخصية","انتقادات النظرية الشخصية"]},{"n":113,"lo":"L1","sec":"LAW333-L1","type":"concept","topic":"saudi-approach","stem":"ما مسلك المنظم السعودي في تحديد نطاق القانون التجاري؟","options":["أخذ بالنظرية الشخصية كأساس فعرّف التاجر، واكتفى بعدّ بعض الأعمال التجارية استثناءً","أخذ بالنظرية الموضوعية وحدها وأهمل صفة التاجر تماماً","أخذ بالنظرية الموضوعية كأساس فعدّد الأعمال التجارية، ولم يهمل النظرية الشخصية فعرّف التاجر واعتدّ بصفته في بعض المسائل","أخذ بالنظرية الشخصية وحدها لأن النظرية الموضوعية يصعب معها حصر الأعمال التجارية"],"answer":2,"why":"الشريحة ١٤ نصاً: الأساس = الموضوعية (عدّد الأعمال التجارية)، ومع ذلك أخذ من الشخصية (عرّف التاجر واعتد بصفته في بعض المسائل)، والسبب: العيوب اللي ترد على النظريتين.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلب الأساس: الأساس الموضوعية مو الشخصية."},{"i":1,"mis":"gen.absolute","note":"«وحدها» و«تماماً» غلط؛ المنظم لم يهمل الشخصية."},{"i":3,"mis":"l1.saudi-approach","note":"المنظم ما أخذ بنظرية وحدة، وأساسه الموضوعية مو الشخصية."}],"tests":["مسلك النظام السعودي"]},{"n":114,"lo":"L1","sec":"LAW333-L1","type":"figure","topic":"sources-map","stem":"الشكل يوضح مصادر القانون التجاري. كل ما يلي يندرج تحت «القانون الوطني» عدا:","img":"img/law333/L1-s15.png","options":["نظام المعاملات المدنية، في حال عدم وجود نص خاص في النظام التجاري","العرف والعادات","اتفاقية فيينا الخاصة بالبيع الدولي والنقل الدولي ١٩٨٠م","القضاء والفقه"],"answer":2,"why":"القانون الوطني في الشكل خمسة: الشريعة الإسلامية، نظام المعاملات المدنية (في حال عدم وجود نص خاص في النظام التجاري)، الأنظمة التجارية، العرف والعادات، القضاء والفقه. أما اتفاقية فيينا فمن الاتفاقيات الدولية الموحدة اللي تدخل تحت «القانون الدولي» (شريحة ٢٣).","wrong":[{"i":0,"mis":"gen.detail","note":"ممكن تستبعده لأنه «مدني» مو تجاري، لكنه في الشكل من مصادر القانون الوطني — بشرط عدم وجود نص خاص في النظام التجاري."},{"i":1,"mis":"gen.detail","note":"العرف والعادات مصدر وطني في الشكل."},{"i":3,"mis":"gen.detail","note":"القضاء والفقه مصدر وطني (وهما من المصادر التفسيرية)."}],"tests":["مصادر القانون التجاري","متى يُرجع لنظام المعاملات المدنية","الاتفاقيات الدولية"]},{"n":115,"lo":"L1","sec":"LAW333-L1","type":"tf","topic":"sharia-order","stem":"إذا طُرح على القاضي نزاع تجاري فإنه يطبق أحكام الشريعة الإسلامية أولاً، ولا يرجع إلى النظام التجاري إلا إذا لم يجد حكماً في الشريعة.","options":["صح","خطأ"],"answer":1,"why":"الشريحة ١٦ تقول العكس: «إذا طُرح على القاضي نزاع تجاري فيطبق عليه النظام التجاري، وإذا لم يجد نصاً في نصوص الأنظمة التجارية، فيطبق عليه أحكام الشريعة الإسلامية». والشريعة تبقى الأساس والحاكمة، لأنها سمحت بتنظيم الأنشطة التجارية بما لا يخالف أحكامها.","wrong":[{"i":0,"mis":"gen.reversed","note":"ممكن تختار صح لأن الشريعة هي الأساس والحاكمة على كل الأنظمة، لكن ترتيب التطبيق في النزاع: النظام التجاري أولاً ثم الشريعة عند عدم وجود نص."}],"tests":["دور الشريعة الإسلامية","ترتيب تطبيق القاضي في النزاع التجاري"]},{"n":116,"lo":"L1","sec":"LAW333-L1","type":"concept","topic":"basic-law-art7","stem":"حسب المادة السابعة من النظام الأساسي للحكم، يستمد الحكم في المملكة العربية السعودية سلطته من:","options":["كتاب الله تعالى وسنة رسوله، وهما الحاكمان على هذا النظام وجميع أنظمة الدولة","الشريعة الإسلامية ونظام المعاملات المدنية","الأنظمة التي يصدرها ولي الأمر والعرف المستقر","كتاب الله تعالى وسنة رسوله، وهما الحاكمان على الأنظمة التجارية دون غيرها"],"answer":0,"why":"نص المادة في الشريحة ١٦: «يستمد الحكم في المملكة العربية السعودية سلطته من كتاب الله تعالى، وسنة رسوله. وهما الحاكمان على هذا النظام وجميع أنظمة الدولة».","wrong":[{"i":1,"mis":"gen.neighbor","note":"نظام المعاملات المدنية مصدر للقانون التجاري، مو مصدر سلطة الحكم في المادة السابعة."},{"i":2,"mis":"gen.neighbor","note":"الأنظمة والعرف مصادر للقانون التجاري، والمادة ما ذكرتها."},{"i":3,"mis":"gen.partial","note":"بداية صحيحة لكن النص يقول «جميع أنظمة الدولة» مو التجارية بس."}],"tests":["المادة السابعة من النظام الأساسي للحكم"]},{"n":117,"lo":"L1","sec":"LAW333-L1","type":"list","topic":"commercial-regulations","stem":"الأنظمة التجارية هي الأنظمة التي يصدرها ولي الأمر ولا تتعارض مع أحكام الشريعة الإسلامية. أيّ مما يلي ليس من أمثلتها التي ذكرتها الشرائح؟","options":["نظام الرهن التجاري","نظام مكافحة الغش التجاري","نظام العلامات التجارية","النظام الأساسي للحكم"],"answer":3,"why":"أمثلة الشريحة ١٧ سبعة: المحكمة التجارية، الشركات، الأوراق التجارية، الرهن التجاري، مكافحة الغش التجاري، الأسماء التجاري، العلامات التجارية. النظام الأساسي للحكم ورد في شريحة الشريعة (المادة السابعة)، مو ضمن أمثلة الأنظمة التجارية.","wrong":[{"i":0,"mis":"gen.detail","note":"نظام الرهن التجاري من الأمثلة السبعة في الشريحة ١٧."},{"i":1,"mis":"gen.detail","note":"نظام مكافحة الغش التجاري من الأمثلة السبعة."},{"i":2,"mis":"gen.detail","note":"نظام العلامات التجارية آخر مثال في القائمة."}],"tests":["تعريف الأنظمة التجارية","أمثلة الأنظمة التجارية"]},{"n":118,"lo":"L1","sec":"LAW333-L1","type":"term","topic":"custom-def","stem":"العرف التجاري يُقصد به:","options":["ما يستمد قوته من إرادة المتعاقدين الصريحة أو الضمنية فقط ويقتصر على أطرافه","مجموعة المبادئ القانونية التي استقرت عليها أحكام الجهات القضائية","الأنظمة التي يصدرها ولي الأمر ولا تتعارض مع أحكام الشريعة الإسلامية","مجموعة القواعد التي يتعارف عليها التجار في تنظيم معاملاتهم التجارية مع اعتقادهم بإلزاميتها"],"answer":3,"why":"الشريحة ١٨ حرفياً. ركّز على «اعتقادهم بإلزاميتها» — هذا اللي يفرّقه عن العادة. وهو «قاعدة تنشأ ويكرر اتباعها في العمل مما يكسبها قوة الالزام».","wrong":[{"i":0,"mis":"l1.custom-vs-usage","note":"هذا وصف العادات التجارية (شريحة ١٩)، وهي أقل درجة من العرف."},{"i":1,"mis":"gen.neighbor","note":"هذا تعريف القضاء (شريحة ٢٠)."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف الأنظمة التجارية (شريحة ١٧)."}],"tests":["تعريف العرف"]},{"n":119,"lo":"L1","sec":"LAW333-L1","type":"tf","topic":"custom-precedence","stem":"يغلب العرف الخاص بتجارة معينة على العرف العام الذي يسود التعاملات التجارية، ويغلب العرف المحلي على العرف الشامل لأماكن متعددة.","options":["صح","خطأ"],"answer":0,"why":"الشريحة ١٨ نصاً: «ويغلب العرف الخاص بتجارة معينة على العرف العام الذي يسود التعاملات التجارية ويغلب العرف المحلي على العرف الشامل لأماكن متعددة». القاعدة: الأخص والأقرب يغلب.","wrong":[{"i":1,"mis":"l1.custom-precedence","note":"ممكن تظن العام والشامل أقوى لأنهم أوسع، لكن الشريحة تقدّم الخاص والمحلي."}],"tests":["غلبة العرف الخاص والمحلي"]},{"n":120,"lo":"L1","sec":"LAW333-L1","type":"scenario","topic":"custom-vs-usage","stem":"تاجران في الدمام تعوّدا في تعاملاتهما على طريقة معينة في حزم البضائع ووزنها. صار بينهما نزاع، وادّعى أحدهما أن هذه الطريقة ملزمة للطرف الثاني. ما التكييف الصحيح حسب الشرائح؟","options":["عرف تجاري، يحكم به القاضي من تلقاء نفسه ويُفترض العلم به","عرف تجاري خاص بتجارة معينة، فيُقدَّم على النص النظامي","عادة تجارية، تقتصر على أطرافها، وعلى من يدعيها عبء الإثبات","عادة تجارية، لكنها تحكم جميع التعاملات التجارية في المنطقة"],"answer":2,"why":"الشريحة ١٩ تذكر «اتباع مسلك معين في حزم البضائع ووزنها» كمثال على العادات التجارية. والعادات أقل درجة من العرف لأنها مستمدة من إرادة المتعاقدين فقط، «فهي لا تحكم جميع التعاملات التجارية بل تقتصر على أطرافها وعلى من يدعيها عبء الإثبات».","wrong":[{"i":0,"mis":"l1.custom-vs-usage","note":"هذا حكم العرف لا العادة: القاضي يحكم بالعرف من تلقاء نفسه ويفترض العلم به (شريحة ١٨)، أما العادة فيثبتها اللي يدعيها."},{"i":1,"mis":"l1.custom-precedence","note":"حتى العرف نفسه «لا يصار إليه إلا في حالة غياب النص النظامي»، فما يتقدم على النص؛ والحالة أصلاً عادة مو عرف."},{"i":3,"mis":"gen.absolute","note":"العادات لا تحكم جميع التعاملات التجارية، تقتصر على أطرافها."}],"tests":["الفرق بين العرف والعادات","عبء إثبات العادة","حكم القاضي بالعرف"]},{"n":121,"lo":"L1","sec":"LAW333-L1","type":"concept","topic":"judiciary-fiqh","stem":"أيّ العبارات التالية صحيحة بشأن القضاء والفقه كمصدرين للقانون التجاري؟","options":["يعد الفقه والقضاء من المصادر التفسيرية للقانون، ومن المبادئ التي يرجع الفضل في استنباطها إلى القضاء القواعد المتعلقة بالشركة الفعلية","الفقه هو مجموعة المبادئ القانونية التي استقرت عليها أحكام الجهات القضائية","يرجع الفضل إلى القضاء في ظهور تخصصات جديدة مثل القانون الصرفي وقانون المنافسة","القضاء هو الذي يعمل على استخلاص المبادئ العامة من القواعد النظامية وبيان النقص والخلل فيها"],"answer":0,"why":"الشريحتان ٢٠–٢١: القضاء = مبادئ استقرت عليها أحكام الجهات القضائية، ومنها تحديد نظام دعوى المنافسة غير المشروعة والقواعد المتعلقة بالشركة الفعلية. الفقه = آراء شراح القانون، وأثّر في ظهور القانون الصرفي وقانون المنافسة. والملاحظة: «يعد الفقه والقضاء من المصادر التفسيرية للقانون».","wrong":[{"i":1,"mis":"l1.judiciary-vs-fiqh","note":"هذا تعريف القضاء؛ الفقه = آراء شراح القانون واجتهاداتهم."},{"i":2,"mis":"l1.judiciary-vs-fiqh","note":"التخصصات الجديدة (القانون الصرفي وقانون المنافسة) أثرها للبحوث الفقهية. فخ: القضاء له «دعوى المنافسة غير المشروعة»، والفقه له «قانون المنافسة»."},{"i":3,"mis":"l1.judiciary-vs-fiqh","note":"هذا دور الفقه؛ القضاء معني بتطبيق النظام وتفسيره بحسب غرضه."}],"tests":["تعريف القضاء","تعريف الفقه","المصادر التفسيرية","مبادئ استنبطها القضاء"]},{"n":122,"lo":"L1","sec":"LAW333-L1","type":"concept","topic":"international-law","stem":"أيّ مما يلي صحيح حسب الشرائح عن القانون الدولي كمصدر للقانون التجاري؟","options":["غرفة التجارة الدولية (ICC) اتفاقية دولية موحدة أُبرمت عام ١٨٨٣م","وافقت المملكة على الانضمام إلى لجنة الأمم المتحدة لقانون التجارة الدولية عام ١٤٢٤هـ","تشارك المملكة في مجموعة العمل المالي (فاتف) كعضو كامل مستقل عن مجلس التعاون الخليجي","اتفاقية فيينا ١٩٨٠م خاصة بتنازع القوانين"],"answer":1,"why":"الشريحة ٢٣: من المنظمات والهيئات «لجنة الأمم المتحدة لقانون التجارة الدولية التي وافقت المملكة على الانضمام إليها في عام ١٤٢٤هـ». والسبب العام للقانون الدولي (شريحة ٢٢): الطبيعة الدولية للتجارة والحد من تباين القوانين التجارية بين الدول.","wrong":[{"i":0,"mis":"l1.intl-mixup","note":"ICC منظمة/هيئة دولية مو اتفاقية؛ و١٨٨٣م سنة اتفاقية باريس لحماية حقوق الملكية الصناعية."},{"i":2,"mis":"l1.intl-mixup","note":"الشريحة تقول المملكة تشارك فيها «من خلال عضوية مجلس التعاون الخليجي، وكعضو مراقب»."},{"i":3,"mis":"l1.intl-mixup","note":"فيينا ١٩٨٠م خاصة بالبيع الدولي والنقل الدولي؛ اللي خاصة بتنازع القوانين اتفاقية روما."}],"tests":["المنظمات الدولية المتخصصة","الاتفاقيات الدولية","انضمام المملكة ١٤٢٤هـ"]},{"n":201,"lo":"L2","sec":"LAW333-L2","type":"term","topic":"speculation-def","stem":"المقصود بالمضاربة في معايير التفرقة بين العمل التجاري والعمل المدني هو:","options":["تبادل السلع وحركتها","استهداف تحقيق الربح","ممارسة العمل عن طريق مشروع أو مقاولة بشكل منظم","الأعمال التي تمارس ضمن مهنة وحرفة التجارة"],"answer":1,"why":"الشريحة ٥ تعرّف المضاربة بأنها «استهداف تحقيق الربح»، فكل عمل يستهدف الربح يكون تجارياً حسب هذا المعيار. للحفظ: مضاربة = ربح.","wrong":[{"i":0,"mis":"l2.criteria-mix","note":"هذا تعريف التداول (حركة السلع)، مو المضاربة."},{"i":2,"mis":"l2.criteria-mix","note":"هذا تعريف المشروع (العمل المنظم)."},{"i":3,"mis":"l2.criteria-mix","note":"هذا تعريف الحرفة (المهنة)."}],"tests":["معيار المضاربة","تعريفات المعايير الأربعة"]},{"n":202,"lo":"L2","sec":"LAW333-L2","type":"concept","topic":"no-single-criterion","stem":"س/ هل يوجد معيار محدد يمكن الاسترشاد به للتفريق بين العمل التجاري والعمل المدني؟ الإجابة الصحيحة حسب المحاضرة:","options":["نعم، معيار المضاربة هو المعيار الحاسم لأن كل عمل يستهدف الربح تجاري","نعم، معيار المشروع يكفي وحده لأن الأعمال التجارية تمارس بشكل منظم","لا يوجد معيار محدد، لذلك عدّدت القوانين الأعمال التجارية على سبيل الحصر دون الاسترشاد بأي معيار","لا يوجد معيار محدد، لذلك لجأت أكثر القوانين لتعداد الأعمال التجارية على سبيل المثال، مسترشدةً بعدة معايير"],"answer":3,"why":"الشريحة ٤: ما فيه معيار محدد، فلجأت أكثر القوانين لتعداد الأعمال التجارية «على سبيل المثال» مسترشدةً بعدة معايير. والخلاصة في الشريحة ٩ تقول إنه لا يمكن الاعتماد على معيار واحد، ونستعين بأكثر من معيار.","wrong":[{"i":0,"mis":"l2.no-single-criterion","note":"معيار المضاربة صحيح لكنه ما يكفي لوحده، ونقده أن المحامي والطبيب أيضاً يستهدفون الربح."},{"i":1,"mis":"l2.no-single-criterion","note":"نتيجة كل معيار: صحيح لكنه ما يكفي لوحده، والمشروع منها."},{"i":2,"mis":"gen.detail","note":"أوله صحيح (ما فيه معيار محدد)، لكن التعداد على سبيل المثال مو الحصر، والقوانين استرشدت بعدة معايير."}],"tests":["ضوابط التفرقة","التعداد على سبيل المثال","الخلاصة"]},{"n":203,"lo":"L2","sec":"LAW333-L2","type":"scenario","topic":"coop-speculation","stem":"جمعية تعاونية في أحد أحياء المدينة المنورة تبيع المواد الغذائية لأعضائها بسعر التكلفة ولا تستهدف الربح. وفقاً لمعيار المضاربة، أعمال هذه الجمعية:","options":["تعتبر أعمالاً تجارية لأنها تبيع مواد غذائية مثل محلات المواد الغذائية","تعتبر أعمالاً تجارية لأنه يتم فيها تداول السلع","لا تعتبر من الأعمال التجارية لأنها لا تستهدف الربح","لا تعتبر من الأعمال التجارية لأنها لا تمارس بواسطة مشروع"],"answer":2,"why":"الشريحة ٥ (وبهذا المعيار نعلم): الجمعيات التعاونية اللي تبيع لأعضائها بسعر التكلفة ولا تستهدف الربح، أعمالها ليست تجارية. معيار المضاربة ينظر للربح فقط.","wrong":[{"i":0,"mis":"gen.keyword","note":"جذبتك عبارة «مواد غذائية». محلات المواد الغذائية تجارية لأنها تبيع بهدف الربح، والجمعية ما تستهدف الربح."},{"i":1,"mis":"l2.coop","note":"صحيح أن فيها تداول، لكن السؤال عن معيار المضاربة. والشريحة ٦ نفسها تقول إن الجمعيات فيها تداول ومع ذلك ما تكتسب الصفة التجارية."},{"i":3,"mis":"l2.criteria-mix","note":"السبب في معيار المضاربة هو عدم استهداف الربح، مو عدم وجود مشروع."}],"tests":["معيار المضاربة","الجمعيات التعاونية"]},{"n":204,"lo":"L2","sec":"LAW333-L2","type":"concept","topic":"speculation-critique","stem":"أي مما يلي يُعد نقداً لمعيار المضاربة تحديداً؟","options":["كثير من الأعمال المدنية تستهدف الربح، كعمل المحامي والطبيب والمزارع","كثير من الأعمال المدنية يتم فيها التداول، كالجمعيات التعاونية التي تبيع لأعضائها بسعر التكلفة","كثير من الأعمال المدنية تمارس عن طريق مشروع منظم، كالمكاتب الهندسية والعيادات الطبية","يستبعد الأعمال التجارية المنفردة التي تعد تجارية بطبيعتها دون اشتراط الاحتراف"],"answer":0,"why":"نقد المضاربة في الشريحة ٥: أعمال مدنية كثيرة تستهدف الربح (المحامي، الطبيب، المزارع)، واستهداف الربح ما أدخلها ضمن الأعمال التجارية.","wrong":[{"i":1,"mis":"l2.criteria-critique","note":"هذا نقد معيار التداول (الشريحة ٦)."},{"i":2,"mis":"l2.criteria-critique","note":"هذا نقد معيار المشروع (الشريحة ٧)."},{"i":3,"mis":"l2.criteria-critique","note":"هذا نقد معيار الحرفة (الشريحة ٨)."}],"tests":["نقد المعايير","معيار المضاربة"]},{"n":205,"lo":"L2","sec":"LAW333-L2","type":"tf","topic":"project-critique","stem":"من نقد معيار المشروع أن بعض العمليات لا تُعتبر تجارية إذا وقعت مرة واحدة فقط، مثل الشراء من أجل البيع.","options":["صح","خطأ"],"answer":1,"why":"العبارة عكس الشريحة ٧. الشريحة تقول إن بعض العمليات «تعتبر تجارية حتى ولو وقعت مرة واحدة، مثل الشراء من أجل البيع»، وهذا سبب أن معيار المشروع ما يكفي لوحده.","wrong":[{"i":0,"mis":"gen.reversed","note":"العبارة قلبت النقد: الشراء من أجل البيع تجاري حتى لو صار مرة وحدة."}],"tests":["معيار المشروع","نقد المعايير"]},{"n":206,"lo":"L2","sec":"LAW333-L2","type":"scenario","topic":"craft-farmer","stem":"مزارع في القصيم اشترى صناديق ليعبّئ فيها محصوله ثم يبيعه. وفقاً لمعيار الحرفة، شراء الصناديق يُعد:","options":["عملاً تجارياً لأنه شراء بقصد البيع","عملاً تجارياً لأنه يستهدف تحقيق الربح","عملاً تجارياً لاتصاله بحرفة تجارية","عملاً مدنياً لاتصاله بحرفة مدنية وهي الزراعة"],"answer":3,"why":"الشريحة ٨: إذا اشترى المزارع صناديق لتعبئتها بمحصوله ثم إعادة بيعها، فهذا عمل مدني لأنه متصل بحرفة مدنية وهي الزراعة. معيار الحرفة ينظر للحرفة اللي يتصل بها العمل. وبالعكس، عقد القرض اللي يبرمه التاجر متصلاً بحرفته التجارية يكون عملاً تجارياً.","wrong":[{"i":0,"mis":"l2.criteria-mix","note":"الشراء بقصد البيع يرتبط بالمضاربة ونقد معيار المشروع، أما معيار الحرفة فينظر للحرفة المتصل بها العمل."},{"i":1,"mis":"l2.criteria-mix","note":"الربح معيار المضاربة، والسؤال عن معيار الحرفة."},{"i":2,"mis":"gen.reversed","note":"الشريحة تنص أن الزراعة حرفة مدنية، مو تجارية."}],"tests":["معيار الحرفة","تطبيق المعيار على حالة"]},{"n":207,"lo":"L2","sec":"LAW333-L2","type":"list","topic":"conclusion","stem":"حسب خلاصة المحاضرة، يكون العمل تجارياً إذا:","options":["كان ينطوي على تداول الثروات، ويهدف إلى تحقيق ربح، ويتم في شكل مشروع، وضمن حرفة تجارية، حيثما تطلب النظام ذلك","كان يستهدف الربح فقط، ولو لم ينطوِ على تداول ولم يتم في شكل مشروع","تم في شكل مشروع منظم، ولو لم يهدف إلى تحقيق الربح","مارسه شخص محترف للتجارة، بغض النظر عن باقي المعايير"],"answer":0,"why":"الشريحة ٩: ما نعتمد على معيار واحد. يكون العمل تجارياً إذا اجتمع فيه تداول الثروات وهدف الربح وشكل المشروع والحرفة التجارية، حيثما تطلب النظام ذلك.","wrong":[{"i":1,"mis":"gen.partial","note":"اعتمد على معيار المضاربة لوحده، والخلاصة تقول إنه لا يمكن الاعتماد على معيار واحد."},{"i":2,"mis":"gen.partial","note":"اعتمد على المشروع لوحده، وكل معيار ما يكفي لوحده."},{"i":3,"mis":"gen.partial","note":"اعتمد على الحرفة لوحدها، والحرفة نفسها انتُقدت لأن النظرية ما حددت معياراً لها."}],"tests":["الخلاصة","تعدد المعايير"]},{"n":208,"lo":"L2","sec":"LAW333-L2","type":"figure","topic":"importance-map","stem":"الشكل يوضح أهمية التمييز بين العمل التجاري والعمل المدني. أي مما يلي يندرج تحت «تنفيذ الالتزامات»؟","img":"img/law333/L2-s10.png","options":["الإثبات","الاختصاص القضائي","الإعذار","معيار الحرفة"],"answer":2,"why":"الشريحة ١٠: أهمية التمييز في ٣ جوانب: الاختصاص القضائي، والإثبات، وتنفيذ الالتزامات. وتحت تنفيذ الالتزامات أربعة أمور: التضامن، والإعذار، والمهلة القضائية، والإفلاس.","wrong":[{"i":0,"mis":"l2.importance-list","note":"الإثبات جانب مستقل بجانب تنفيذ الالتزامات، مو من الأمور اللي تحته."},{"i":1,"mis":"l2.importance-list","note":"الاختصاص القضائي جانب مستقل أيضاً."},{"i":3,"mis":"gen.neighbor","note":"معيار الحرفة من ضوابط التفرقة، مو من أهمية التمييز."}],"tests":["أهمية التمييز","تنفيذ الالتزامات"]},{"n":209,"lo":"L2","sec":"LAW333-L2","type":"list","topic":"commercial-courts","stem":"تختص المحاكم التجارية بكل مما يلي، ما عدا:","options":["منازعات الشركاء في شركة المضاربة","الدعاوى والمخالفات الناشئة عن تطبيق أحكام نظام الإفلاس","الدعاوى والمخالفات الناشئة عن تطبيق أنظمة الملكية الفكرية","المنازعات المدنية وجميع المنازعات التي تخرج عن اختصاص المحاكم الأخرى"],"answer":3,"why":"الشريحة ١١: المنازعات المدنية وكل منازعة تخرج عن اختصاص المحاكم الأخرى من اختصاص المحاكم العامة. الخيارات الباقية كلها مذكورة في قائمة اختصاص المحاكم التجارية (الشريحة ١٢).","wrong":[{"i":0,"mis":"gen.keyword","note":"«المضاربة» هنا اسم نوع من الشركات، مو معيار المضاربة. ومنازعات شركائها من اختصاص المحاكم التجارية."},{"i":1,"mis":"l2.courts","note":"مذكورة صراحة ضمن اختصاص المحاكم التجارية."},{"i":2,"mis":"l2.courts","note":"مذكورة صراحة ضمن اختصاص المحاكم التجارية."}],"tests":["الاختصاص القضائي","المحاكم العامة","المحاكم التجارية"]},{"n":210,"lo":"L2","sec":"LAW333-L2","type":"scenario","topic":"commercial-court-threshold","stem":"مواطن غير تاجر رفع دعوى على تاجر في الرياض في منازعة ناشئة عن عقد تجاري، وقيمة المطالبة الأصلية ٦٠٠ ألف ريال. حسب الشرائح، المحكمة المختصة بنظر الدعوى هي:","options":["المحاكم العامة، لأن المدعي ليس تاجراً","المحاكم التجارية، لأن قيمة المطالبة الأصلية تتجاوز الحد المقرر","المحاكم العامة، لأن منازعات العقود لا تدخل في اختصاص المحاكم التجارية","المحاكم العامة، لأن قيمة المطالبة الأصلية أقل من مليون ريال"],"answer":1,"why":"الدعوى مقامة على التاجر في منازعة عقد تجاري، فتروح للمحاكم التجارية إذا تجاوزت قيمة المطالبة الحد. في المحاضرة ٢ (شريحة ١٢) الحد «تزيد على مائة ألف ريال». وفي شريحة الأعمال المختلطة (المحاضرة ٤، شريحة ١٧) الحد «تزيد عن خمسمائة ألف ريال». ٦٠٠ ألف أكثر من الحدين، فالجواب واحد على الشريحتين. انتبه: الرقم يختلف بين المحاضرتين، فاحفظ كل رقم مع محاضرته.","wrong":[{"i":0,"mis":"l2.courts","note":"العبرة بالمدعى عليه: الدعوى مقامة على التاجر والعقد تجاري. وشريحة الأعمال المختلطة تحيل للمحكمة العامة فقط إذا كان العمل مدنياً بالنسبة للمدعى عليه، وهذا مو حالنا."},{"i":2,"mis":"gen.reversed","note":"الشرائح تذكر صراحة أن منازعات العقود التجارية المقامة على التاجر من اختصاص المحاكم التجارية إذا تجاوزت قيمتها الحد."},{"i":3,"mis":"gen.detail","note":"ولا شريحة تذكر مليون ريال. الحد مائة ألف في المحاضرة ٢ وخمسمائة ألف في المحاضرة ٤، و٦٠٠ ألف تتجاوز الحدين."}],"tests":["الاختصاص القضائي","اختصاص المحاكم التجارية بمنازعات العقود التجارية","حد قيمة المطالبة الأصلية"]},{"n":211,"lo":"L2","sec":"LAW333-L2","type":"concept","topic":"freedom-of-evidence","stem":"أقر القانون التجاري «مبدأ حرية الإثبات» مراعاةً للطابع الخاص للمعاملات التجارية. معنى ذلك:","options":["يصح الإثبات بالشهادة أو القرائن أو أي من الوسائل الأخرى، وكذلك إثبات العكس، ما لم ينص النظام على خلاف ذلك","يُشترط الكتابة لإثبات المعاملات التجارية كما في التعاملات المدنية","يصح الإثبات بأي وسيلة، لكن إثبات العكس لا يكون إلا بالكتابة","يصح الإثبات بأي وسيلة في جميع التصرفات التجارية بلا أي استثناء"],"answer":0,"why":"الشريحة ١٣: قواعد الإثبات التجاري ما فيها قيود المدني مثل اشتراط الكتابة. فيصح الإثبات بالشهادة أو القرائن أو أي وسيلة، ويصح كذلك إثبات العكس، ما لم ينص النظام على غير ذلك. والدفاتر التجارية أيضاً وسيلة إثبات، سواء لمصلحة التاجر أو ضده.","wrong":[{"i":1,"mis":"l2.evidence-freedom","note":"اشتراط الكتابة من قيود التعاملات المدنية، وقواعد الإثبات التجاري ما فيها هذا القيد."},{"i":2,"mis":"gen.detail","note":"الشريحة تقول إن الحرية تشمل «إثبات العكس أيضاً»."},{"i":3,"mis":"gen.absolute","note":"فيه استثناءات تُشترط فيها الكتابة: عقد الشركة، وبيع السفينة، والأوراق التجارية، والترخيص باستعمال العلامة التجارية."}],"tests":["الإثبات","مبدأ حرية الإثبات"]},{"n":212,"lo":"L2","sec":"LAW333-L2","type":"list","topic":"writing-exceptions","stem":"استثناءً من مبدأ حرية الإثبات، تُشترط الكتابة في عدة تصرفات تجارية. أي مما يلي ليس منها حسب المحاضرة؟","options":["عقد الشركة","عقد بيع السفينة أو حصة منها","عقد القرض الذي يبرمه التاجر متصلاً بحرفته","عقد الترخيص باستعمال العلامة التجارية"],"answer":2,"why":"الشريحة ١٤ تذكر ٤ استثناءات: عقد الشركة، وعقد بيع السفينة أو حصة منها، والأوراق التجارية، وعقد الترخيص باستعمال العلامة التجارية. عقد القرض جاء في معيار الحرفة (الشريحة ٨)، مو في استثناءات الكتابة.","wrong":[{"i":0,"mis":"l2.evidence-freedom","note":"عقد الشركة أول استثناء في القائمة."},{"i":1,"mis":"gen.detail","note":"مذكور في القائمة، ويشمل بيع حصة من السفينة أيضاً."},{"i":3,"mis":"l2.evidence-freedom","note":"مذكور ضمن الاستثناءات."}],"tests":["استثناءات الإثبات","اشتراط الكتابة"]},{"n":213,"lo":"L2","sec":"LAW333-L2","type":"tf","topic":"evidence-law-1443","stem":"في المملكة العربية السعودية، يُطبق نظام الإثبات الصادر عام ١٤٤٣هـ على المعاملات المدنية فقط.","options":["صح","خطأ"],"answer":1,"why":"الشريحة ١٣: نظام الإثبات الصادر عام ١٤٤٣هـ يُطبق «على المعاملات المدنية والتجارية».","wrong":[{"i":0,"mis":"gen.partial","note":"أخذت نصف الحكم فقط، والنظام يُطبق على المعاملات المدنية والتجارية معاً."}],"tests":["نظام الإثبات ١٤٤٣هـ"]},{"n":214,"lo":"L2","sec":"LAW333-L2","type":"scenario","topic":"solidarity","stem":"اقترض ثلاثة تجار في جدة مبلغاً بدين تجاري لتمويل صفقة، ولم يتفقوا على التضامن ولا يوجد نص نظامي بذلك. حسب المحاضرة، يستطيع الدائن:","options":["أن يطالب كل واحد منهم بحصته فقط، لأنه لا تضامن إلا باتفاق أو نص نظامي","أن يطالب أي واحد منهم بكامل الدين، لأن العرف التجاري استقر على افتراض التضامن","أن يطالب أي واحد منهم بكامل الدين، بشرط إثبات اتفاق مكتوب على التضامن","أن يطالبهم مجتمعين فقط، ولا يجوز له الرجوع على أحدهم منفرداً"],"answer":1,"why":"الشريحة ١٥: في الدين التجاري استقر العرف على افتراض التضامن إذا تعدد المدينون، فيقدر الدائن يطالب أي واحد منهم بكامل الدين بدون اتفاق أو نص. أما الدين المدني فما فيه تضامن إلا باتفاق أو نص.","wrong":[{"i":0,"mis":"l2.solidarity-reversed","note":"هذه قاعدة الدين المدني، والدين في السؤال تجاري."},{"i":2,"mis":"l2.solidarity-reversed","note":"التضامن في الدين التجاري مفترض وما يحتاج اتفاقاً، والاتفاق يُحتاج لنفيه."},{"i":3,"mis":"gen.detail","note":"الشريحة تقول إن الدائن يعود على «أي من المدينين» ويطالبه بكامل الدين."}],"tests":["التضامن","الفرق بين الدين التجاري والمدني"]},{"n":215,"lo":"L2","sec":"LAW333-L2","type":"term","topic":"notice-def","stem":"«تصرف قانوني بأن يتخذ الدائن إجراءً شكلياً لتنبيه مدينه لتنفيذ التزامه أو الوفاء بما عليه من دين بحلول أجل الالتزام أو الدين». هذا تعريف:","options":["المهلة القضائية","التضامن","الإفلاس","الإعذار"],"answer":3,"why":"الشريحة ١٦: هذا نص تعريف الإعذار. الكلمة المفتاحية: «تنبيه المدين».","wrong":[{"i":0,"mis":"gen.neighbor","note":"المهلة القضائية أجل يعطيه القاضي للمدين، مو تنبيه من الدائن."},{"i":1,"mis":"gen.neighbor","note":"التضامن يخص تعدد المدينين ومطالبة أي واحد منهم بكامل الدين."},{"i":2,"mis":"gen.neighbor","note":"الإفلاس تنفيذ جماعي على أموال التاجر اللي توقف عن دفع ديونه التجارية."}],"tests":["الإعذار"]},{"n":216,"lo":"L2","sec":"LAW333-L2","type":"tf","topic":"notice-form","stem":"في الديون التجارية جرى العرف بأن الإعذار يتحقق بأي وسيلة، فقد يكون بخطاب عادي، ولا يُشترط أن يكون بطريقة رسمية.","options":["صح","خطأ"],"answer":0,"why":"الشريحة ١٦: في الديون المدنية يكون الإعذار بورقة رسمية تُعلن بواسطة أعوان القضاء، أما في الديون التجارية فيصح بأي وسيلة ولو بخطاب عادي.","wrong":[{"i":1,"mis":"l2.notice-form","note":"إذا اخترت «خطأ» فأنت طبقت قاعدة الدين المدني (الورقة الرسمية) على الدين التجاري."}],"tests":["الإعذار","الفرق بين الدين التجاري والمدني"]},{"n":217,"lo":"L2","sec":"LAW333-L2","type":"concept","topic":"grace-period","stem":"بخصوص المهلة القضائية (مهلة الوفاء) في الديون التجارية، العبارة الصحيحة حسب المحاضرة:","options":["لا يجوز منحها مطلقاً، ولم يُجز المنظم أي استثناء","يمنحها القاضي للمدين متى عجز عن الوفاء إذا استدعت حالته ذلك ولم ينتج عن ذلك ضرر جسيم للدائن","لا يصح للمحكمة منحها إلا في حدود ضيقة، واستثناءً أجاز المنظم منح المدين التاجر مهلة للوفاء بشروط محددة ومتشددة","تُمنح تلقائياً لكل مدين تاجر تأخر في الوفاء"],"answer":2,"why":"الشريحة ١٧: في الدين التجاري ما تُعطى المهلة إلا في حدود ضيقة، واستثناءً أجازها المنظم بشروط محددة ومتشددة. أما في الدين المدني فللقاضي أن يعطي المدين نظرة الميسرة إذا استدعت حالته، بشرط ما يتضرر الدائن ضرراً جسيماً.","wrong":[{"i":0,"mis":"gen.absolute","note":"كلمة «مطلقاً» غلط، لأن فيه استثناء أجازه المنظم بشروط محددة ومتشددة."},{"i":1,"mis":"l2.grace-period","note":"هذا وصف نظرة الميسرة في التعاملات المدنية، مو التجارية."},{"i":3,"mis":"gen.reversed","note":"العكس تماماً: الأصل في الدين التجاري التشدد في المهلة."}],"tests":["المهلة القضائية","نظرة الميسرة"]},{"n":218,"lo":"L2","sec":"LAW333-L2","type":"scenario","topic":"bankruptcy-civil-debt","stem":"تاجر أقمشة في المدينة المنورة منتظم في سداد ديونه التجارية، لكنه توقف عن دفع دين مدني عليه. حسب المحاضرة:","options":["لا يُشهر إفلاسه، لأن الإفلاس نظام تجاري لا يسري إلا على التجار الذين توقفوا عن سداد ديونهم التجارية","يُشهر إفلاسه لأنه تاجر توقف عن دفع دين، أياً كان نوعه","يُشهر إفلاسه لأن الإفلاس يسري على كل الديون متى اضطربت حالة المدين المادية","يُشهر إفلاسه، وتُغل يده عن أمواله المدنية فقط دون التجارية"],"answer":0,"why":"الشريحة ١٨: الأصل أن شهر إفلاس التاجر يشترط توقفه عن دفع ديونه التجارية. أما إذا توقف عن دفع دين مدني فلا يُشهر إفلاسه، لأن الإفلاس نظام تجاري.","wrong":[{"i":1,"mis":"l2.bankruptcy-civil-debt","note":"كونه تاجراً ما يكفي، لازم يكون الدين اللي توقف عنه تجارياً."},{"i":2,"mis":"gen.detail","note":"اضطراب الحالة المادية جزء من تعريف الإفلاس، لكن التعريف مربوط بالتوقف عن دفع الديون التجارية."},{"i":3,"mis":"gen.detail","note":"غل اليد يشمل إدارة كل أمواله والتصرف فيها، وأصلاً ما يُشهر إفلاسه في هذه الحالة."}],"tests":["الإفلاس","شرط الدين التجاري"]},{"n":301,"lo":"L3","sec":"LAW333-L3","type":"concept","topic":"definition","stem":"ما الصحيح بشأن تعريف المحل التجاري حسب المحاضرة؟","options":["عرّفه النظام السعودي تعريفاً تشريعياً بأنه مجموعة العناصر المادية التي يملكها التاجر","لا يوجد له تعريف تشريعي في النظام السعودي، وعرّفه الفقه بأنه أداة يستخدمها التاجر في ممارسة التجارة تتكون من عناصر مادية ومعنوية","عرّفه الفقه بأنه شخص معنوي له ذمة مالية مستقلة عن صاحبه التاجر","عرّفه نظام العلامات التجارية لأن العلامة التجارية أهم عناصره"],"answer":1,"why":"الشريحة صريحة: «لا يوجد تعريف تشريعي للمحل التجاري في النظام السعودي». والتعريف الموجود فقهي: أداة يستخدمها التاجر في ممارسة التجارة وتتكون من العناصر المادية والمعنوية وتشكّل كياناً مستقلاً عن صاحبه.","wrong":[{"i":0,"mis":"l3.legis-def","note":"عبارة «النظام السعودي» مألوفة فتغريك، لكن ما فيه تعريف تشريعي أصلاً، والتعريف الفقهي يشمل العناصر المعنوية بعد، مو المادية بس."},{"i":2,"mis":"l3.personality","note":"«كيان مستقل» في التعريف ما معناه شخصية معنوية. المحل ما له شخصية معنوية ولا ذمة مستقلة."},{"i":3,"mis":"gen.neighbor","note":"نظام العلامات التجارية يحكم عنصر العلامات فقط، لأن كل عنصر يخضع لنظامه. وهو ما عرّف المحل التجاري."}],"tests":["التعريف التشريعي","التعريف الفقهي"]},{"n":302,"lo":"L3","sec":"LAW333-L3","type":"concept","topic":"importance","stem":"ما الذي استدعى وجود نظام قانوني واحد للمحل التجاري حسب المحاضرة؟","options":["منح المحل التجاري شخصية معنوية مستقلة عن التاجر حتى تكون له ذمة مالية خاصة","إلغاء الأنظمة الخاصة بكل عنصر، مثل نظام العلامات التجارية ونظام الأسماء التجارية","أن عناصره ذات قيمة مالية عالية، فاحتيج إلى تمكين التاجر من التصرف في المحل ككيان واحد بدلاً من التصرف في كل عنصر منفرداً","أن العناصر المادية وحدها هي مصدر قيمة المحل، فيلزم بيعها مجتمعة"],"answer":2,"why":"الشريحة تقول إن عناصر المحل «تمتاز بقيمة مالية عالية» وتشكّل أدوات اقتصادية هامة، ولهذا جاءت الحاجة لنظام واحد «يمكن التاجر من التصرف في المحل التجاري ككيان واحد عوضا عن التصرف في كل عنصر من عناصره بشكل منفرد».","wrong":[{"i":0,"mis":"l3.personality","note":"المحل ما يتمتع بالشخصية المعنوية أصلاً، والتنظيم ما جاء يعطيه شخصية ولا ذمة."},{"i":1,"mis":"l3.single-entity","note":"التنظيم الموحّد ما يلغي استقلال العناصر. حسب التعريف الفقهي يبقى كل عنصر خاضع لنظامه الخاص."},{"i":3,"mis":"l3.material-movable","note":"بالعكس: قيمة المحل الاقتصادية تُستمد في الأساس من عناصره المعنوية."}],"tests":["أهمية تنظيم المحل التجاري","التصرف في المحل ككيان واحد"]},{"n":303,"lo":"L3","sec":"LAW333-L3","type":"scenario","topic":"movable","stem":"وهب تاجر في جدة جميع أمواله المنقولة لابنه، ولم يذكر محله التجاري بالاسم. هل يدخل المحل التجاري في هذه الهبة؟","options":["نعم، لأن المحل التجاري مال منقول (من المنقولات المعنوية) يخضع للنظام القانوني للمنقولات","لا، لأن المحل التجاري يُعامل معاملة العقار فلا يدخل في المنقولات","لا، لأن للمحل التجاري شخصية معنوية وذمة مالية مستقلة عن التاجر","تدخل البضائع والمعدات فقط، لأن العناصر المعنوية ليست من الأموال المنقولة"],"answer":0,"why":"الشريحة تضرب نفس المثال: «إذا وهب تاجر جميع أمواله المنقولة لشخص آخر فإن محله التجاري يدخل من ضمن هذه المنقولات». السبب إنه مال منقول، وتحديداً منقول معنوي.","wrong":[{"i":1,"mis":"l3.material-movable","note":"تخلط بين المحل والعقار. المحل منقول، والعقار نفسه من العناصر المستبعدة من المحل."},{"i":2,"mis":"l3.personality","note":"المحل ما له شخصية معنوية ولا ذمة مستقلة، فهو مال من أموال التاجر."},{"i":3,"mis":"l3.material-movable","note":"المحل منقول معنوي وقيمته أساساً من عناصره المعنوية، فيدخل كله في الهبة."}],"tests":["المحل التجاري من الأموال المنقولة","المحل التجاري من المنقولات المعنوية"]},{"n":304,"lo":"L3","sec":"LAW333-L3","type":"tf","topic":"debts","stem":"الديون التي نشأت نتيجة لأعمال استغلال المحل التجاري تُعتبر من عناصره عند بيعه.","options":["صح","خطأ"],"answer":1,"why":"خطأ. الديون من «العناصر المعنوية المستبعدة»، والشريحة تقول: «لا تعتبر ضمن عناصر المحل التجاري عند بيعه حتى لو نشأت كنتيجة لأعمال استغلال المحل التجاري».","wrong":[{"i":0,"mis":"l3.debts","note":"عبارة «نشأت نتيجة لاستغلال المحل» تغريك تحسبها جزء منه، لكن الشريحة قالت «حتى لو» نشأت من استغلاله فهي مستبعدة."}],"tests":["العناصر المعنوية المستبعدة","الديون"]},{"n":305,"lo":"L3","sec":"LAW333-L3","type":"scenario","topic":"commercial-character","stem":"افتتح د. خالد عيادة أسنان خاصة في المدينة المنورة، وافتتح أخوه ماجد بجانبها متجراً لبيع العطور. أي العبارات التالية صحيحة؟","options":["كلاهما محل تجاري، لأن لكل منهما ترخيصاً والتراخيص من العناصر المعنوية للمحل التجاري","متجر العطور محل تجاري، أما العيادة فليست محلاً تجارياً لأن مهنة الطب من قبيل الأعمال المدنية","العيادة وحدها محل تجاري، لأن مكاتب أصحاب المهن الحرة لها صفة تجارية خاصة","لا يُعد أي منهما محلاً تجارياً، لأن المحل التجاري لا يتمتع بالشخصية المعنوية"],"answer":1,"why":"من خصائص المحل إنه «يكتسب الصفة التجارية»، ولهذا ما تُعتبر مكاتب أصحاب المهن الحرة «كالطبيب والمهندس والمحامي» محال تجارية، لأن هذه المهن «تعتبر من قبيل الأعمال المدنية». أما متجر العطور فيبيع بضائع، فهو محل تجاري.","wrong":[{"i":0,"mis":"l3.liberal-professions","note":"وجود ترخيص ما يحوّل العيادة لمحل تجاري. مهنة الطب عمل مدني، والشريحة استبعدتها بالاسم."},{"i":2,"mis":"gen.reversed","note":"عكست الحكم: مكاتب المهن الحرة هي اللي ما تُعتبر محال تجارية."},{"i":3,"mis":"l3.personality","note":"عدم الشخصية المعنوية خاصية من خصائص المحل نفسه، وما تنفي إنه محل تجاري."}],"tests":["اكتساب الصفة التجارية","المهن الحرة أعمال مدنية"]},{"n":306,"lo":"L3","sec":"LAW333-L3","type":"concept","topic":"no-legal-personality","stem":"ما الأثر المترتب على أن المحل التجاري لا يتمتع بالشخصية المعنوية؟","options":["أنه لا يخضع للنظام القانوني للمنقولات في البيع والرهن","أنه لا يتمتع بذمة مالية مستقلة أو رأس مال مستقل","أنه لا يكتسب الصفة التجارية مثل مكاتب المهن الحرة","أنه لا يجوز التصرف فيه ككيان واحد، بل يُتصرف في كل عنصر منفرداً"],"answer":1,"why":"الشريحة تقول: «لا يكتسب المحل التجاري الشخصية المعنوية على عكس الحال في الشركات التجارية, أثر ذلك هو عدم تمتعه بذمة مالية مستقلة أو رأس مال مستقل».","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذي خاصية ثانية ثابتة للمحل: إنه منقول ويخضع لنظام المنقولات. عدم الشخصية ما يلغيها."},{"i":2,"mis":"l3.liberal-professions","note":"المحل يكتسب الصفة التجارية. الاستبعاد يخص مكاتب المهن الحرة، مو المحل التجاري."},{"i":3,"mis":"l3.single-entity","note":"بالعكس، هدف تنظيم المحل هو التصرف فيه ككيان واحد، وعدم الشخصية ما يمنع هذا."}],"tests":["عدم تمتع المحل بالشخصية المعنوية","الذمة المالية المستقلة"]},{"n":307,"lo":"L3","sec":"LAW333-L3","type":"concept","topic":"legal-aggregate","stem":"لماذا تعرضت نظرية المجموع القانوني للنقد؟","options":["لأنها خالية من أي مدلول قانوني يمكن الاستناد إليه لتحديد طبيعة المحل التجاري","لأنها تجعل للمحل ذمة مالية مستقلة عن صاحبه، فتتعارض مع مبدأ وحدة الذمة المالية ومع مبدأ عدم تمتع المحل بشخصية معنوية مستقلة عن مالكه","لأنها تعتبر المحل مالاً معنوياً منقولاً يدخل ضمن عناصر الذمة المالية لصاحبه","لأنها تجعل كل عنصر من عناصر المحل يحتفظ بطبيعته ونظامه الخاص"],"answer":1,"why":"نظرية المجموع القانوني ترى المحل «مجموعة قانونية من الأموال» لها «ذمة مالية مستقلة عن صاحب المحل التجاري»، ولهذا انتُقدت «لتعارضها مع مبدأ وحدة الذمة المالية ومع مبدأ عدم تمتع المحل التجاري بشخصية معنوية مستقلة عن مالكه».","wrong":[{"i":0,"mis":"l3.theory-mixup","note":"هذا المأخذ على نظرية المجموع الواقعي، مو المجموع القانوني."},{"i":2,"mis":"l3.theory-mixup","note":"هذا مضمون نظرية الملكية المعنوية، وما ذُكر كسبب لنقد المجموع القانوني."},{"i":3,"mis":"l3.theory-mixup","note":"احتفاظ كل عنصر بطبيعته ونظامه الخاص من مضمون نظرية المجموع الواقعي."}],"tests":["نظرية المجموع القانوني","نقد نظرية المجموع القانوني","مبدأ وحدة الذمة المالية"]},{"n":308,"lo":"L3","sec":"LAW333-L3","type":"tf","topic":"real-aggregate","stem":"يؤخذ على نظرية المجموع الواقعي أنها خالية من أي مدلول قانوني يمكن الاستناد إليه لتحديد طبيعة المحل التجاري القانونية.","options":["صح","خطأ"],"answer":0,"why":"صح. نظرية المجموع الواقعي ترى المحل «مجموعة واقعية من العناصر المادية والمعنوية تنسق لغرض ممارسة النشاط وتحقيق الربح»، والشريحة تقول عنها: «هذه النظرية خالية من أي مدلول قانوني يمكن الاستناد إليه لتحديد طبيعة المحل التجاري القانونية».","wrong":[{"i":1,"mis":"l3.theory-mixup","note":"لو اخترت خطأ فغالباً خلطتها بنقد المجموع القانوني (التعارض مع وحدة الذمة). مأخذ المجموع الواقعي هو غياب المدلول القانوني."}],"tests":["نظرية المجموع الواقعي","المأخذ على نظرية المجموع الواقعي"]},{"n":309,"lo":"L3","sec":"LAW333-L3","type":"concept","topic":"intangible-ownership","stem":"أي مما يلي ليس من مضمون نظرية الملكية المعنوية في الطبيعة القانونية للمحل التجاري؟","options":["المحل التجاري مال معنوي منقول يدخل ضمن عناصر الذمة المالية لصاحبه","يخوّل المحل صاحبه حق احتكاره واستغلاله والاحتجاج به أمام الغير","يحمي القانون المحل التجاري بدعوى المنافسة غير المشروعة","تكون للمحل التجاري ذمة مالية مستقلة عن صاحبه تضم الحقوق والديون الناشئة عن استغلاله"],"answer":3,"why":"الذمة المالية المستقلة اللي تضم الحقوق والديون هي مضمون نظرية المجموع القانوني. أما الملكية المعنوية فتجعل المحل «مال معنوي منقول يدخل من ضمن عناصر الذمة المالية لصاحب المحل»، يخوّله حق احتكاره واستغلاله والاحتجاج به أمام الغير، «ويحميه القانون بدعوى المنافسة غير المشروعة».","wrong":[{"i":0,"mis":"gen.partial","note":"هذا أول جزء من نص نظرية الملكية المعنوية، فهو من مضمونها."},{"i":1,"mis":"gen.partial","note":"حق الاحتكار والاستغلال والاحتجاج أمام الغير مذكور حرفياً في النظرية."},{"i":2,"mis":"l3.theory-mixup","note":"دعوى المنافسة غير المشروعة هي وسيلة الحماية المذكورة في نظرية الملكية المعنوية نفسها."}],"tests":["نظرية الملكية المعنوية","نظرية المجموع القانوني"]},{"n":310,"lo":"L3","sec":"LAW333-L3","type":"list","topic":"material-elements","stem":"أي مما يلي يُعد من العناصر المادية للمحل التجاري (غير المستبعدة)؟","options":["العقار الذي يُمارس فيه النشاط التجاري","الدفاتر التجارية والمراسلات","المهام والمعدات مثل الآلات والشاحنات والأثاث وأجهزة الحاسب الآلي","حق الإيجار"],"answer":2,"why":"العناصر المادية في الشرائح اثنين: البضائع، و«المهام والمعدات»، وهي منقولات مادية يستخدمها التاجر في استثمار محله، غرضها تيسير العمل وليست مخصصة للبيع. العقار والدفاتر من «العناصر المادية المستبعدة»، وحق الإيجار عنصر معنوي.","wrong":[{"i":0,"mis":"l3.excluded-material","note":"العقار مادي فعلاً لكنه مستبعد، ونقل ملكيته يحتاج إفراغ رسمي عند كتابة العدل."},{"i":1,"mis":"l3.excluded-material","note":"الدفاتر والمراسلات مستبعدة، وما تنتقل ملكيتها للمشتري ببيع المحل."},{"i":3,"mis":"gen.neighbor","note":"حق الإيجار من العناصر المعنوية (حق الانتفاع بالمكان المؤجر)، مو من المادية."}],"tests":["العناصر المادية","المهام والمعدات","العناصر المادية المستبعدة"]},{"n":311,"lo":"L3","sec":"LAW333-L3","type":"scenario","topic":"sale-excluded","stem":"باع فهد محله التجاري في الرياض إلى عبدالله، وكان فهد يملك أيضاً العقار الذي يقع فيه المحل، واتفقا على بيعه معه. أي العبارات التالية صحيحة حسب المحاضرة؟","options":["ينتقل العقار تلقائياً مع بيع المحل لأنه من العناصر المادية للمحل التجاري","يجب أن يتم نقل ملكية العقار بموجب إفراغ رسمي لدى كتابة العدل","تنتقل ملكية الدفاتر التجارية والمراسلات إلى عبدالله بمجرد بيع المحل","يكفي لنقل ملكية العقار تسليمه بالمناولة أو تركه للمشتري بعد التنازل عنه"],"answer":1,"why":"العقار من «العناصر المادية المستبعدة»: إذا تصرف مالك العقار والمحل بالبيع «فإن نقل ملكية العقار يجب أن تتم بموجب إفراغ رسمي لدى الجهة المختصة المتمثلة في كتابة العدل».","wrong":[{"i":0,"mis":"l3.excluded-material","note":"العقار مستبعد من عناصر المحل، فما ينتقل تلقائياً ببيع المحل."},{"i":2,"mis":"l3.excluded-material","note":"الدفاتر والمراسلات «لا تنتقل ملكيتها» ببيع المحل، لكن يجوز نقلها طوعاً."},{"i":3,"mis":"gen.neighbor","note":"المناولة أو الترك طريقة نقل الدفاتر والمراسلات طوعاً، مو طريقة نقل العقار."}],"tests":["العقارات عنصر مستبعد","الإفراغ الرسمي لدى كتابة العدل","الدفاتر التجارية والمراسلات"]},{"n":312,"lo":"L3","sec":"LAW333-L3","type":"term","topic":"goodwill","stem":"«القدرة التي يتمتع بها المحل التجاري وتمكنه من اجتذاب العملاء العرضيين بسبب موقعه أو اسمه أو علامته التجارية أو لأي سبب». هذا تعريف:","options":["حق الاتصال مع العملاء","السمعة التجارية","الاسم التجاري","العلامات التجارية"],"answer":1,"why":"الكلمة المفتاحية «العملاء العرضيين» تدلك على السمعة التجارية. أما حق الاتصال مع العملاء فهم «مجموعة من الأشخاص الذين استقروا على التعامل مع المحل التجاري».","wrong":[{"i":0,"mis":"l3.clientele-vs-goodwill","note":"حق الاتصال مع العملاء يخص العملاء المستقرين على التعامل مع المحل، مو العرضيين."},{"i":2,"mis":"gen.keyword","note":"الاسم مذكور في التعريف كسبب من أسباب جذب العملاء، لكنه عنصر مستقل: التسمية اللي تميّز المحل عن غيره."},{"i":3,"mis":"gen.keyword","note":"العلامة مذكورة كسبب للجذب، لكن تعريفها: دلالات أو إشارات أو رموز يضعها التاجر على منتجاته."}],"tests":["السمعة التجارية","حق الاتصال مع العملاء"]},{"n":401,"lo":"L4","sec":"LAW333-L4","type":"term","topic":"muqawala-definition","stem":"حسب الشرائح، يُقصد بالمقاولة:","options":["أن يقع العمل التجاري ولو لمرة واحدة بقصد تحقيق الربح","أن يتخذ العمل شكل المشروع المنظم المهيأ مسبقاً لأن يعمل بشكل مستمر","أن يصدر العمل المدني من تاجر لحاجات تجارته","أن يكون العمل تجارياً لأحد طرفيه ومدنياً بالنسبة للطرف الآخر"],"answer":1,"why":"هذا نص تعريف المقاولة في الشريحة 3. الكلمات المفتاحية: مشروع منظم + مهيأ مسبقاً + يعمل بشكل مستمر، يعني تكرار واحتراف وتنظيم، مو عمل يصير مرة وحدة.","wrong":[{"i":0,"mis":"l4.single-vs-enterprise","note":"هذا وصف الأعمال المنفردة اللي تكتسب الصفة التجارية ولو وقعت مرة وحدة، والمقاولة عكسها تحتاج تكرار واستمرار."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف الأعمال التجارية بالتبعية، مفهوم ثاني في نفس المحاضرة."},{"i":3,"mis":"gen.neighbor","note":"هذا تعريف العمل المختلط، مو المقاولة."}],"tests":["المقاولة","التكرار والاحتراف"]},{"n":402,"lo":"L4","sec":"LAW333-L4","type":"tf","topic":"art2-not-exhaustive","stem":"الأعمال بطريق المقاولة المحددة في المادة 2 من نظام المحكمة التجارية (الصناعة، التوريد، الوكالة بالعمولة، النقل، البيع بالمزاد، محلات ومكاتب الأعمال، إنشاء المباني) واردة على سبيل الحصر.","options":["صح","خطأ"],"answer":1,"why":"الشريحة 3 تقول صراحة إنها «واردة على سبيل المثال لا الحصر»، يعني ممكن تكون فيه أعمال ثانية على وجه المقاولة غير السبعة.","wrong":[{"i":0,"mis":"l4.list-exhaustive","note":"لأن المادة عدّدتها بأسمائها يحس إنها قائمة مقفلة، بس الشريحة نصت إنها أمثلة مو حصر."}],"tests":["المادة 2 من نظام المحكمة التجارية","المثال لا الحصر"]},{"n":403,"lo":"L4","sec":"LAW333-L4","type":"scenario","topic":"craftsman-outside-industry","stem":"أبو فهد خياط في حي شعبي بالمدينة المنورة، يفصّل الثياب لزبائنه بنفسه في محله الصغير معتمداً على مهارته الشخصية. حسب الشرائح، ما تكييف عمله؟","options":["يعد من مقاولة الصناعة لأنه يحوّل القماش إلى ثياب","يعد من مقاولة التوريد لأنه يقدم سلعة لزبائنه مقابل ثمن","يخرج من نطاق الصناعة لأنه أقرب إلى بيع الإنتاج أو المهارة الشخصية منه للمضاربة","يعد عملاً تجارياً بالتبعية لأنه يمارسه في محل"],"answer":2,"why":"الشريحة 4 نصت إن أعمال الحرفيين كالخياط والحداد والإسكافي تخرج من نطاق الصناعة، لكونها أقرب إلى بيع الإنتاج أو المهارة الشخصية منها للمضاربة، لأن مقومات المشروع (وسائل مادية وبشرية بقصد المضاربة والربح) مو متوفرة.","wrong":[{"i":0,"mis":"l4.craftsman-industry","note":"شاف كلمة تحويل (قماش إلى ثوب) فربطها بصور الصناعة، بس الصناعة تشترط مقومات المشروع، والحرفي مستثنى بالنص."},{"i":1,"mis":"gen.neighbor","note":"التوريد التزام بتقديم سلعة أو خدمة بصفة دورية ومنتظمة خلال فترة محددة، وهذا مو وصف الخياط اللي يفصّل لكل زبون."},{"i":3,"mis":"gen.keyword","note":"وجود محل ما يخلي العمل تجاري بالتبعية؛ التبعية تحتاج شخص بصفة التاجر وعمل مدني متصل بتجارته، والشريحة صنّفت الخياط كحرفي خارج الصناعة."}],"tests":["مقاولة الصناعة","الحرفيون","مقومات المشروع"]},{"n":404,"lo":"L4","sec":"LAW333-L4","type":"tf","topic":"supply-without-purchase","stem":"مؤسسة في جازان تصطاد الأسماك بنفسها وتوردها بصفة دورية ومنتظمة إلى المطاعم والمستشفيات ضمن مشروع منظم. توريدها يعد عملاً تجارياً رغم أنه لم يسبقه شراء.","options":["صح","خطأ"],"answer":0,"why":"الشريحة 5: التوريد عمل تجاري طالما تم على وجه المقاولة، حتى وإن لم يسبقه شراء، ومثّلت بأسماك تم صيدها ومحاصيل تمت زراعتها. المهم مقومات المشروع، مو مصدر السلعة.","wrong":[{"i":1,"mis":"l4.criterion-means","note":"يظن إن التوريد لازم يكون شراء ثم إعادة بيع عشان يصير تجاري، بس الشريحة قالت إنه تجاري سواء سبقه شراء أو إنتاج أو حتى بدون شراء ما دام على وجه المقاولة."}],"tests":["مقاولة التوريد","مقومات المشروع"]},{"n":405,"lo":"L4","sec":"LAW333-L4","type":"term","topic":"commission-agency-definition","stem":"عقد يلتزم بمقتضاه شخص بأن يقوم بتصرف قانوني باسمه الشخصي ولكن لحساب موكله مقابل أجر يتقاضاه. هذا تعريف:","options":["الوكالة بالعمولة","الوكالة العادية","السمسرة","التوريد"],"answer":0,"why":"مفتاح التعريف: «باسمه الشخصي ولكن لحساب موكله» مقابل أجر يسمى عمولة. هذا بالضبط تعريف الوكالة بالعمولة في الشريحة 6.","wrong":[{"i":1,"mis":"l4.commission-vs-agency","note":"في الوكالة العادية الوكيل يتصرف باسم موكله ولحسابه بموجب وكالة رسمية، مو باسمه الشخصي."},{"i":2,"mis":"l4.commission-vs-brokerage","note":"السمسار ما يكون طرف في التصرف، دوره يقرّب بين الطرفين بس."},{"i":3,"mis":"gen.neighbor","note":"التوريد التزام بتقديم سلعة أو خدمة بصفة دورية ومنتظمة، ما فيه تصرف باسم شخص لحساب شخص ثاني."}],"tests":["الوكالة بالعمولة","الوكالة العادية","السمسرة"]},{"n":406,"lo":"L4","sec":"LAW333-L4","type":"concept","topic":"brokerage-vs-commission","stem":"ما الذي يميّز السمسرة عن الوكالة بالعمولة حسب الشرائح؟","options":["أن السمسار يتصرف باسمه الخاص ولحساب موكله ثم ينقل الحقوق إليه","أن السمسار يجري التصرف باسم موكله ولحسابه بموجب وكالة رسمية","أن السمسار يدخل طرفاً في العقد فيكتسب الحقوق ويتحمل الالتزامات","أن السمسار يقرّب بين الطرفين دون أن يكون طرفاً فلا يلتزم بأي أثر من آثار العقد"],"answer":3,"why":"الشريحة 6: السمسار يقوم بالتقريب بين شخصين أو أكثر لإبرام صفقة دون أن يكون طرفاً فيها، فلا يلتزم بأي أثر من آثار العقد اللي توسط فيه. بعكس الوكيل بالعمولة اللي يدخل طرف في التصرف ويكتسب الحقوق ويتحمل الالتزامات ثم ينقلها لموكله.","wrong":[{"i":0,"mis":"l4.commission-vs-brokerage","note":"هذا وصف الوكيل بالعمولة نفسه، مو السمسار."},{"i":1,"mis":"l4.commission-vs-agency","note":"هذا وصف الوكالة العادية، مو السمسرة."},{"i":2,"mis":"gen.reversed","note":"قلب الفرق: الدخول كطرف واكتساب الحقوق وتحمل الالتزامات صفة الوكيل بالعمولة، والسمسار بالعكس ما يكون طرف."}],"tests":["السمسرة","الوكالة بالعمولة"]},{"n":407,"lo":"L4","sec":"LAW333-L4","type":"concept","topic":"transport-criterion","stem":"حسب الشرائح، ما العبرة في اعتبار النقل عملاً تجارياً؟","options":["نوع الوسيلة المستخدمة، فالنقل الجوي والبحري تجاري دون البري","أن يكون المنقول أشياء أو بضائع لا أشخاصاً","احتراف عملية النقل في شكل مشروع منظم ومهيأ مسبقاً لأن يعمل بشكل مستمر","أن يتم النقل ولو لمرة واحدة مقابل أجرة"],"answer":2,"why":"الشريحة 7 نصت: «فليست العبرة بالوسيلة وإنما باحتراف عملية النقل في شكل مشروع منظم ومهيءٍ مسبقاً لأن يعمل بشكل مستمر». والنقل يشمل أشخاص أو أشياء، براً أو بحراً أو جواً.","wrong":[{"i":0,"mis":"l4.criterion-means","note":"الشريحة نفت إن العبرة بالوسيلة؛ البر والبحر والجو كلها تجارية متى تمت على وجه المقاولة."},{"i":1,"mis":"gen.detail","note":"التعريف نفسه يقول «بنقل أشخاص أو أشياء»، فنقل الأشخاص داخل."},{"i":3,"mis":"l4.single-vs-enterprise","note":"النقل من الأعمال اللي لازم تكون على وجه المقاولة (تكرار واستمرار)، مو مرة وحدة."}],"tests":["مقاولة النقل","معيار المقاولة"]},{"n":408,"lo":"L4","sec":"LAW333-L4","type":"list","topic":"offices-liberal-professions","stem":"أي مما يلي لا يعد من مقاولة المحلات والمكاتب التجارية حسب الشرائح؟","options":["مكتب تخليص جمركي","مكتب محاماة","مكتب استقدام","مكتب تحصيل ديون"],"answer":1,"why":"الشريحة 8 فرّقت بين مكاتب الخدمات ومكاتب المهن الحرة كمكاتب المحامين والأطباء والمهندسين، وقالت إن الأخيرة لا تعد أعمالاً تجارية وتخضع لتنظيم قانوني مختلف. الباقي كلها أمثلة صريحة على المكاتب التجارية.","wrong":[{"i":0,"mis":"gen.detail","note":"مكاتب التخليص الجمركي مذكورة حرفياً في أمثلة المكاتب التجارية؛ ممكن يحسبها شغل حكومي فيستبعدها."},{"i":2,"mis":"gen.detail","note":"مكاتب الاستقدام من الأمثلة المذكورة في الشريحة."},{"i":3,"mis":"gen.detail","note":"مكاتب تحصيل الديون من أوائل الأمثلة في القائمة."}],"tests":["مقاولة المحلات والمكاتب التجارية","المهن الحرة"]},{"n":409,"lo":"L4","sec":"LAW333-L4","type":"scenario","topic":"government-auction","stem":"أعلنت جهة حكومية عن مزاد علني لبيع سيارات ومعدات مصادرة، وعن مزاد آخر لبيع أموال مدين تنفيذاً عليها، ولا تمارس هذه الجهة المزادات بصورة منتظمة. حسب الشرائح، ما تكييف هذه المزادات؟","options":["عمل تجاري لأن البيع يتم لمن يقدم أعلى ثمن","عمل تجاري لأن البيع بالمزاد مذكور في المادة 2 من نظام المحكمة التجارية","عمل مختلط: تجاري للمشتري ومدني للجهة الحكومية","لا تعد عملاً تجارياً لأنها مزايدات عرضية لا تتم بصورة منتظمة"],"answer":3,"why":"الشريحة 9: لا يمكن اعتبار المزايدات العرضية اللي ما تتم بصورة منتظمة عملاً تجارياً، كاللي تنفذها الجهات الحكومية على أموال تملكها أو تشرف على بيعها، مثل التنفيذ على أموال المدينين أو الأموال المصادرة. المزاد يصير تجاري بس لما يكون على وجه المقاولة (تكرار واحتراف).","wrong":[{"i":0,"mis":"gen.keyword","note":"البيع لمن يقدم أعلى ثمن هو تعريف البيع العلني، مو معيار تجاريته؛ المعيار التكرار والاحتراف."},{"i":1,"mis":"l4.single-vs-enterprise","note":"المادة 2 تذكر البيع بالمزاد بطريق المقاولة، والمزاد العرضي غير المنتظم مستثنى صراحة."},{"i":2,"mis":"gen.neighbor","note":"الشريحة حكمت على هذي المزايدات بإنها مو عمل تجاري لعدم انتظامها، وما صنّفتها مختلطة."}],"tests":["البيع بالمزاد العلني","المزايدات العرضية"]},{"n":410,"lo":"L4","sec":"LAW333-L4","type":"list","topic":"building-construction-scope","stem":"استقر الرأي على أن أعمال إنشاء المباني تشمل أعمالاً منها:","options":["حفر القنوات ومد خطوط السكك الحديدية","تحويل الرمل إلى زجاج وأعمال الطباعة","توريد الوقود للسيارات والسفن والطائرات","إبرام عقود النقل لحساب شركة النقل"],"answer":0,"why":"الشريحة 10: أعمال إنشاء المباني تشمل الهدم والترميم، وإنشاء الجسور والأنفاق والطرق والمطارات، وحفر القنوات ومد خطوط السكك الحديدية، ومختلف أعمال البنية التحتية من مد أنابيب المياه والغاز والكهرباء والهاتف.","wrong":[{"i":1,"mis":"gen.neighbor","note":"هذي أمثلة مقاولة الصناعة (تحويل الرمل إلى زجاج، والقضاء عدّ الطباعة منها)."},{"i":2,"mis":"gen.neighbor","note":"هذا مثال مقاولة التوريد."},{"i":3,"mis":"gen.neighbor","note":"هذا مثال الوكالة بالعمولة."}],"tests":["مقاولة إنشاء المباني"]},{"n":411,"lo":"L4","sec":"LAW333-L4","type":"term","topic":"accessory-definition","stem":"الأعمال التي تعتبر في الأصل مدنية إلا أنها تكتسب الصفة التجارية لصدورها من تاجر لحاجات تجارته هي:","options":["الأعمال التجارية على وجه المقاولة","الأعمال المختلطة","الأعمال التجارية بالتبعية","الأعمال التجارية المنفردة"],"answer":2,"why":"هذا تعريف الأعمال التجارية بالتبعية بالنص (الشريحة 11). المفتاح: أصلها مدني + صدرت من تاجر + لحاجات تجارته.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المقاولة أعمال تجارية أصلية تشترط التكرار والتنظيم، مو أعمال مدنية في الأصل."},{"i":1,"mis":"l4.mixed-vs-accessory","note":"المختلط عمل تجاري لطرف ومدني للطرف الثاني، والتعريف هنا عن عمل مدني ينقلب تجاري بسبب صفة التاجر وحاجات تجارته."},{"i":3,"mis":"gen.neighbor","note":"الأعمال المنفردة تكتسب الصفة التجارية بطبيعتها ولو وقعت مرة وحدة، مو أعمال مدنية في الأصل."}],"tests":["الأعمال التجارية بالتبعية"]},{"n":412,"lo":"L4","sec":"LAW333-L4","type":"list","topic":"accessory-two-components","stem":"يقتضي تطبيق نظرية الأعمال التجارية بالتبعية وجود مكونين رئيسين هما:","options":["التكرار والاحتراف، ووجود مشروع منظم يضمن استمرارية العمل","اتصاف الشخص بصفة التاجر، واتصال العمل المدني بشؤون تجارته","اتصاف الشخص بصفة التاجر، وأن يكون العمل تجارياً بطبيعته","أن يكون العمل تجارياً لأحد الطرفين ومدنياً للطرف الآخر"],"answer":1,"why":"الشريحة 11 ذكرت المكونين: اتصاف الشخص بصفة التاجر + اتصال العمل المدني بشؤون تجارته، وهما نفس الشرطين في الشريحة 13 (صفة التاجر، وأن يكون العمل متعلقاً بحاجات تجارة التاجر أو ناشئاً عنها).","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذي عناصر المقاولة، مو مكونات نظرية التبعية."},{"i":2,"mis":"gen.partial","note":"نصها صح (صفة التاجر) ونصها غلط: العمل في التبعية أصله مدني مو تجاري بطبيعته."},{"i":3,"mis":"l4.mixed-vs-accessory","note":"هذا وصف العمل المختلط، مو شروط التبعية."}],"tests":["شروط الأعمال التجارية بالتبعية","صفة التاجر"]},{"n":413,"lo":"L4","sec":"LAW333-L4","type":"concept","topic":"accessory-regulatory-basis","stem":"أي مما يلي يمثل الأساس التنظيمي لنظرية الأعمال التجارية بالتبعية؟","options":["أن الفرع يتبع الأصل، فشراء التاجر الأثاث لمحله يعد تجارياً تبعاً لصفته","أن المنطق يقضي بخضوع جميع أعمال التاجر لنظام قانوني واحد ومحكمة واحدة","أن من يدعي أن العمل تجاري بالتبعية يقع عليه عبء إثباته","نص المادة 2 فقرة (د) من نظام المحكمة التجارية على أن جميع العقود والتعهدات الحاصلة بين التجار أعمال تجارية"],"answer":3,"why":"الأساس التنظيمي هو أخذ المنظم السعودي بالنظرية نصاً: المادة 2 فقرة (د) من نظام المحكمة التجارية، ومعها المادة 16/1 من نظام المحاكم التجارية اللي تجعل المنازعات بين التجار بسبب أعمالهم الأصلية والتبعية من اختصاص المحاكم التجارية (الشريحة 12).","wrong":[{"i":0,"mis":"l4.bases-mixup","note":"هذا الأساس النظري (الفرع يتبع الأصل)."},{"i":1,"mis":"l4.bases-mixup","note":"هذا الأساس المنطقي."},{"i":2,"mis":"gen.neighbor","note":"هذي قاعدة إثبات الأعمال التجارية بالتبعية (الشريحة 15)، مو أساس النظرية."}],"tests":["أساس نظرية التبعية","المادة 2 فقرة (د)","المادة 16/1"]},{"n":414,"lo":"L4","sec":"LAW333-L4","type":"scenario","topic":"unrelated-civil-acts","stem":"عبدالله تاجر أجهزة إلكترونية في الرياض، اشترى سيارة عائلية لنقل أفراد أسرته، ودفع رسوم مدرسة أبنائه. حسب الشرائح، ما تكييف هذين العملين؟","options":["عملان مدنيان لأنه لا صلة لهما بتجارته","عملان تجاريان بالتبعية لأن من قام بهما تاجر","عملان مختلطان لأنهما تجاريان لعبدالله ومدنيان للطرف الآخر","شراء السيارة تجاري بالتبعية، ورسوم المدرسة مدنية"],"answer":0,"why":"الشريحة 11: الأعمال المدنية اللي يمارسها التاجر وما لها صلة بتجارته لا تكتسب الوصف التجاري، ومثّلت بشراء سيارة لنقل أفراد أسرته ودفع مصاريف التعليم والعلاج لأبنائه. صفة التاجر وحدها ما تكفي.","wrong":[{"i":1,"mis":"l4.accessory-unrelated","note":"نسي الشرط الثاني: لازم العمل يتصل بشؤون تجارته."},{"i":2,"mis":"l4.mixed-vs-accessory","note":"العمل أصلاً مدني بالنسبة لعبدالله لأنه ما له علاقة بتجارته، فما يصير تجاري من جهته."},{"i":3,"mis":"gen.keyword","note":"ربط شراء السيارة بمثال سيارة نقل البضائع، بس العبرة بالغرض: هنا لنقل الأسرة فهي مدنية."}],"tests":["الأعمال التجارية بالتبعية","اتصال العمل بالتجارة"]},{"n":415,"lo":"L4","sec":"LAW333-L4","type":"scenario","topic":"noncontractual-unfair-competition","stem":"صاحب محل عطور في جدة قلّد العلامة التجارية لمحل منافس، فالتزم بتعويض المنافس عن الضرر. حسب الشرائح، التزامه بالتعويض يعد:","options":["عملاً مدنياً لأن مصدر الالتزام ليس عقداً","عملاً تجارياً على وجه المقاولة","عملاً تجارياً بالتبعية لأنه التزام غير تعاقدي ناشئ عن المسؤولية التقصيرية للتاجر","عملاً مختلطاً لأنه تجاري للتاجر ومدني للمنافس"],"answer":2,"why":"الشريحة 14: الالتزامات غير التعاقدية (اللي مصدرها مو العقد) تعد كذلك أعمالاً تجارية بالتبعية، ومنها الأعمال الناشئة عن المسؤولية التقصيرية كالمنافسة غير المشروعة (تقليد العلامة التجارية، اغتصاب الاسم التجاري)، والتزام التاجر بتعويض الغير عن الضرر.","wrong":[{"i":0,"mis":"l4.accessory-noncontract","note":"يظن إن التبعية للعقود بس، والشريحة نصت إن الالتزامات غير التعاقدية تدخل."},{"i":1,"mis":"gen.neighbor","note":"المقاولة صورة من الأعمال الأصلية تحتاج مشروع منظم مستمر، والتعويض هنا التزام تابع لتجارة التاجر."},{"i":3,"mis":"l4.mixed-vs-accessory","note":"الشريحة صنّفت التزام التاجر بالتعويض الناشئ عن المنافسة غير المشروعة صراحة ضمن الأعمال التجارية بالتبعية، مو المختلطة."}],"tests":["الالتزامات غير التعاقدية","المسؤولية التقصيرية","المنافسة غير المشروعة"]},{"n":416,"lo":"L4","sec":"LAW333-L4","type":"tf","topic":"mixed-applicable-law","stem":"في العمل المختلط تُطبق قواعد القانون التجاري على الطرفين معاً لأن العمل تجاري بالنسبة لأحدهما.","options":["صح","خطأ"],"answer":1,"why":"الشريحة 17: استقر الرأي فقهياً على تطبيق قواعد القانون التجاري على الطرف التجاري، والقانون المدني على الطرف المدني. وفي الإثبات بالذات يلتزم الطرفان بقواعد وأحكام نظام الإثبات.","wrong":[{"i":0,"mis":"l4.mixed-court","note":"يحسب إن وجود طرف تجاري يجر الطرفين للقانون التجاري، بس كل طرف يُطبق عليه قانونه."}],"tests":["الأعمال المختلطة","القانون واجب التطبيق"]},{"n":417,"lo":"L4","sec":"LAW333-L4","type":"tf","topic":"accessory-proof-presumption","stem":"استقر الرأي على وجود قرينة مقتضاها أن جميع الأعمال التي يمارسها التاجر يُفترض أنها تتعلق بتجارته ما لم يثبت خلاف ذلك.","options":["صح","خطأ"],"answer":0,"why":"هذا نص الشريحة 15. والأصل إن من يدعي إن العمل تجاري بالتبعية عليه إثباته، ويصح الإثبات بأي وسيلة بما فيها البينات والقرائن، لكن القرينة تفترض إن أعمال التاجر متعلقة بتجارته إلى أن يثبت العكس.","wrong":[{"i":1,"mis":"gen.reversed","note":"يعكس القرينة ويحسب إن الأصل في أعمال التاجر إنها مدنية، والشريحة قالت العكس: يُفترض إنها متعلقة بتجارته ما لم يثبت خلاف ذلك."}],"tests":["إثبات الأعمال التجارية بالتبعية","القرينة"]},{"n":418,"lo":"L4","sec":"LAW333-L4","type":"scenario","topic":"mixed-competent-court","stem":"خالد موظف لا يمارس التجارة، أبرم مع شركة تجارية عقداً يعد تجارياً بالنسبة للشركة، ثم نشأ نزاع فرفع خالد دعوى على الشركة يطالبها بـ 700 ألف ريال. حسب الشرائح، المحكمة المختصة هي:","options":["المحكمة العامة لأن العمل مدني بالنسبة للمدعي خالد","المحكمة العامة دائماً لأن العمل المختلط لا تختص به المحكمة التجارية","المحكمة التجارية مهما كانت قيمة المطالبة","المحكمة التجارية لأن العمل تجاري للمدعى عليه والعقد تجاري وقيمة المطالبة تزيد عن 500 ألف ريال"],"answer":3,"why":"الشريحة 17: العبرة بصفة العمل بالنسبة للمدعى عليه. هنا المدعى عليه الشركة والعمل تجاري لها، فتختص المحكمة التجارية إذا كان من العقود التجارية وقيمة المطالبة تزيد عن خمسمائة ألف ريال (700 ألف أكثر من 500 ألف)، والمحكمة العامة في غير ذلك.","wrong":[{"i":0,"mis":"l4.mixed-court","note":"نظر لصفة العمل عند المدعي، بس الشريحة تحدد المحكمة حسب صفة العمل للمدعى عليه."},{"i":1,"mis":"gen.absolute","note":"تعميم غلط؛ العمل المختلط ممكن تختص به المحكمة التجارية إذا كان العمل تجاري للمدعى عليه وتحقق شرط العقد التجاري والقيمة."},{"i":2,"mis":"gen.partial","note":"نسي شرط القيمة: التجارية تختص إذا زادت المطالبة عن 500 ألف ريال، وإلا فالعامة."}],"tests":["الأعمال المختلطة","المحكمة المختصة"]},{"n":501,"lo":"L5","sec":"LAW333-L5","type":"term","topic":"trader-def","stem":"عرّفت المادة الأولى من نظام المحكمة التجارية التاجر بأنه:","options":["كل من باشر عملاً تجارياً ولو مرة واحدة بقصد الربح","كل من قُيّد اسمه في السجل التجاري ومسك الدفاتر التجارية","كل من اشتغل بالمعاملات التجارية واتخذها مهنة له","كل من فتح محلاً تجارياً يعمل فيه باسمه ولحسابه الخاص"],"answer":2,"why":"نص المادة الأولى: «كل من اشتغل بالمعاملات التجارية واتخذها مهنة له». الكلمة المفتاح «اتخذها مهنة»، وهي الاحتراف.","wrong":[{"i":0,"mis":"l5.occasional","note":"فيها قصد الربح، لكن العمل الواحد العارض ما يكفي. لازم احتراف بصفة دائمة ومنتظمة ومستمرة."},{"i":1,"mis":"l5.registry-proof","note":"القيد ومسك الدفاتر مجرد قرائن بسيطة للإثبات، وما لها علاقة بتعريف التاجر."},{"i":3,"mis":"l5.shop-required","note":"«باسمه ولحسابه» من الاستقلالية فتبان صحيحة، لكن المحل التجاري مو شرط أصلاً، والمادة ما ذكرته."}],"tests":["تعريف التاجر","المادة الأولى من نظام المحكمة التجارية"]},{"n":502,"lo":"L5","sec":"LAW333-L5","type":"list","topic":"three-conditions","stem":"يستلزم لاكتساب صفة التاجر وفق نظام المحكمة التجارية وما أكده الفقه والقضاء ثلاثة شروط. أي مما يلي ليس من هذه الشروط؟","options":["احتراف الأعمال التجارية","اتخاذ محل تجاري ثابت لمباشرة النشاط","الاستقلالية في مباشرة الأعمال التجارية","توافر الأهلية الواجبة لاحتراف التجارة"],"answer":1,"why":"الشروط الثلاثة هي الاحتراف والاستقلالية والأهلية. أما المحل التجاري فالشرائح صرّحت إنه «لا يلزم اتخاذ محل تجاري»، والسمسار والوكيل بالعمولة تجار ولو ما عندهم محل.","wrong":[{"i":0,"mis":"gen.partial","note":"هذا هو الشرط الأول بنصه، فما يصلح جواباً لسؤال «ليس منها»."},{"i":2,"mis":"gen.partial","note":"هذا الشرط الثاني. ممكن تختاره لو نسيت الاستقلالية لأنها أقل شهرة من الاحتراف."},{"i":3,"mis":"gen.partial","note":"هذا الشرط الثالث بنصه في الشريحة."}],"tests":["الشروط الثلاثة لاكتساب صفة التاجر","عدم لزوم المحل التجاري"]},{"n":503,"lo":"L5","sec":"LAW333-L5","type":"term","topic":"professionalism-def","stem":"يُقصد بالاحتراف كشرط لاكتساب صفة التاجر:","options":["أن يكون الشخص مستقلاً عن غيره في ممارسته للأعمال التجارية ويتحمل ما ينتج عنها من ربح أو خسارة","قيام الشخص بالأعمال التجارية بشرط أن تكون مهنته الوحيدة ومصدر رزقه الوحيد","قيام الشخص بالأعمال التجارية برأس مال كبير وبدرجة عالية من التنظيم المهني","قيام الشخص بالأعمال التجارية بصفة دائمة ومنتظمة ومستمرة وكوسيلة للارتزاق والتعيش"],"answer":3,"why":"تعريف الشريحة: «قيام الشخص بالأعمال التجارية بصفة دائمة ومنتظمة ومستمرة وكوسيلة للارتزاق والتعيش». احفظ الصفات الثلاث: دائمة، منتظمة، مستمرة.","wrong":[{"i":0,"mis":"l5.conditions-mixup","note":"هذا تعريف الاستقلالية (الشرط الثاني)، مو الاحتراف."},{"i":1,"mis":"l5.side-job","note":"فيها «الارتزاق» فتبان قريبة، لكن الشرائح نصت إنه ما يشترط تكون التجارة مهنته الوحيدة."},{"i":2,"mis":"gen.detail","note":"الشرائح قالت العكس: بتوافر الاحتراف يكتسب الشخص الصفة «بصرف النظر عن حجم رأس المال أو درجة التنظيم المهني»."}],"tests":["تعريف الاحتراف"]},{"n":504,"lo":"L5","sec":"LAW333-L5","type":"scenario","topic":"occasional-trade","stem":"سعد موظف في شركة أهلية. اشترى سيارة وباعها بربح، وبعد عدة أشهر اشترى سيارة ثانية وباعها، وهكذا على فترات متقطعة وطويلة. ما حكمه وفق الشرائح؟","options":["لا يُعد ذلك احترافاً مكسباً لصفة التاجر، لأن العمل عارض وعلى فترات متباعدة","يكتسب صفة التاجر لأنه اشترى بقصد البيع وحقق ربحاً","يكتسب صفة التاجر لأن العبرة بقصد الربح لا بتكرار العمل","لا يكتسب صفة التاجر لأن له مهنة أخرى هي وظيفته"],"answer":0,"why":"الشرائح ذكرت نفس المثال: شراء وبيع السيارات اللي تتخلله فترات متقطعة وطويلة «لا يعد من قبيل الاحتراف المكسب لصفة التاجر». العمل العارض أو المتباعد ما يحقق شرط الاحتراف.","wrong":[{"i":1,"mis":"l5.occasional","note":"قصد البيع والربح موجود فعلاً، لكن ينقصه الدوام والانتظام والاستمرار."},{"i":2,"mis":"gen.keyword","note":"عبارة «العبرة بالقصد» صحيحة بس في موضوع الربح (هل يتحقق أو لا)، والاحتراف بنفسه لازم فيه استمرار."},{"i":3,"mis":"l5.side-job","note":"النتيجة صحيحة لكن السبب غلط. وجود مهنة ثانية ما يمنع صفة التاجر (المحامي والمهندس ممكن يكونون تجاراً)، والسبب الحقيقي إن العمل عارض."}],"tests":["شرط الاحتراف","العمل العارض لا يكفي"]},{"n":505,"lo":"L5","sec":"LAW333-L5","type":"tf","topic":"sole-profession","stem":"يشترط لاكتساب صفة التاجر أن يكون العمل التجاري هو مهنة الشخص الوحيدة؛ فالمحامي أو المهندس الذي يمارس التجارة بصورة مستمرة لا يُعد تاجراً.","options":["صح","خطأ"],"answer":1,"why":"الشريحة: «ولا يشترط أن يكون العمل التجاري مهنة الشخص الوحيدة»، فيكتسب الشخص صفة التاجر بمجرد قيامه بالأعمال التجارية بصورة مستمرة، حتى لو عنده مهنة ثانية كالمحاماة أو الهندسة.","wrong":[{"i":0,"mis":"l5.side-job","note":"ممكن تحس إن التاجر لازم يكون متفرغ للتجارة، لكن الشريحة صريحة: المحامي والمهندس يكتسبون الصفة إذا تاجروا باستمرار."}],"tests":["الاحتراف مع وجود مهنة أخرى"]},{"n":506,"lo":"L5","sec":"LAW333-L5","type":"scenario","topic":"banned-vs-incapable","stem":"موظف عام تمنعه أنظمة وظيفته من التجارة، فتح مؤسسة يمارس فيها التجارة باستمرار ثم تعثر. وفي المقابل شخص مجنون باشر أعمالاً تجارية. أي العبارات التالية صحيحة وفق الشرائح؟","options":["كلاهما لا يكتسب صفة التاجر، ولا يجوز شهر إفلاس أي منهما","المجنون يُعتبر تاجراً حمايةً للغير، أما الموظف فلا يُعتبر تاجراً لأن الحظر يُبطل تصرفاته","الموظف يُعتبر تاجراً، لكنه يُعفى من الجزاءات التأديبية لأنه صار خاضعاً لالتزامات التجار","الموظف يُعتبر تاجراً ويجوز شهر إفلاسه مع تعرضه لجزاءاته التأديبية، أما المجنون فلا يكتسب صفة التاجر ولا يجوز شهر إفلاسه"],"answer":3,"why":"الحظر (مثل حظر الموظف العام) مقرر للمصلحة العامة وما يأثر على صحة التصرف، فيعتبر الموظف تاجراً ويجوز شهر إفلاسه «بغض النظر عما قد يتعرض له من جزاءات تأديبية». أما عديم الأهلية فتصرفه باطل، ومنعه مقرر لمصلحته وحمايته، فلا يكتسب صفة التاجر ولا يجوز شهر إفلاسه.","wrong":[{"i":0,"mis":"l5.capacity-vs-ban","note":"صحيحة بالنسبة للمجنون، لكن الموظف المحظور يعتبر تاجراً، لأن مخالف لوائح مهنته ما يُكافأ بإعفائه من التزامات التاجر."},{"i":1,"mis":"l5.capacity-vs-ban","note":"قلبت الحكمين: عديم الأهلية هو اللي يبطل تصرفه، أما الحظر فلا أثر له على صحة التصرف."},{"i":2,"mis":"gen.partial","note":"النص الأول صحيح، لكن الشرائح قالت إن هذا «لا يعفيه من المسؤولية والعقوبة» المقررة في أنظمة مهنته."}],"tests":["الموظف العام الممنوع من التجارة","الفرق بين الأهلية والحظر","شهر الإفلاس"]},{"n":507,"lo":"L5","sec":"LAW333-L5","type":"concept","topic":"illegal-activity","stem":"وفق الشرائح، ما حكم من يستتر في ممارسته لأعمال غير مشروعة (كبيع المخدرات) خلف ساتر القيام بأعمال مشروعة، من حيث اكتساب صفة التاجر؟","options":["يكتسب صفة التاجر بصورة مطلقة لأن نشاطه الظاهر مشروع","لا يكتسب صفة التاجر في أي حال لأن مشروعية العمل شرط ضروري لاكتسابها","لا يكتسب الصفة التجارية إلا في مواجهة الغير حسن النية، الذي يجوز له طلب شهر إفلاسه على أساس النشاط الظاهر المشروع","يكتسب صفة التاجر ويُشهر إفلاسه على أساس نشاطه المستتر غير المشروع لأنه نشاطه الحقيقي"],"answer":2,"why":"الشريحة: هذا الشخص «لا يكتسب الصفة التجارية إلا في مواجهة الغير حسن النية» لأن الغير يستفيد من نظرية الوضع الظاهر، فيطلب شهر إفلاسه على أساس النشاط الظاهر المشروع، مو على أساس النشاط المستتر غير المشروع.","wrong":[{"i":0,"mis":"gen.absolute","note":"أطلقت الحكم، والصحيح إن الصفة تثبت له في مواجهة الغير حسن النية فقط."},{"i":1,"mis":"l5.illegal-trade","note":"صحيح إن المشروعية شرط، لكن الشرائح استثنت حماية الغير حسن النية بنظرية الوضع الظاهر."},{"i":3,"mis":"gen.reversed","note":"العكس هو الصحيح: شهر الإفلاس يكون على أساس النشاط الظاهر المشروع، مو المستتر غير المشروع."}],"tests":["مشروعية العمل التجاري","نظرية الوضع الظاهر","الغير حسن النية"]},{"n":508,"lo":"L5","sec":"LAW333-L5","type":"concept","topic":"partners-status","stem":"اكتسبت شركة الصفة التجارية. ما أثر ذلك على الشركاء فيها وفق الشرائح؟","options":["يكتسب جميع الشركاء صفة التاجر تبعاً للشركة","لا يكتسب أي شريك صفة التاجر بلا استثناء، لاستقلال الشخصية المعنوية للشركة","يكتسب صفة التاجر الشركاء المساهمون في الشركة المساهمة فقط لأنهم يملكون أسهمها","لا يكتسب الشركاء صفة التاجر لاستقلال الشخصية المعنوية، إلا الشركاء المتضامنين في شركتي التضامن والتوصية البسيطة لمسؤوليتهم التضامنية عن ديون الشركة"],"answer":3,"why":"الشريحة: اكتساب الشركة الصفة التجارية «لا يؤدي لاكتساب الصفة التجارية بالنسبة للشركاء فيها» لاستقلال الشخصية المعنوية، ويستثنى من ذلك الشركاء المتضامنون في شركتي التضامن والتوصية البسيطة بسبب مسؤوليتهم التضامنية.","wrong":[{"i":0,"mis":"l5.partners","note":"الشخصية المعنوية للشركة مستقلة عن الشركاء، فصفة الشركة ما تنتقل لهم تلقائياً."},{"i":1,"mis":"gen.absolute","note":"القاعدة صحيحة، لكنك نسيت الاستثناء: المتضامنون في شركتي التضامن والتوصية البسيطة."},{"i":2,"mis":"gen.neighbor","note":"خلطت في نوع الشركة ونوع الشريك. الاستثناء للمتضامنين بسبب مسؤوليتهم التضامنية، مو للمساهمين."}],"tests":["الشخصية المعنوية للشركة","الشركاء المتضامنون"]},{"n":509,"lo":"L5","sec":"LAW333-L5","type":"tf","topic":"profit-intent","stem":"يشترط لاكتساب صفة التاجر أن يتحقق الربح فعلياً وأن يكون كبيراً، فلا يكفي مجرد قصد الربح.","options":["صح","خطأ"],"answer":1,"why":"الشريحة: «لا يشترط في الربح أن يكون كبيراً ولا يشترط تحقق الربح فعلياً فتوفر القصد فقط يكفي والعبرة بالقصد وليس بالنتيجة». المطلوب إن الاحتراف يكون بقصد الربح، ومثال العمل اللي ما يقوم على الربح: سحب الكمبيالات.","wrong":[{"i":0,"mis":"l5.profit-result","note":"ممكن تربط التجارة بالكسب الفعلي، لكن الشرائح تعتد بالقصد مو بالنتيجة."}],"tests":["قصد الربح","العبرة بالقصد لا بالنتيجة"]},{"n":510,"lo":"L5","sec":"LAW333-L5","type":"concept","topic":"proof","stem":"تمسّك شخص بأنه تاجر مستنداً إلى قيده في السجل التجاري ومسكه للدفاتر التجارية. ما قيمة ذلك في إثبات صفة التاجر وفق الشرائح؟","options":["قرائن بسيطة ومظاهر يُستعان بها في الإثبات ويمكن إثبات عكسها، ولقاضي الموضوع التحقق من الاحتراف الفعلي","دليل قاطع على صفة التاجر لا يجوز إثبات عكسه","لا قيمة لها في الإثبات، والعبرة بوصف الشخص لنفسه بالتاجر في عقوده","تنقل عبء الإثبات إلى خصمه لأن صفة التاجر مفترضة في كل من قُيّد في السجل"],"answer":0,"why":"الأصل إن صفة التاجر غير مفترضة، واللي يتمسك بها عليه عبء الإثبات. والقيد ومسك الدفاتر ومظاهر الشهرة «ليست هذه إلا قرائن بسيطة ومظاهر يستعان بها في الإثبات»، ويمكن إثبات عكسها، وقاضي الموضوع يتحقق من وجود الاحتراف الفعلي.","wrong":[{"i":1,"mis":"l5.registry-proof","note":"القيد يبان رسمياً وقوياً، لكنه قرينة بسيطة يمكن إثبات عكسها، وما يعتبر دليلاً كافياً."},{"i":2,"mis":"gen.absolute","note":"هي مو بلا قيمة، بل قرائن يُستعان بها. ووصف الشخص لنفسه بالتاجر ما يثبت له الصفة التجارية أصلاً."},{"i":3,"mis":"gen.reversed","note":"العكس هو الصحيح: صفة التاجر «غير مفترضة»، وعبء الإثبات على اللي يتمسك بها."}],"tests":["إثبات الاحتراف","عبء الإثبات","القرائن البسيطة"]},{"n":511,"lo":"L5","sec":"LAW333-L5","type":"tf","topic":"start-end-status","stem":"يُعد الشخص تاجراً منذ اللحظة التي تتجه فيها إرادته لاحتراف الأعمال التجارية ويعبّر عنها بمظهر خارجي كفتح محل تجاري أو تأسيس شركة، وتنتهي صفته التجارية بانتهاء آخر عمل يقوم به مع نية الاعتزال، إلا في حال التصفية فتظل قائمة طيلة فترة التصفية.","options":["صح","خطأ"],"answer":0,"why":"هذا نفس كلام «الخلاصة» في شريحة إثبات الاحتراف: البداية من اتجاه الإرادة مع التعبير عنها بمظهر خارجي، والنهاية بآخر عمل مع نية الاعتزال، والصفة تبقى طول فترة التصفية.","wrong":[{"i":1,"mis":"gen.detail","note":"ممكن تشك في استثناء التصفية أو في لحظة البداية، لكن الاثنين مذكورين في الخلاصة."}],"tests":["بداية الصفة التجارية","انتهاء الصفة التجارية","فترة التصفية"]},{"n":512,"lo":"L5","sec":"LAW333-L5","type":"scenario","topic":"independence-manager","stem":"عبدالله مدير تنفيذي لشركة مساهمة، يباشر يومياً وبصفة مستمرة صفقات تجارية بقصد الربح لصالح الشركة. هل يكتسب صفة التاجر؟","options":["نعم، لأنه يحترف الأعمال التجارية بصفة دائمة ومنتظمة وبقصد الربح","لا، لأنه لا يملك محلاً تجارياً خاصاً به","لا، لأنه يعمل باسم ولحساب الشركة ولا يتحمل مخاطر ما ينتج عن هذه الأعمال، فينقصه شرط الاستقلالية","نعم، قياساً على الوكيل بالعمولة الذي يُعد تاجراً رغم عمله لحساب الغير"],"answer":2,"why":"الاستقلالية معناها إن الشخص «يعمل باسمه ولحسابه الخاص» ويتحمل الربح والخسارة. والشرائح قالت إن احتراف الأعمال بقصد الربح «لا يعد كافياً» إذا ما كان لحسابه، واستشهدت بمدير الشركة المساهمة لأنه يشتغل لحساب الشركة.","wrong":[{"i":0,"mis":"gen.partial","note":"شرط الاحتراف متوفر فعلاً، لكن الشروط ثلاثة، وعبدالله ناقصه شرط الاستقلالية."},{"i":1,"mis":"l5.shop-required","note":"النتيجة صحيحة والسبب غلط. المحل التجاري مو شرط، والسبب الحقيقي هو غياب الاستقلالية."},{"i":3,"mis":"l5.agent-commission","note":"الوكيل بالعمولة حالة خاصة: أعماله تجارية بطبيعتها ويمارسها باسمه ولحسابه. هذا ما ينطبق على مدير الشركة."}],"tests":["شرط الاستقلالية","مدير الشركة المساهمة"]},{"n":513,"lo":"L5","sec":"LAW333-L5","type":"scenario","topic":"commission-agent","stem":"ماجد وكيل بالعمولة، يحترف إبرام صفقات باسمه لحساب موكليه مقابل عمولة، وليس له محل تجاري، وبعض الصفقات التي يبرمها لحساب موكله مدنية. ما حكمه وفق الشرائح؟","options":["لا يُعد تاجراً لأنه يعمل لحساب الغير مثل مدير الشركة المساهمة","لا يُعد تاجراً لأنه ليس له محل تجاري","يُعد تاجراً في الصفقات التجارية فقط دون الصفقات المدنية","يُعد تاجراً، لأن تجارية الوكالة بالعمولة أساسها احترافه لها وليس طبيعة الأعمال التي يقوم بها"],"answer":3,"why":"الشرائح: «السمسار والوكيل بالعمولة يعدان تاجرين ولو لم يكن لهم محل تجاري»، و«يعد الوكيل بالعمولة تاجراً ولو كانت الأعمال التي يقوم بها لحساب موكله مدنية»، لأن تجارية الوكالة بالعمولة أساسها الاحتراف، مو طبيعة الأعمال نفسها.","wrong":[{"i":0,"mis":"l5.agent-commission","note":"الاثنين يشتغلون لحساب الغير، لكن الوكيل بالعمولة أعماله تجارية بطبيعتها ويمارسها باسمه ولحسابه، فيعتبر تاجراً."},{"i":1,"mis":"l5.shop-required","note":"المحل التجاري مو شرط، وهذي من نتائج شرط الاستقلالية."},{"i":2,"mis":"gen.partial","note":"تبان حلاً وسطاً، لكن الشرائح نصت إن صفة الأعمال التجارية أو المدنية «لا تغير من الصفة التجارية للوكالة بالعمولة»."}],"tests":["الوكيل بالعمولة والسمسار","عدم لزوم المحل التجاري"]},{"n":514,"lo":"L5","sec":"LAW333-L5","type":"scenario","topic":"apparent-hidden","stem":"تركي يمارس تجارة الأقمشة باسمه أمام الناس، لكن الأرباح والخسائر كلها لحساب صديقه فيصل اللي يفضّل يبقى بعيداً عن الصورة. تعثرت التجارة. وفق الرأي الراجح، من يكتسب صفة التاجر؟","options":["تركي فقط لأنه الظاهر أمام المتعاملين","فيصل فقط لأن التجارة لحسابه","كلاهما يكتسبان صفة التاجر","لا أحد منهما، لأن الظاهر لا يتاجر لحسابه والمستتر لا يتاجر باسمه"],"answer":2,"why":"الرأي الراجح: «كليهما يكتسبان صفة التاجر». المستتر عشان ما يتهرب من الآثار مثل شهر الإفلاس، والظاهر بإعمال نظرية الظاهر حمايةً للغير اللي تعامل معه على إنه تاجر.","wrong":[{"i":0,"mis":"l5.hidden-trader","note":"هذا نصف الحكم: الظاهر تاجر بنظرية الظاهر، لكن المستتر بعد تاجر."},{"i":1,"mis":"l5.hidden-trader","note":"تطبيق شرط الاستقلالية يخليك تختار المستتر بس، لكن الرأي الراجح يعتبر الظاهر تاجراً بعد، حمايةً للغير."},{"i":3,"mis":"gen.reversed","note":"هذا عكس الرأي الراجح، وكأنه يعطي الاثنين فرصة يتهربون من آثار التجارة."}],"tests":["التاجر الظاهر والتاجر المستتر","نظرية الظاهر"]},{"n":515,"lo":"L5","sec":"LAW333-L5","type":"term","topic":"capacity-def","stem":"الأهلية هي الشرط الثالث لاكتساب صفة التاجر. كيف عرّفتها الشرائح؟","options":["أن يكون الشخص مستقلاً عن غيره في ممارسته للأعمال ويتحمل ربحها وخسارتها","قدرة المرء وصلاحيته على مباشرة التصرفات القانونية","بلوغ الشخص ثمانية عشر عاماً وقيده في السجل التجاري","قيام الشخص بالأعمال التجارية بصفة دائمة ومنتظمة ومستمرة"],"answer":1,"why":"تعريف الشريحة: الأهلية هي «قدرة المرء وصلاحيته على مباشرة التصرفات القانونية». ومباشرة الأعمال التجارية من التصرفات القانونية اللي تحتاج أهلية، وهي شرط أساسي للأفراد مو للشركات.","wrong":[{"i":0,"mis":"l5.conditions-mixup","note":"هذا تعريف الاستقلالية (الشرط الثاني)."},{"i":2,"mis":"gen.partial","note":"18 سنة هو سن الرشد، لكنه مو تعريف الأهلية، والقيد في السجل مو شرط أصلاً."},{"i":3,"mis":"l5.conditions-mixup","note":"هذا تعريف الاحتراف (الشرط الأول)."}],"tests":["تعريف الأهلية"]},{"n":516,"lo":"L5","sec":"LAW333-L5","type":"list","topic":"age-majority","stem":"نصت المادة الرابعة من نظام المحكمة التجارية على أن «كل من كان رشيداً أو بلغ سن الرشد فله الحق أن يمارس مهنة التجارة بأنواعها». كم سن الرشد في المملكة وفقاً لقرار مجلس الشورى رقم ١١٤ وتاريخ ٥/١١/١٣٧٤هـ؟","options":["16 سنة","21 سنة","18 سنة","15 سنة"],"answer":2,"why":"الشريحة: «وسن الرشد في المملكة هو 18 سنة وفقاً لقرار مجلس الشورى رقم ١١٤». ومع بلوغ السن لازم يكون الشخص رشيداً (غير مصاب بعارض من عوارض الأهلية)، والذكر والأنثى في هذا سواء.","wrong":[{"i":0,"mis":"gen.detail","note":"رقم قريب ويشتت، وممكن تخلطه مع عمر القاصر في أمثلة المحاضرة. السن المعتمد في الشريحة 18."},{"i":1,"mis":"gen.detail","note":"21 سنة ممكن تكون في بالك من أنظمة ثانية، لكن الشريحة حددت 18 سنة."},{"i":3,"mis":"gen.detail","note":"رقم ما ورد في الشرائح، والسن المحدد بقرار مجلس الشورى 18 سنة."}],"tests":["المادة الرابعة من نظام المحكمة التجارية","سن الرشد","قرار مجلس الشورى رقم ١١٤"]},{"n":517,"lo":"L5","sec":"LAW333-L5","type":"scenario","topic":"minor-permission","stem":"نواف عمره 16 سنة، وأذن له وليه بالإتجار في بيع الجوالات فقط (إذناً مقيداً). ما حكمه وفق الشرائح؟","options":["لا يجوز للولي الإذن له، وإنما للولي أن ينشئ له تجارة جديدة يديرها نيابةً عنه","يُعتبر كامل الأهلية في جميع التصرفات التجارية حتى ما لم يُؤذن له فيه","يُعتبر كامل الأهلية فيما أُذن له فيه وفي التقاضي فيه، فيكتسب صفة التاجر ويلتزم بآثارها القانونية","لا يكتسب صفة التاجر لأن الإذن المقيد لا يُعتد به، والمعتبر هو الإذن المطلق فقط"],"answer":2,"why":"بمقتضى المادة الرابعة ما يجوز للقاصر ممارسة التجارة، لكن «يجوز لوليه أن يأذن له بالإتجار بشكل مطلق أو مقيد، وفي كلتا الحالتين يعتبر القاصر كامل الأهلية فيما أذن له فيه وفي التقاضي فيه». وانتبه: الولي ما ينشئ للقاصر تجارة جديدة، له بس يستمر في تجارة آلت للقاصر بإذن المحكمة.","wrong":[{"i":0,"mis":"l5.minor-trade","note":"فيها غلطتين: الولي يجوز له الإذن، ومو له إنه ينشئ للقاصر تجارة جديدة."},{"i":1,"mis":"gen.absolute","note":"الأهلية الكاملة محصورة «فيما أذن له فيه وفي التقاضي فيه» بس، مو في كل التصرفات."},{"i":3,"mis":"l5.minor-trade","note":"الشريحة نصت إن الإذن يكون «بشكل مطلق أو مقيد»، وفي الحالتين يعتبر القاصر كامل الأهلية فيما أُذن له فيه."}],"tests":["أهلية القاصر","إذن الولي بالإتجار","المادة الرابعة من نظام المحكمة التجارية"]},{"n":601,"lo":"L6","sec":"LAW333-L6","type":"list","topic":"merchant-obligations","stem":"«باكتساب الشخص صفة التاجر يصبح في مركز قانوني يفرض عليه بعض الالتزامات». أي مما يلي ليس من الالتزامات اللي عددتها المحاضرة؟","options":["مراعاة الدين وآداب المهنة","القيد في الغرفة التجارية","مسك دفتر الخزانة (الصندوق)","القيد في السجل التجاري"],"answer":2,"why":"الالتزامات الأربعة في الشريحة: مراعاة الدين وآداب المهنة، مسك الدفاتر التجارية، القيد في السجل التجاري، القيد في الغرفة التجارية. ودفتر الخزانة بالذات من الدفاتر الاختيارية، فما يمكن يكون التزام على التاجر.","wrong":[{"i":0,"mis":"gen.partial","note":"ممكن يحسبها نصيحة أخلاقية بس، لكنها أول بند في قائمة الالتزامات بالنص."},{"i":1,"mis":"gen.partial","note":"ينساها لأنها تشبه السجل التجاري، لكن الغرفة التجارية بند مستقل في القائمة."},{"i":3,"mis":"gen.partial","note":"القيد في السجل التجاري من الالتزامات الأربعة صراحة."}],"tests":["merchant-obligations","optional-books"]},{"n":602,"lo":"L6","sec":"LAW333-L6","type":"list","topic":"bookkeeping-importance","stem":"أي مما يلي ليس من أوجه أهمية مسك الدفاتر التجارية حسب المحاضرة؟","options":["التقدير الصحيح للزكاة والضريبة","بيان المركز المالي الحقيقي","معرفة أسباب الإفلاس","تحديد مدة التقادم للحقوق التجارية"],"answer":3,"why":"الأهمية أربع نقاط: التقدير الصحيح للزكاة والضريبة، بيان المركز المالي الحقيقي، وسيلة للإثبات، معرفة أسباب الإفلاس. التقادم مو منها، وبالعكس المحاضرة قالت إن مدة حفظ الدفاتر «ليست مدة تقادم».","wrong":[{"i":0,"mis":"gen.partial","note":"أول بند في قائمة الأهمية بالنص، ومرتبط كمان بأثر احتساب الزكاة تقديرياً لو ما انمسكت الدفاتر."},{"i":1,"mis":"gen.partial","note":"بند صريح: الدفاتر تبيّن المركز المالي الحقيقي للتاجر."},{"i":2,"mis":"gen.partial","note":"تبان فائدة غريبة، لكنها آخر بند في الشريحة بالنص."}],"tests":["bookkeeping-importance"]},{"n":603,"lo":"L6","sec":"LAW333-L6","type":"tf","topic":"who-must-keep-books","stem":"صح أو خطأ: «التاجر الأجنبي والشريك المتضامن كلاهما مستثنى من مسك الدفاتر التجارية».","options":["صح","خطأ"],"answer":1,"why":"مسك الدفاتر «واجب على كل من اكتسب صفة التاجر، سواء شخص طبيعي أم اعتباري، سعودي أم اجنبي». المستثنى بس: التاجر اللي رأس ماله ما يزيد عن مئة ألف ريال، والشريك المتضامن. فالعبارة نصها صح (المتضامن) ونصها غلط (الأجنبي)، وبالتالي هي خطأ.","wrong":[{"i":0,"mis":"l6.exempt","note":"الشريك المتضامن فعلاً مستثنى، فيغرّه نص العبارة الصحيح وينسى إن الأجنبي ملزم مثل السعودي."}],"tests":["who-must-keep-books","exemptions"]},{"n":604,"lo":"L6","sec":"LAW333-L6","type":"scenario","topic":"exemption-capital","stem":"سعد عنده بقالة في المدينة المنورة رأس مالها ٨٠ ألف ريال، وخالد عنده محل قطع غيار رأس ماله ٣٠٠ ألف ريال، والاثنين اكتسبوا صفة التاجر. حسب المحاضرة، مين المستثنى من مسك الدفاتر التجارية؟","options":["سعد فقط، لأن رأس ماله لا يزيد عن مئة ألف ريال","خالد فقط، لأن رأس ماله يزيد عن مئة ألف ريال","الاثنين مستثنون لأنهم أشخاص طبيعيون مو شركات","ولا واحد منهم، لأن مسك الدفاتر واجب على كل تاجر بلا أي استثناء"],"answer":0,"why":"من المستثنين «التاجر الذي لا يزيد رأس ماله عن مئة ألف ريال». سعد ٨٠ ألف يعني تحت الحد فهو مستثنى، وخالد فوق الحد فيلزمه مسك الدفاتر.","wrong":[{"i":1,"mis":"gen.reversed","note":"قلب الحد: الاستثناء لصاحب رأس المال الصغير (ما يزيد عن ١٠٠ ألف)، مو الكبير."},{"i":2,"mis":"l6.exempt","note":"الالتزام يشمل الشخص الطبيعي والاعتباري، فكونه فرد مو شركة ما يعفيه."},{"i":3,"mis":"gen.absolute","note":"صحيح إن الأصل الوجوب، لكن الشريحة ذكرت استثناءين، منهم التاجر اللي رأس ماله ما يزيد عن مئة ألف."}],"tests":["exemptions","who-must-keep-books"]},{"n":605,"lo":"L6","sec":"LAW333-L6","type":"term","topic":"journal-book","stem":"الدفتر اللي تُقيَّد فيه عمليات التاجر المالية يوم بيوم، بما في ذلك السحوبات الشخصية، هو:","options":["دفتر الأستاذ","دفتر اليومية الأصلي","دفتر التسويدة","دفتر الخزانة (الصندوق)"],"answer":1,"why":"«يوم بيوم» و«السحوبات الشخصية» هي بصمة دفتر اليومية الأصلي، وهو أول الدفاتر الإلزامية.","wrong":[{"i":0,"mis":"l6.ledger-journal","note":"الأستاذ تُرحَّل إليه العمليات ذات الطبيعة الواحدة من الدفاتر الثانية، مو قيد يومي أول بأول."},{"i":2,"mis":"l6.draft-journal","note":"التسويدة فيها العمليات اليومية بسرعة وبدون تنظيم ثم تنتقل لليومية، يعني هي مسودة اليومية مو اليومية نفسها."},{"i":3,"mis":"gen.neighbor","note":"الخزانة يُقيد فيها ما يدخل ويخرج من الصندوق بس، مو كل عمليات التاجر والسحوبات الشخصية."}],"tests":["journal-book","mandatory-books"]},{"n":606,"lo":"L6","sec":"LAW333-L6","type":"term","topic":"ledger-book","stem":"«هو أهم الدفاتر التجارية، وتُرحل إليه جميع العمليات ذات الطبيعة الواحدة المقيدة في الدفاتر الأخرى». هذا تعريف:","options":["دفتر اليومية الأصلي","دفتر الجرد","دفتر الأستاذ","دفتر الأوراق التجارية"],"answer":2,"why":"«أهم الدفاتر التجارية» + «تُرحل إليه العمليات ذات الطبيعة الواحدة» = دفتر الأستاذ، وهو ثالث الدفاتر الإلزامية.","wrong":[{"i":0,"mis":"l6.ledger-journal","note":"اليومية هي اللي تنقيد فيها العمليات أول مرة يوم بيوم، والأستاذ هو اللي يُرحَّل إليه بعدين."},{"i":1,"mis":"gen.neighbor","note":"الجرد إلزامي مثل الأستاذ، لكنه لتفاصيل البضاعة آخر السنة المالية وصورة المركز المالي."},{"i":3,"mis":"gen.neighbor","note":"دفتر الأوراق التجارية اختياري ويخص الأوراق اللي التاجر دائن أو مدين فيها وتواريخ استحقاقها."}],"tests":["ledger-book","mandatory-books"]},{"n":607,"lo":"L6","sec":"LAW333-L6","type":"term","topic":"commercial-papers-book","stem":"الدفتر اللي يُقيد فيه الأوراق التجارية اللي يكون فيها التاجر دائناً أو مديناً وتواريخ استحقاقها، يُسمى أيضاً:","options":["دفتر الخزانة (الصندوق)","دفتر التسويدة","دفتر الجرد","دفتر القبض والدفع"],"answer":3,"why":"الشريحة نصت إن دفتر الأوراق التجارية «يسمى ايضا دفتر القبض والدفع»، وهو من الدفاتر الاختيارية.","wrong":[{"i":0,"mis":"gen.keyword","note":"الأوراق التجارية والقبض والدفع تذكّره بالفلوس والصندوق، لكن الخزانة اسمها الثاني «الصندوق» مو «القبض والدفع»."},{"i":1,"mis":"gen.neighbor","note":"التسويدة لقيد العمليات اليومية بسرعة وبدون تنظيم، ما لها علاقة بالأوراق التجارية."},{"i":2,"mis":"gen.neighbor","note":"الجرد دفتر إلزامي لتفاصيل البضاعة آخر السنة، وما له اسم ثاني في المحاضرة."}],"tests":["commercial-papers-book","optional-books"]},{"n":608,"lo":"L6","sec":"LAW333-L6","type":"scenario","topic":"inventory-book","stem":"في نهاية السنة المالية، قيّد تاجر في المدينة تفاصيل البضاعة الموجودة عنده، ومعها صورة من قائمة مركزه المالي (ما له وما عليه من ديون). حسب المحاضرة، هذا الدفتر هو:","options":["دفتر الجرد، وهو من الدفاتر الإلزامية","دفتر المخزن، وهو من الدفاتر الاختيارية","دفتر الجرد، وهو من الدفاتر الاختيارية","دفتر المخزن، وهو من الدفاتر الإلزامية"],"answer":0,"why":"«آخر السنة المالية» + «صورة من قائمة المركز المالي» = دفتر الجرد، والمخطط يحطه مع اليومية والأستاذ في الدفاتر الإلزامية.","wrong":[{"i":1,"mis":"l6.inventory-warehouse","note":"المخزن يقيد حركة البضاعة اللي تدخل وتطلع، مو جرد آخر السنة مع المركز المالي."},{"i":2,"mis":"l6.mandatory-optional","note":"عرف الدفتر صح لكن غلط في التصنيف: الجرد إلزامي."},{"i":3,"mis":"l6.inventory-warehouse","note":"خلط بين الجرد والمخزن، وكمان المخزن اختياري مو إلزامي."}],"tests":["inventory-book","mandatory-books"]},{"n":609,"lo":"L6","sec":"LAW333-L6","type":"figure","topic":"draft-book","stem":"بالاستعانة بمخطط «أنواع الدفاتر التجارية»: الدفتر اللي يُقيد فيه جميع العمليات اليومية على وجه السرعة ودون تنظيم، ثم تُنقل بشكل منظم إلى دفتر اليومية، وش اسمه وتحت أي قسم؟","img":"img/law333/L6-s08.png","options":["دفتر اليومية – دفاتر إلزامية","دفتر التسويدة – دفاتر اختيارية","دفتر التسويدة – دفاتر إلزامية","دفتر المخزن – دفاتر اختيارية"],"answer":1,"why":"هذا وصف دفتر التسويدة (مسودة سريعة تنتقل بعدين لليومية)، والمخطط يحطه أول واحد في خانة الدفاتر الاختيارية.","wrong":[{"i":0,"mis":"l6.draft-journal","note":"اليومية هي اللي تنتقل لها العمليات بشكل منظم، مو اللي تنقيد فيها بسرعة وبدون تنظيم."},{"i":2,"mis":"l6.mandatory-optional","note":"عرف الدفتر لكن حطه في القسم الغلط؛ الإلزامية ثلاثة بس: اليومية والجرد والأستاذ."},{"i":3,"mis":"gen.neighbor","note":"المخزن اختياري فعلاً، لكنه لحركة البضاعة داخل وطالع من المخزن، مو للعمليات اليومية."}],"tests":["draft-book","book-types"]},{"n":610,"lo":"L6","sec":"LAW333-L6","type":"scenario","topic":"cash-book","stem":"بنك في الرياض يعتمد بشكل أساسي على دفتر يُقيد فيه كل ما يدخل ويخرج من الصندوق. حسب المحاضرة، أي وصف لهذا الدفتر صحيح؟","options":["دفتر الخزانة، وهو من الدفاتر الإلزامية لأنه أساسي للبنوك","دفتر الخزانة، وهو من الدفاتر الاختيارية، إلا أنه يُعد من الدفاتر الأساسية بالنسبة للبنوك والشركات الكبرى","دفتر الأستاذ، لأنه أهم الدفاتر التجارية وتُرحل إليه العمليات","دفتر الأوراق التجارية، لأنه يسمى أيضاً دفتر القبض والدفع"],"answer":1,"why":"الشريحة: دفتر الخزانة (الصندوق) «يُقيد فيه مايدخل ويخرج من الصندوق، وعلى الرغم من أنه من الدفاتر الاختيارية الا أنه يُعد من الدفاتر الأساسية بالنسبة للبنوك والشركات الكبرى». يعني أهميته للبنوك ما تغيّر تصنيفه، يبقى اختياري.","wrong":[{"i":0,"mis":"l6.mandatory-optional","note":"كلمة «أساسي» توهمه إنه صار إلزامي، لكن الشريحة صريحة إنه اختياري رغم أهميته للبنوك."},{"i":2,"mis":"gen.keyword","note":"«أهم الدفاتر» وصف دفتر الأستاذ، لكنه للعمليات ذات الطبيعة الواحدة المرحّلة من الدفاتر الثانية، مو حركة الصندوق."},{"i":3,"mis":"gen.keyword","note":"«القبض والدفع» توحي بالصندوق، لكنه اسم دفتر الأوراق التجارية."}],"tests":["cash-book","optional-books"]},{"n":611,"lo":"L6","sec":"LAW333-L6","type":"concept","topic":"retention-period","stem":"حسب المادة الثامنة كما وردت في المحاضرة، مين يلتزم بالاحتفاظ بالدفاتر التجارية وكم المدة؟","options":["التاجر وحده، لمدة عشر سنوات على الأكثر","التاجر وحده، لمدة عشر سنوات على الأقل","التاجر وورثته، لمدة خمس سنوات على الأقل","التاجر وورثته، لمدة عشر سنوات على الأقل"],"answer":3,"why":"النص: «الزمت المادة الثامنة ... التاجر وورثته الاحتفاظ بالدفاتر التجارية المنصوص عليها في النظام لمدة عشر سنوات على الأقل». انتبه لكلمتين: «وورثته» و«على الأقل».","wrong":[{"i":0,"mis":"gen.reversed","note":"قلب «على الأقل» إلى «على الأكثر»، ونسي إن الالتزام يشمل الورثة."},{"i":1,"mis":"l6.retention","note":"المدة صح، لكنه نسي إن المادة ألزمت الورثة مع التاجر."},{"i":2,"mis":"gen.detail","note":"الأشخاص صح لكن المدة غلط؛ هي عشر سنوات مو خمس."}],"tests":["retention-period","article-8"]},{"n":612,"lo":"L6","sec":"LAW333-L6","type":"tf","topic":"retention-not-prescription","stem":"صح أو خطأ: «حجية الدفاتر التجارية تبقى قائمة حتى لو انتهت مدة العشر سنوات، لأن هذه المدة ليست مدة تقادم».","options":["صح","خطأ"],"answer":0,"why":"الشريحة نصت إن الغاية من الحفظ «للرجوع اليها اذا ما دعت الحاجة للإثبات، وحجية هذه الدفاتر قائمة وان انتهت مدة العشر سنوات، لأنها ليست مدة تقادم».","wrong":[{"i":1,"mis":"l6.retention","note":"يحسب إن العشر سنوات مثل مدة تقادم تسقط بعدها قيمة الدفاتر، والشريحة تنفي هذا صراحة."}],"tests":["retention-period","evidence-authority"]},{"n":613,"lo":"L6","sec":"LAW333-L6","type":"scenario","topic":"irregular-books","stem":"تاجر يكتب في حواشي دفتر اليومية، ويترك فراغات بين القيود، وما يرقّم الحواشي. صار بينه وبين عميل نزاع، فقدّم دفاتره عشان يثبت حقه. حسب المحاضرة، وش الأثر؟","options":["تُقبل في الإثبات عادي، لأن المهم إنه مسك الدفاتر","يترتب على ذلك عدم الاعتداد بها أو الاستناد عليها في الإثبات","تُقبل في الإثبات بشرط يقدّم المحاسب القانوني تقرير «فحص تأكيدات»","الأثر الوحيد إن الزكاة تنحسب بالأسلوب التقديري، وتبقى الدفاتر مقبولة في الإثبات"],"answer":1,"why":"الشريحة: «عدم انتظام الدفاتر التجارية مثل الكتابة في الحواشي أو ترك أي فراغ أو عدم ترقيم الحواشي يترتب عليه عدم الاعتداد بها أو الاستناد عليها في الاثبات». والحالة فيها الثلاث صور كلها.","wrong":[{"i":0,"mis":"gen.partial","note":"مجرد مسك الدفاتر ما يكفي؛ الشريحة ربطت الأثر بعدم الانتظام نفسه."},{"i":2,"mis":"l6.computer-conditions","note":"تقرير «فحص تأكيدات» من شروط تدوين الدفاتر بالحاسب الآلي، مو علاج لعدم انتظام الدفاتر."},{"i":3,"mis":"l6.irregular-effect","note":"الاحتساب التقديري أثر ثاني مذكور، لكنه ما يلغي أثر عدم الاعتداد بالدفاتر غير المنتظمة في الإثبات."}],"tests":["irregular-books","non-compliance-effects"]},{"n":614,"lo":"L6","sec":"LAW333-L6","type":"concept","topic":"penalty-fine","stem":"حسب المحاضرة، يُعاقب كل مخالف لأحكام نظام الأوراق التجارية ولائحته بغرامة:","options":["لا تقل عن خمسة آلاف ريال ولا تزيد عن خمسين ألف ريال","لا تقل عن ألف ريال ولا تزيد عن عشرة آلاف ريال","لا تقل عن عشرة آلاف ريال ولا تزيد عن مئة ألف ريال","لا تقل عن خمسين ألف ريال ولا تزيد عن مئة ألف ريال"],"answer":0,"why":"الحد الأدنى ٥ آلاف والحد الأعلى ٥٠ ألف ريال. لا تخلطها برقم ١٠٠ ألف، هذا حد رأس مال التاجر المستثنى من مسك الدفاتر.","wrong":[{"i":1,"mis":"gen.detail","note":"أرقام أصغر من اللي في الشريحة؛ تذكّر خمسة آلاف إلى خمسين ألف."},{"i":2,"mis":"l6.numbers","note":"دخّل رقم المئة ألف (حد رأس المال للمستثنى) في الغرامة."},{"i":3,"mis":"l6.numbers","note":"خلى الحد الأعلى (٥٠ ألف) حد أدنى، وأضاف رقم المئة ألف من موضوع الاستثناء."}],"tests":["penalty","non-compliance-effects"]},{"n":615,"lo":"L6","sec":"LAW333-L6","type":"list","topic":"computer-bookkeeping","stem":"أجاز النظام تدوين بيانات الدفاتر التجارية عن طريق الحاسب الآلي مع توافر عدة شروط. أي مما يلي ليس من هذه الشروط كما وردت في المحاضرة؟","options":["أن يتوفر لدى المنشأة وسائل الأمان اللازمة للحفاظ على سلامة الأجهزة وبرامجها","أن يتم استخراج بيانات مطبوعة «مخرجات» بشكل دوري منتظم","أن يكون المحاسب القانوني وحده مسؤولاً مسؤولية مباشرة عن صحة البيانات المحاسبية المدونة بدلاً من المنشأة","أن يقدم المحاسب القانوني للمنشأة تقرير «فحص تأكيدات» يؤيد صحة ونظامية البيانات المدخلة"],"answer":2,"why":"الشرط الثاني نصه: «أن تكون المنشأة مسؤولة مسؤولية مباشرة عن صحة البيانات المحاسبية المدونة». دور المحاسب القانوني إنه يقدّم تقرير «فحص تأكيدات»، مو إنه يشيل المسؤولية بدال المنشأة.","wrong":[{"i":0,"mis":"gen.partial","note":"ممكن يحسبه تفصيل تقني مو شرط نظامي، لكنه أول شرط بالنص."},{"i":1,"mis":"gen.partial","note":"كلمة «مطبوعة» تبان غريبة مع الحاسب الآلي، لكن الشريحة طلبتها صراحة ضمن الشرط الأول."},{"i":3,"mis":"gen.partial","note":"ممكن يظن اسم التقرير مخترع، لكنه الشرط الثالث بالنص."}],"tests":["computer-bookkeeping"]},{"n":616,"lo":"L6","sec":"LAW333-L6","type":"concept","topic":"evidence-authority","stem":"أي العبارات التالية صحيحة حسب المحاضرة بخصوص استخدام الدفاتر التجارية في الإثبات؟","options":["القضاء ملزم بالأخذ بالدفاتر التجارية متى كانت منتظمة","الدليل المستخلص من الدفاتر التجارية دليل قطعي لا يجوز إثبات عكسه","استخدام الدفاتر في الإثبات لمصلحة التاجر أو ضده تطبيق للقاعدة العامة «لا يُجبر الشخص على تقديم دليل ضد نفسه»","النظام لم يبين ما إذا كان للخصم الحق في الاطلاع على الدفاتر التجارية للتاجر"],"answer":3,"why":"الشريحة ١٥ قالت بالنص: «النظام لم يبين ما اذا كان للخصم الحق في الاطلاع على الدفاتر التجارية للتاجر». أما باقي العبارات فكل وحدة منها عكس اللي في الشرائح.","wrong":[{"i":0,"mis":"l6.binding-proof","note":"القضاء «غير ملزم» حتى لو كانت الدفاتر منتظمة، لأن القاضي له سلطة تقديرية."},{"i":1,"mis":"l6.binding-proof","note":"الدليل منها «لا يُعد دليلا قطعيا»، ولكل ذي مصلحة يثبت عكس اللي مقيد فيها."},{"i":2,"mis":"l6.evidence-exception","note":"استخدامها لمصلحة التاجر أو ضده «استثناء» من القواعد العامة، مو تطبيق لها."}],"tests":["evidence-authority","evidence-exception","opponent-access"]},{"n":701,"lo":"L7","sec":"LAW333-L7","type":"term","topic":"registry-definition","stem":"«وسيلة إشهار تجارية تؤمن نشر المعلومات المتعلقة بالتاجر والتي يرغب الغير من المتعاملين مع التاجر معرفتها والوقوف عليها». هذا تعريف:","options":["الغرفة التجارية والصناعية","مكاتب السجل التجاري","السجل التجاري","الصورة المستخرجة من السجل التجاري"],"answer":2,"why":"هذا تعريف السجل التجاري في شريحة 3. عبارتا «وسيلة إشهار» و«نشر المعلومات المتعلقة بالتاجر» هما مفتاح السجل.","wrong":[{"i":0,"mis":"l7.registry-vs-chamber","note":"الغرفة كمان مرتبطة بالتجار، لكنها هيئة لا تستهدف الربح وتمثل مصالحهم أمام السلطات العامة، وليست وسيلة إشهار."},{"i":1,"mis":"gen.neighbor","note":"المكاتب هي الجهة الإدارية اللي تتأكد من صحة البيانات المسجلة، وليست السجل نفسه."},{"i":3,"mis":"gen.neighbor","note":"الصورة المستخرجة شي يحصل عليه الشخص من السجل، وليست تعريف السجل."}],"tests":["تعريف السجل التجاري"]},{"n":702,"lo":"L7","sec":"LAW333-L7","type":"term","topic":"chamber-definition","stem":"«هيئة لا تستهدف الربح وتمثل في دائرة اختصاصها المصالح التجارية والصناعية لدى السلطات العامة، وتعمل على حمايتها وتطويرها». هذا تعريف:","options":["السجل التجاري","الغرفة التجارية والصناعية","وزارة التجارة","مكاتب السجل التجاري التابعة لوزارة التجارة"],"answer":1,"why":"عبارتا «لا تستهدف الربح» و«تمثل المصالح التجارية والصناعية لدى السلطات العامة» هما وصف الغرفة التجارية والصناعية في شريحة 9.","wrong":[{"i":0,"mis":"l7.registry-vs-chamber","note":"السجل وسيلة إشهار لمعلومات التاجر، وليس هيئة تمثل المصالح."},{"i":2,"mis":"gen.neighbor","note":"الوزارة مذكورة في المحاضرة لأن مكاتب السجل تتبعها، لكن التعريف هنا للهيئة غير الربحية اللي تمثل التجار والصناع، وهي الغرفة."},{"i":3,"mis":"l7.registry-vs-chamber","note":"المكاتب جهة إدارية تتأكد من صحة البيانات المسجلة، ولا تمثل مصالح التجار."}],"tests":["تعريف الغرفة التجارية والصناعية"]},{"n":703,"lo":"L7","sec":"LAW333-L7","type":"scenario","topic":"individual-obligation","stem":"فهد تاجر في جدة رأس ماله ثلاثة ملايين ريال، يبيع بضاعته متنقلاً بين الأسواق الموسمية دون أن يكون له محل يباشر فيه عمله التجاري. حسب الشرائح، ما حكم قيده في السجل التجاري؟","options":["ملزم بالقيد؛ لأن رأس ماله كبير","ملزم بالقيد؛ لأن كل تاجر يلزمه القيد مهما كانت طريقة ممارسته للتجارة","غير ملزم بالقيد؛ لأن الالتزام بالقيد مقصور على الشركات دون الأفراد","غير ملزم بالقيد؛ لأنه لا يملك محلاً ثابتاً يزاول فيه تجارته"],"answer":3,"why":"التاجر الفرد ملزم بالقيد «بغض النظر عن مقدار رأس المال، طالما لديه محل ثابت». واللي يمارس تجارته بدون محل يباشر فيه عمله ليس ملزماً (شريحة 4).","wrong":[{"i":0,"mis":"l7.fixed-shop-criterion","note":"رأس المال الكبير يغريك، لكن الشريحة تقول «بغض النظر عن مقدار رأس المال»، والمعيار هو المحل الثابت."},{"i":1,"mis":"gen.absolute","note":"الأصل فعلاً «على كل تاجر»، لكن الشريحة استثنت اللي ما له محل يباشر فيه عمله."},{"i":2,"mis":"gen.partial","note":"الالتزام يشمل الأفراد والشركات، والفرد يلزمه القيد إذا كان عنده محل ثابت."}],"tests":["الملتزمون بالقيد: الأفراد","معيار المحل الثابت","عدم الاعتداد برأس المال"]},{"n":704,"lo":"L7","sec":"LAW333-L7","type":"tf","topic":"companies-obligation","stem":"يقتصر الالتزام بالقيد في السجل التجاري على الشركات التجارية، أما الشركات المدنية كالتي تمارس أعمالاً عقارية أو زراعية فلا تلتزم به.","options":["صح","خطأ"],"answer":1,"why":"العبارة خطأ. شريحة 4 تقول إن الالتزام يسري كذلك على الشركات المدنية كالتي تمارس أعمالاً عقارية أو زراعية، ويسري أيضاً على الشركات الأجنبية المرخص لها بفتح فرع أو مكتب في المملكة.","wrong":[{"i":0,"mis":"l7.companies-scope","note":"كلمة «مدنية» توحي إنها خارج التجارة، لكن الشريحة نصّت صراحة إن الالتزام يسري عليها."}],"tests":["الملتزمون بالقيد: الشركات","الشركات المدنية"]},{"n":705,"lo":"L7","sec":"LAW333-L7","type":"list","topic":"registrable-data","stem":"أي مما يلي من البيانات التي يجب أن يحتوي عليها القيد في السجل التجاري حسب الشرائح؟","options":["الأحكام الخاصة بإفلاس التاجر ولو لم تكن نهائية","الأحكام التي تؤثر على أهلية التاجر كسحب الإذن بالاتجار أو تقييده للمحجور عليه","أسماء عملاء التاجر والمتعاملين معه","الأحكام الصادرة بإدانة التاجر في جميع القضايا الجزائية أياً كان نوعها"],"answer":1,"why":"أحكام الأهلية هي البند الثالث في قائمة البيانات الواجب قيدها (شريحة 5). القائمة كاملة: البيانات الشخصية والوصفية، أحكام الإفلاس النهائية، أحكام الأهلية، أحكام حل الشركة أو بطلانها، والإدانة في التزوير والتزييف والرشوة.","wrong":[{"i":0,"mis":"gen.detail","note":"الإفلاس موجود في القائمة، لكن الشريحة تقول «الأحكام والأوامر النهائية»، فإذا شلت شرط النهائية صارت العبارة غلط."},{"i":2,"mis":"l7.data-list","note":"التعريف يذكر «الغير من المتعاملين» على أنهم المستفيدون من المعلومات، وليسوا بيانات تُقيد. وأسماء العملاء مو من البنود الخمسة."},{"i":3,"mis":"gen.absolute","note":"الإدانة المذكورة محصورة في قضايا التزوير والتزييف والرشوة، وليست كل القضايا الجزائية."}],"tests":["البيانات الواجب قيدها","أحكام الأهلية"]},{"n":706,"lo":"L7","sec":"LAW333-L7","type":"concept","topic":"registry-offices","stem":"ما الوصف الصحيح لمكاتب السجل التجاري حسب الشرائح؟","options":["جهة إدارية تابعة لوزارة التجارة تختص بالتأكد من صحة البيانات المسجلة في السجل التجاري","جهة قضائية تختص بالفصل في صحة البيانات المسجلة في السجل التجاري","هيئة لا تستهدف الربح تمثل مصالح التجار والصناع أمام السلطات العامة","جهة تابعة للغرفة التجارية دورها الإحصاء والاستعلام فقط"],"answer":0,"why":"نص شريحة 6: «تختص مكاتب السجل التجاري التابعة لوزارة التجارة بالتأكد من صحة البيانات المسجلة... وهي جهة إدارية ليست قضائية».","wrong":[{"i":1,"mis":"l7.judicial-body","note":"«التأكد من صحة البيانات» يوحي بعمل قضائي، لكن الشريحة قالت صراحة «إدارية ليست قضائية»."},{"i":2,"mis":"l7.registry-vs-chamber","note":"هذا وصف الغرفة التجارية والصناعية، وليس وصف مكاتب السجل."},{"i":3,"mis":"l7.stats-only","note":"المكاتب تتبع وزارة التجارة وليس الغرفة، والقيد نفسه ليس فقط للإحصاء والاستعلام بل للشهر القانوني."}],"tests":["مكاتب السجل التجاري","جهة إدارية لا قضائية","التبعية لوزارة التجارة"]},{"n":707,"lo":"L7","sec":"LAW333-L7","type":"concept","topic":"legal-publicity","stem":"حسب الشرائح، كيف يُوصف القيد في السجل التجاري من حيث وظيفته؟","options":["أداة للإحصاء والاستعلام فقط","وسيلة لتمثيل التجار والصناع أمام السلطات العامة","ليس فقط أداة للإحصاء والاستعلام، بل أداة للشهر القانوني","إجراء تنظيمي داخلي لا يطّلع عليه غير التاجر"],"answer":2,"why":"نص شريحة 6: «القيد في السجل التجاري ليس فقط أداة للإحصاء والاستعلام بل أداة للشهر القانوني»، وهذا متماشٍ مع تعريف السجل كوسيلة إشهار.","wrong":[{"i":0,"mis":"l7.stats-only","note":"هذا أول الجملة فقط، وترك «بل أداة للشهر القانوني»."},{"i":1,"mis":"l7.registry-vs-chamber","note":"تمثيل التجار والصناع أمام السلطات العامة هو دور الغرفة التجارية."},{"i":3,"mis":"gen.reversed","note":"بالعكس، السجل وسيلة إشهار، وأي شخص يقدر ياخذ صورة مستخرجة منه."}],"tests":["وظيفة القيد","الشهر القانوني"]},{"n":708,"lo":"L7","sec":"LAW333-L7","type":"scenario","topic":"registry-extract","stem":"طلب سعد صورة مستخرجة من السجل التجاري لتاجر يريد أن يتعامل معه، وكان قد صدر على هذا التاجر حكم إفلاس سابق ولم يُرد إليه اعتباره بعد. حسب الشرائح، ما الحكم؟","options":["يحق لسعد الحصول على صورة كاملة تتضمن حكم الإفلاس السابق؛ لأن السجل وسيلة إشهار","يحق لسعد الحصول على الصورة، بشرط ألا تتضمن بيانات تضر بسمعة التاجر ولا تفيد الغير كحكم الإفلاس السابق","لا يحق لسعد الحصول على الصورة إلا بعد أن يُرد للتاجر اعتباره","لا يحق لسعد الحصول على أي صورة؛ لأن الصورة المستخرجة لا تُعطى إلا للتاجر نفسه"],"answer":1,"why":"شريحة 6: «يمكن لأي شخص أن يحصل على صورة مستخرجة... شريطة أن لا يكون فيها بيانات تضر بسمعة التاجر ولا تفيد الغير كأحكام الإفلاس السابقة على التاجر قبل أن يرد إليه اعتباره».","wrong":[{"i":0,"mis":"l7.extract-limits","note":"صحيح إن السجل وسيلة إشهار، لكن الشريحة استثنت من الصورة البيانات اللي تضر بسمعة التاجر، مثل الإفلاس السابق قبل رد الاعتبار."},{"i":2,"mis":"gen.detail","note":"رد الاعتبار مذكور كقيد على البيانات اللي تظهر في الصورة، وليس شرطاً عشان يحصل على الصورة أصلاً."},{"i":3,"mis":"gen.reversed","note":"الشريحة تقول «يمكن لأي شخص»، مو التاجر وحده."}],"tests":["الصورة المستخرجة من السجل","حماية سمعة التاجر"]},{"n":709,"lo":"L7","sec":"LAW333-L7","type":"scenario","topic":"deregistration","stem":"شركة تجارية مقيدة في السجل التجاري في الرياض دخلت مرحلة التصفية. حسب الشرائح، من الذي يجب عليه طلب شطب قيدها من السجل التجاري؟","options":["الورثة","مكاتب السجل التجاري من تلقاء نفسها","رئيس مجلس إدارة الغرفة التجارية","المصفون"],"answer":3,"why":"شريحة 7: يجب طلب شطب القيد على التاجر إذا اعتزل التجارة، وعلى ورثته إذا توفي، و«المصفين في حال تصفية الشركة».","wrong":[{"i":0,"mis":"l7.deregistration-who","note":"الورثة يطلبون الشطب إذا توفي التاجر، وليس عند تصفية الشركة."},{"i":1,"mis":"gen.neighbor","note":"المكاتب تتأكد من صحة البيانات، والشريحة حمّلت واجب طلب الشطب لأصحاب الشأن وليس لها."},{"i":2,"mis":"l7.registry-vs-chamber","note":"رئيس مجلس الإدارة يمثل الغرفة أمام القضاء والغير، وما له علاقة بشطب قيد الشركة."}],"tests":["شطب القيد","حالة تصفية الشركة"]},{"n":710,"lo":"L7","sec":"LAW333-L7","type":"list","topic":"registration-effects","stem":"ذكرت الشرائح آثاراً تترتب على القيد في السجل التجاري. أي مما يلي ليس منها؟","options":["أن حجية البيانات المقيدة في السجل التجاري تكون من تاريخ تقديمها","أن عدداً من الأنظمة الأخرى ربطت أحكامها بالقيد ورتبت مزايا لا يتمتع بها سوى المقيدين","أن مخالفة أحكام السجل التجاري يترتب عليها جزاء جنائي بغرامة تصل إلى خمسين ألف ريال","أن البيانات المقيدة لا تكون حجة إلا من تاريخ حصول الغير على صورة مستخرجة منها"],"answer":3,"why":"شريحة 8 تذكر ثلاثة بنود: الحجية من تاريخ تقديم البيانات، وأنظمة أخرى ربطت أحكامها بالقيد مع مزايا للمقيدين فقط، وغرامة تصل إلى خمسين ألف ريال. ربط الحجية بحصول الغير على صورة غير مذكور.","wrong":[{"i":0,"mis":"l7.evidence-date","note":"ممكن تشك في تاريخ بداية الحجية، لكن نص الشريحة: «تكون من تاريخ تقديمها»، فهو أثر مذكور."},{"i":1,"mis":"gen.detail","note":"عبارة «لا يتمتع بها سوى المقيدين» تبدو مبالغة، لكنها نص الشريحة حرفياً."},{"i":2,"mis":"l7.fine-amount","note":"ممكن تحسب المبلغ مختلف، أو تحسب الجزاء الجنائي مو من الآثار، لكن الشريحة ذكرته بند ثالث بغرامة تصل إلى خمسين ألف ريال."}],"tests":["آثار القيد","حجية البيانات من تاريخ تقديمها","غرامة تصل إلى خمسين ألف ريال"]},{"n":711,"lo":"L7","sec":"LAW333-L7","type":"tf","topic":"current-vs-old-law","stem":"رتّب نظام السجل التجاري الحالي، بخلاف القديم، آثاراً قانونية مدنية على القيد في السجل التجاري، وجزاءً جنائياً في حال مخالفة أحكامه.","options":["صح","خطأ"],"answer":0,"why":"العبارة صحيحة، وهي نص شريحة 7 تقريباً: «رتب نظام السجل التجاري الحالي – بخلاف القديم – آثارا قانونية مدنية... وجزاءً جنائيا في حال مخالفة أحكامه».","wrong":[{"i":1,"mis":"l7.old-vs-new-law","note":"اللي يختار «خطأ» غالباً يحسب إن النظام القديم هو اللي رتّب هذي الآثار، والشريحة تقول «بخلاف القديم»."}],"tests":["النظام الحالي مقابل القديم","الآثار المدنية والجزاء الجنائي"]},{"n":712,"lo":"L7","sec":"LAW333-L7","type":"tf","topic":"chamber-personality","stem":"ليس للغرفة التجارية والصناعية شخصية اعتبارية، ولذلك تتولى وزارة التجارة تمثيلها أمام القضاء والغير.","options":["صح","خطأ"],"answer":1,"why":"العبارة خطأ. شريحة 9: «ويكون للغرفة التجارية والصناعية الشخصية الاعتبارية، ويقوم رئيس مجلس إدارتها بتمثيلها أمام القضاء والغير».","wrong":[{"i":0,"mis":"l7.chamber-nature","note":"وزارة التجارة مذكورة في المحاضرة لأن مكاتب السجل تتبعها، فتغريك، لكن الغرفة لها شخصية اعتبارية ويمثلها رئيس مجلس إدارتها."}],"tests":["الشخصية الاعتبارية للغرفة","تمثيل الغرفة أمام القضاء والغير"]},{"n":801,"lo":"L2","sec":"LAW333-PRAC","type":"concept","topic":"المحكمة المختصة","stem":"الجهة التي لها حق الفصل في المنازعات التجارية في النظام السعودي هي:","options":["المحكمة العمالية","المحكمة الجزائية","المحكمة التجارية","المحكمة الشرعية"],"answer":2,"why":"من أهمية التفرقة بين العمل التجاري والمدني إنها تحدد المحكمة المختصة: المنازعات التجارية تروح للمحكمة التجارية، والمدنية للمحاكم العامة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"العمالية لقضايا العامل وصاحب العمل، مو للنزاعات التجارية."},{"i":1,"mis":"gen.neighbor","note":"الجزائية للجرائم والعقوبات."},{"i":3,"mis":"l2.courts","note":"المحاكم العامة (الشرعية) للمنازعات المدنية، والتجارية لها محكمتها الخاصة."}],"tests":["المحكمة المختصة","أهمية التفرقة"]},{"n":802,"lo":"L2","sec":"LAW333-PRAC","type":"concept","topic":"معيار المضاربة","stem":"كل العمليات التي تهدف إلى تحقيق الربح تعتبر أعمالاً تجارية وفقاً لمعيار:","options":["المنافسة","المقاولة","المضاربة","التداول"],"answer":2,"why":"شريحة ٥ (المحاضرة الثانية): المقصود بالمضاربة استهداف تحقيق الربح؛ فكل عمل يستهدف الربح تجاري، وكل عمل لا يستهدفه غير تجاري.","wrong":[{"i":0,"mis":"gen.keyword","note":"المنافسة مو من المعايير الأربعة أصلاً (المضاربة، التداول، المشروع، الحرفة)."},{"i":1,"mis":"l2.criteria-mix","note":"المقاولة/المشروع معياره التكرار في شكل مشروع منظم، مو الربح."},{"i":3,"mis":"l2.criteria-mix","note":"التداول = حركة السلع وانتقالها من المنتج للمستهلك."}],"tests":["المعايير الأربعة","معيار المضاربة = الربح"]},{"n":803,"lo":"L5","sec":"LAW333-PRAC","type":"scenario","topic":"شرط الاستقلالية","stem":"لا يتوافر فيه شرط الاستقلالية لاعتباره تاجراً:","options":["مندوب المبيعات في المحل التجاري","السمسار"],"answer":0,"why":"الاستقلالية = تشتغل باسمك ولحسابك وتتحمل الربح والخسارة. مندوب المبيعات موظف يشتغل لحساب صاحب المحل وما يتحمل الخسارة، فما هو تاجر. السمسار تاجر حتى بدون محل لأنه يمارس السمسرة باسمه ولحسابه. (الخياران الباقيان ما ظهروا في الصورة.)","wrong":[{"i":1,"mis":"l5.agent-commission","note":"السمسار والوكيل بالعمولة تجار بنص الشرائح، حتى لو ما عندهم محل تجاري."}],"tests":["شرط الاستقلالية","مين ما يعتبر تاجر"]},{"n":804,"lo":"L4","sec":"LAW333-PRAC","type":"list","topic":"صور المقاولة","stem":"لا تعتبر من ضمن صور الأعمال التجارية بالمقاولة:","options":["المحلات التجارية","الوكالة بالعمولة","أعمال التجارة البحرية","البيع بالمزاد العلني"],"answer":2,"why":"صور المقاولة السبع في المادة ٢: الصناعة، التوريد، الوكالة بالعمولة، النقل، البيع بالمزاد، المحلات والمكاتب، إنشاء المباني. «أعمال التجارة البحرية» مو منها — هي نوع مستقل من الأعمال التجارية.","wrong":[{"i":0,"mis":"gen.detail","note":"المحلات والمكاتب التجارية الصورة الخامسة."},{"i":1,"mis":"gen.detail","note":"الوكالة بالعمولة الصورة الثالثة."},{"i":3,"mis":"gen.detail","note":"البيع بالمزاد العلني الصورة السادسة."}],"tests":["الصور السبع للمقاولة"]},{"n":805,"lo":"L4","sec":"LAW333-PRAC","type":"scenario","topic":"الأعمال بالتبعية","stem":"شراء التاجر الأثاث اللازم لمتجره بالنسبة إليه يعد من قبيل:","options":["الأعمال التجارية المنفردة","الأعمال التجارية بالمقاولة","الأعمال التجارية بالتبعية","الأعمال المختلطة"],"answer":2,"why":"شراء الأثاث بحد ذاته عمل مدني، لكن لأن التاجر سواه لحاجة تجارته صار تجاري بالتبعية (الفرع يتبع الأصل). المثال نفسه في الشرائح.","wrong":[{"i":0,"mis":"l4.single-vs-enterprise","note":"المنفردة تجارية بطبيعتها حتى لو سواها مرة (زي الشراء بقصد البيع)، والأثاث ما انشرى للبيع."},{"i":1,"mis":"l4.single-vs-enterprise","note":"المقاولة تحتاج تكرار في مشروع منظم، وهذا شراء لحاجة المحل."},{"i":3,"mis":"l4.mixed-vs-accessory","note":"المختلط يكون تجاري لطرف ومدني للطرف الثاني؛ السؤال يسأل عن صفته «بالنسبة إليه» = التاجر."}],"tests":["الأعمال بالتبعية","مثال الأثاث"]},{"n":806,"lo":"IMP","sec":"LAW333-PRAC","type":"concept","topic":"الشيك","stem":"يلزم أن يكون المسحوب عليه دائماً بنكاً في:","options":["الكمبيالة والمخالصة","الكمبيالة والسند لأمر والشيك","الشيك","السند لأمر"],"answer":2,"why":"الشيك لا يُسحب إلا على بنك. في الكمبيالة المسحوب عليه ممكن يكون أي شخص، والسند لأمر ما فيه مسحوب عليه أصلاً (طرفين: المحرر والمستفيد).","wrong":[{"i":0,"mis":"imp.drawee","note":"الكمبيالة المسحوب عليه فيها أي شخص، والمخالصة مو ورقة تجارية."},{"i":1,"mis":"imp.drawee","note":"التعميم غلط: البنك شرط في الشيك فقط."},{"i":3,"mis":"imp.drawee","note":"السند لأمر ما فيه مسحوب عليه."}],"tests":["أطراف الأوراق التجارية","الشيك = بنك"]},{"n":807,"lo":"L4","sec":"LAW333-PRAC","type":"term","topic":"الوكيل بالعمولة","stem":"الشخص الذي يقوم بشراء سلعة باسمه الخاص من تاجر الجملة لحساب تاجر التجزئة يسمى:","options":["السمسار","الوسيط","الوكيل بالعمولة","وكيل عادي"],"answer":2,"why":"الوكيل بالعمولة يتصرف باسمه الشخصي لكن لحساب موكله مقابل عمولة — ومثال الشرائح بالحرف: يشتري سلعة من تاجر الجملة لحساب تاجر التجزئة. الكلمتين المفتاح: «باسمه الخاص» + «لحساب غيره».","wrong":[{"i":0,"mis":"l4.commission-vs-brokerage","note":"السمسار يقرّب بين الطرفين بس، وما يدخل طرف في العقد."},{"i":1,"mis":"gen.neighbor","note":"الوسيط مو مصطلح من المحاضرة."},{"i":3,"mis":"l4.commission-vs-agency","note":"الوكيل العادي يتصرف باسم موكله، مو باسمه الخاص."}],"tests":["الوكالة بالعمولة","الفرق عن السمسرة والوكالة العادية"]},{"n":808,"lo":"L5","sec":"LAW333-PRAC","type":"tf","topic":"المهن الحرة","stem":"سارة تعمل طبيبة في عيادتها الخاصة، وبسبب مهارتها يأتي إليها الكثير من المراجعين مما جعلها تحقق عوائد كثيرة. سارة اكتسبت صفة التاجر لأنها حققت أرباحاً.","options":["صح","خطأ"],"answer":1,"why":"خطأ. الطب مهنة حرة وعمل الطبيب مدني حتى لو ربح كثير — وهذا بالضبط نقد معيار المضاربة: الطبيب والمحامي يستهدفون الربح وأعمالهم مدنية. فسارة ليست تاجرة، وعيادتها ليست محلاً تجارياً.","wrong":[{"i":0,"mis":"l4.liberal-professions","note":"الربح وحده ما يصنع تاجر؛ المهن الحرة (طبيب، مهندس، محامي) أعمال مدنية."}],"tests":["المهن الحرة","نقد معيار المضاربة"]},{"n":809,"lo":"L4","sec":"LAW333-PRAC","type":"concept","topic":"مقاولة الصناعة","stem":"يعتبر من ضمن الأعمال التجارية:","options":["عمل المهندس الذي يقتصر على الإشراف الهندسي","النقل مقابل أجر ولو لمرة واحدة","مقاولة الصناعة بكافة أشكالها","أعمال سفن النزهة"],"answer":2,"why":"شريحة ٤: مختلف صور الصناعة (إنتاج، تحويل، إصلاح) أعمال تجارية متى تمت على وجه المقاولة — وهذا معنى «بكافة أشكالها».","wrong":[{"i":0,"mis":"l4.liberal-professions","note":"المهندس اللي يشرف بس يمارس مهنة حرة = عمل مدني."},{"i":1,"mis":"l4.single-vs-enterprise","note":"النقل تجاري بس إذا كان مقاولة (مشروع منظم مستمر)، مو مرة وحدة."},{"i":3,"mis":"gen.detail","note":"سفن النزهة للترفيه مو للمضاربة والربح، فما تكون عمل تجاري."}],"tests":["مقاولة الصناعة","شرط المقاولة"]}]};
